@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&family=Outfit:wght@300;400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;1,400;1,600&family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=Sora:wght@400;600;700;800&family=Space+Grotesk:wght@400;600;700&family=Syne:wght@400;600;700;800;900&display=swap');

:root {
  /* Light Theme Variables */
  --bg-primary: #ffffff;
  --bg-secondary: #f9f9f9;
  --bg-tertiary: #f1f1f1;
  --text-primary: #000000;
  --text-secondary: #555555;
  --text-tertiary: #8c8c8c;
  --border-color: #e5e5e5;
  --border-color-hover: #adadad;
  --accent-color: #000000;
  --accent-secondary: #262626;
  --accent-glow: rgba(0, 0, 0, 0.05);
  --card-shadow: 0 1px 3px rgba(0, 0, 0, 0.02), 0 1px 2px rgba(0, 0, 0, 0.04);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-display: 'Outfit', sans-serif;
  --ui-font-scale: 1;
  --ui-scale: 1;
  --transition-fast: 0.15s ease;
  --transition-medium: 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  --header-height: 64px;
  --sidebar-width: 76px;

  /* Theme-aware Heatmap Colors */
  --heatmap-level-0: #161b22;
  --heatmap-level-1: #0c4a6e;
  --heatmap-level-2: #0284c7;
  --heatmap-level-3: #38bdf8;
  --heatmap-level-4: #7dd3fc;
  --heatmap-glow: rgba(56, 189, 248, 0.45);
}

html, body {
  overflow-x: hidden !important;
  max-width: 100% !important;
  width: 100% !important;
  box-sizing: border-box !important;
}

*, *::before, *::after {
  box-sizing: border-box;
}

#root,
.app-container,
.app-main-wrapper,
.main-content {
  overflow-x: hidden !important;
  max-width: 100% !important;
  width: 100% !important;
  min-height: 100vh;
}

/* Hide native number spin buttons globally for sleek stepper & metric inputs */
input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

input[type="number"] {
  -moz-appearance: textfield;
  appearance: textfield;
}

body,
.app-container,
.main-content,
.app-header,
.settings-command-header,
.settings-sub-panel,
.theme-spotlight-card {
  transition: background-color 0.25s cubic-bezier(0.16, 1, 0.3, 1),
              border-color 0.25s ease,
              color 0.2s ease;
}

.app-container.sidebar-collapsed {
  --sidebar-width: 72px;
}

[data-theme="phosphor-crt"] {
  /* Phosphor CRT Matrix Theme Variables */
  --bg-primary: #05080a;
  --bg-secondary: #080d10;
  --bg-tertiary: #0e1713;
  --text-primary: #39ff7a;
  --text-secondary: #22c55e;
  --text-tertiary: #166534;
  --border-color: rgba(57, 255, 122, 0.24);
  --border-color-hover: rgba(57, 255, 122, 0.55);
  --accent-color: #39ff7a;
  --accent-secondary: #10b981;
  --accent-text: #05080a;
  --accent-glow: 0 0 16px rgba(57, 255, 122, 0.35);
  --card-shadow: 0 0 0 1px rgba(57, 255, 122, 0.22), 0 8px 24px rgba(0, 0, 0, 0.6);

  --heatmap-level-0: #080d10;
  --heatmap-level-1: #0e4429;
  --heatmap-level-2: #15803d;
  --heatmap-level-3: #22c55e;
  --heatmap-level-4: #39ff7a;
  --heatmap-glow: rgba(57, 255, 122, 0.6);
}

[data-theme="phosphor-crt"] .nav-link.active {
  background: #39ff7a !important;
  color: #05080a !important;
  font-weight: 700;
}

[data-theme="phosphor-crt"] .nav-link.active .nav-link-text,
[data-theme="phosphor-crt"] .nav-link.active .nav-icon {
  color: #05080a !important;
}

[data-theme="phosphor-crt"] .nav-link.active .nav-icon svg {
  stroke: #05080a !important;
}

