/* ========================================================
   5. DETAILED SYLLABUS INSPECTOR DRAWER / MODAL
   ======================================================== */
.blueprint-inspector-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(8px);
  z-index: 9999;
  display: flex;
  justify-content: flex-end;
  animation: fadeInOverlay 0.2s ease-out;
}

@keyframes fadeInOverlay {
  from { opacity: 0; }
  to { opacity: 1; }
}

.blueprint-inspector-drawer {
  width: 100%;
  max-width: 580px;
  height: 100%;
  max-height: 100vh;
  background: #0f172a;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: -10px 0 40px rgba(0, 0, 0, 0.6);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: slideInDrawer 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideInDrawer {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

.drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  gap: 14px;
  background: rgba(0, 0, 0, 0.2);
}

.drawer-header-left {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.drawer-week-number {
  font-size: 11px;
  font-weight: 800;
  color: #38bdf8;
  letter-spacing: 0.5px;
}

.drawer-title {
  font-size: 20px;
  font-weight: 800;
  color: #ffffff;
  margin: 0;
}

.drawer-phase-pill {
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
}

.drawer-header-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.drawer-status-select {
  padding: 6px 12px;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 800;
  outline: none;
  cursor: pointer;
}

.drawer-status-select.completed {
  background: rgba(34, 197, 94, 0.18);
  border: 1px solid rgba(34, 197, 94, 0.4);
  color: #4ade80;
}

.drawer-status-select.in-progress {
  background: rgba(245, 158, 11, 0.18);
  border: 1px solid rgba(245, 158, 11, 0.4);
  color: #fde047;
}

.drawer-status-select.not-started {
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #94a3b8;
}

.drawer-status-select option {
  background: #18191c;
  color: #ffffff;
}

.drawer-close-btn {
  background: rgba(255, 255, 255, 0.05);
