}

.section-sub-heading {
  font-size: 14px;
  font-weight: 800;
  color: #ffffff;
  margin: 0 0 4px 0;
}

.section-sub-desc {
  font-size: 12px;
  color: #94a3b8;
  margin: 0 0 14px 0;
}

.checklist-subject-group {
