   RESPONSIVE ADJUSTMENTS FOR STUDY PLAN
   ======================================================== */
@media (max-width: 768px) {
  .plan-expedition-hero {
    padding: 20px;
    gap: 16px;
  }

  .expedition-headline {
    font-size: 26px;
  }

  .expedition-hud-card {
    min-width: 100%;
  }

  .expedition-nav-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .expedition-tools-right {
    justify-content: space-between;
  }

  .expedition-search-box {
    flex: 1;
    width: auto;
  }

  .expedition-search-box:focus-within {
    width: auto;
  }

  .expedition-dossier-grid {
    grid-template-columns: 1fr;
  }

  .roadmap-nodes-row {
    grid-template-columns: 1fr;
  }

  .blueprint-inspector-drawer {
    max-width: 100%;
  }

  .blueprint-table-container {
    overflow-x: auto;
  }

  .blueprint-table {
    min-width: 600px;
  }
}


/* Daily Tracker Layout */
