}

.tracker-tab {
  background: none;
  border: none;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 4px 12px;
  border-radius: var(--radius-sm);
  transition: var(--transition-fast);
}

.tracker-tab:hover {
  color: var(--text-primary);
}

.tracker-tab.active {
  background-color: var(--accent-color);
  color: var(--bg-primary);
}

.tracker-subtabs-row {
  display: flex;
  gap: 6px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.tracker-subtab {
  background: none;
  border: 1px solid var(--border-color);
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  transition: var(--transition-fast);
}

.tracker-subtab:hover {
  border-color: var(--border-color-hover);
  color: var(--text-primary);
}

.tracker-subtab.active {
  background-color: var(--text-primary);
  color: var(--bg-primary);
  border-color: var(--text-primary);
}

/* ========================================================
   CLEAN & MINIMAL DAILY DRILL & TELEMETRY HUB
   ======================================================== */
.minimal-daily-hub {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 1320px;
  margin: 0 auto;
  width: 100%;
  padding-bottom: 60px;
}

/* 1. Compact Header Strip */
.minimal-header-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding-bottom: 2px;
}

.minimal-header-left {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.minimal-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--accent-color, #38bdf8);
}

.minimal-ping {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #38bdf8;
  box-shadow: 0 0 8px #38bdf8;
  animation: radarPulse 1.6s infinite;
}

.minimal-title {
  font-family: 'Syne', var(--font-display), sans-serif;
  font-size: clamp(22px, 3.2vw, 32px);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: #ffffff;
  margin: 0;
}

.minimal-title-italic {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-weight: 400;
  text-transform: none;
  color: var(--accent-color, #38bdf8);
}

.minimal-actions-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.minimal-sync-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 700;
  color: #64748b;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.08);
  padding: 5px 8px;
  border-radius: 7px;
}

.sync-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}
.sync-dot.synced { background: #10b981; box-shadow: 0 0 6px #10b981; }
.sync-dot.syncing { background: #fbbf24; animation: radarPulse 1s infinite; }
.sync-dot.ready { background: #38bdf8; }

.minimal-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 12px;
  border-radius: 7px;
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.minimal-btn.outline {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #cbd5e1;
}

.minimal-btn.outline:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

.minimal-btn.accent {
  background: #ffffff;
  color: #04101e;
  border: 1px solid #ffffff;
  box-shadow: 0 2px 8px rgba(255, 255, 255, 0.15);
}

.minimal-btn.accent:hover {
  background: #f1f5f9;
  transform: translateY(-1px);
}

/* ========================================================
   2. CONSOLIDATED NAVIGATOR BAR
   ======================================================== */
.unified-nav-strip {
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

@media (min-width: 960px) {
  .unified-nav-strip {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
  }
}

.nav-period-group {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
  max-width: 100%;
}

.nav-period-group::-webkit-scrollbar {
  display: none;
}

.period-pills-row {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}

.period-pill {
  padding: 4px 9px;
  border-radius: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 700;
  color: #64748b;
  background: transparent;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.period-pill:hover {
  color: #cbd5e1;
  background: rgba(255, 255, 255, 0.04);
}

.period-pill.active {
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
  border-color: rgba(56, 189, 248, 0.3);
}

.period-pill.week.active {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.2);
}

.nav-pipe {
  width: 1px;
  height: 18px;
  background: rgba(255, 255, 255, 0.1);
  flex-shrink: 0;
}

/* 7-Day Mini Track Grid */
.mini-day-track {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
  width: 100%;
}

@media (min-width: 960px) {
  .mini-day-track {
    width: auto;
    display: flex;
    gap: 5px;
  }
}

.mini-day-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 5px 2px;
  min-width: 0;
  width: 100%;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.06);
  cursor: pointer;
  transition: all 0.15s ease;
}

@media (min-width: 960px) {
  .mini-day-pill {
    padding: 5px 8px;
    min-width: 44px;
    width: auto;
  }
}

.mini-day-pill:hover {
  border-color: rgba(255, 255, 255, 0.2);
}

.mini-day-pill.selected {
  background: rgba(56, 189, 248, 0.14);
  border-color: rgba(56, 189, 248, 0.4);
}

.mini-day-pill.is-today {
  border-color: rgba(245, 158, 11, 0.45);
}

.mini-day-name {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  color: #ffffff;
  text-align: center;
  line-height: 1;
}

.mini-day-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #475569;
}
.mini-day-dot.some { background: #38bdf8; }
.mini-day-dot.all { background: #10b981; }

.mini-day-hrs {
  font-family: 'JetBrains Mono', monospace;
  font-size: 8px;
  color: #94a3b8;
  line-height: 1;
}

/* ========================================================
   3. CLEAN 2-COLUMN WORKSPACE
   ======================================================== */
.clean-workspace-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 16px;
  align-items: start;
}

/* LEFT COLUMN: DRILLS & RETROSPECTIVE */
.workspace-main-col {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}

.day-overview-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  padding-bottom: 8px;
  gap: 10px;
}

.day-title-block {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.day-title-inline {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}

.selected-day-heading {
  font-family: 'Syne', var(--font-display), sans-serif;
  font-size: clamp(18px, 3.5vw, 22px);
  font-weight: 900;
  color: #ffffff;
  margin: 0;
  line-height: 1.1;
  white-space: nowrap;
}

.selected-date-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: #64748b;
  white-space: nowrap;
}

.today-live-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 8px;
  font-weight: 900;
  color: #fbbf24;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.3);
  padding: 1px 5px;
  border-radius: 3px;
}

.day-syllabus-subtitle {
  font-size: 11px;
  color: #94a3b8;
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.day-overview-right-cluster {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.daily-stamp-rally-card-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  border-radius: 8px;
  background: rgba(239, 68, 68, 0.08);
  border: 1px solid rgba(239, 68, 68, 0.28);
  color: #f87171;
  cursor: pointer;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  text-decoration: none;
}

.daily-stamp-rally-card-btn:hover {
  background: rgba(239, 68, 68, 0.18);
  border-color: rgba(239, 68, 68, 0.55);
  box-shadow: 0 0 14px rgba(239, 68, 68, 0.28);
  transform: translateY(-1px);
}

.stamp-card-icon-circle {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #f87171;
  flex-shrink: 0;
}

.stamp-card-btn-content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
  line-height: 1.15;
}

.stamp-card-btn-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: #f87171;
}

.stamp-card-btn-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 700;
  color: #ffffff;
}

.day-quota-tally {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex-shrink: 0;
  text-align: right;
}

.tally-score {
  font-family: 'Syne', var(--font-display), sans-serif;
  font-size: 16px;
  font-weight: 900;
  color: #ffffff;
  line-height: 1.1;
  white-space: nowrap;
}

.tally-score.all-done {
  color: #34d399;
}

.tally-label {
  font-size: 10px;
  color: #64748b;
  font-family: 'JetBrains Mono', monospace;
  white-space: nowrap;
}

@media (max-width: 640px) {
  .day-overview-header {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
  }
  .day-overview-right-cluster {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
  }
}

/* The 3 Drill Cards (Uniform 2-Row Layout) */
.drills-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.drill-item-card {
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: all 0.15s ease;
}

.drill-item-card:hover {
  border-color: rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.02);
}

.drill-item-card.quant { border-left: 3px solid #38bdf8; }
.drill-item-card.lrdi { border-left: 3px solid #c084fc; }
.drill-item-card.varc { border-left: 3px solid #fbbf24; }
.drill-item-card.custom { border-left: 3px solid var(--accent-color, #38bdf8); }

.drill-item-card.done {
  background: linear-gradient(90deg, rgba(16, 185, 129, 0.07) 0%, rgba(15, 23, 42, 0.5) 100%);
  border-left-color: #10b981;
}

.drill-card-top-row {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
}

.drill-check-bubble {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.4);
  border: 1.5px solid rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: transparent;
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.15s ease;
}

.drill-check-bubble:hover {
  border-color: #10b981;
}

.drill-check-bubble.checked {
  background: #10b981;
  border-color: #10b981;
  color: #04101e;
  box-shadow: 0 0 10px rgba(16, 185, 129, 0.4);
}

.drill-subject-heading-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  min-width: 0;
  flex-wrap: wrap;
}

.drill-subject-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  font-weight: 900;
  padding: 1px 6px;
  border-radius: 4px;
  flex-shrink: 0;
}

.drill-subject-badge.quant { color: #38bdf8; background: rgba(56, 189, 248, 0.15); }
.drill-subject-badge.lrdi { color: #c084fc; background: rgba(192, 132, 252, 0.15); }
.drill-subject-badge.varc { color: #fbbf24; background: rgba(251, 191, 36, 0.15); }
.drill-subject-badge.custom { color: #f59e0b; background: rgba(245, 158, 11, 0.15); border: 1px solid rgba(245, 158, 11, 0.3); }

.drill-subject-title {
  font-size: 13px;
  font-weight: 800;
  color: #ffffff;
  white-space: nowrap;
}

.drill-timer-pill {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: #34d399;
  white-space: nowrap;
}

.drill-timer-pill.custom {
  color: #fbbf24;
}

.drill-card-bottom-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-left: 36px;
}

@media (max-width: 640px) {
  .drill-card-bottom-row {
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 8px !important;
    padding-left: 0 !important;
  }
  .drill-target-col {
    width: 100% !important;
  }
  .drill-curriculum-pill {
    white-space: normal !important;
    word-break: break-word !important;
    line-height: 1.4 !important;
  }
  .drill-target-text {
    white-space: normal !important;
    word-break: break-word !important;
    line-height: 1.35 !important;
  }
  .drill-stepper-compact {
    width: 100% !important;
    justify-content: space-between !important;
    margin-top: 4px !important;
    padding-top: 8px !important;
    border-top: 1px dashed rgba(255, 255, 255, 0.08) !important;
  }
}

.drill-target-text {
  font-size: 11px;
  color: #94a3b8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
}

/* Minimal Stepper */
.drill-stepper-compact {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.stepper-subtext {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: #64748b;
  white-space: nowrap;
}

.stepper-buttons-wrap {
  display: flex;
  align-items: center;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 6px;
}

.step-btn {
  background: transparent;
  border: none;
  color: #cbd5e1;
  font-size: 13px;
  font-weight: 800;
  width: 22px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.step-btn:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.08);
}

.step-input {
  width: 32px;
  text-align: center;
  background: transparent;
  border: none;
  color: #ffffff;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 800;
  outline: none;
  -moz-appearance: textfield;
  appearance: textfield;
}

.step-input::-webkit-outer-spin-button,
.step-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
  display: none;
}

/* Add Custom Objective Button & Card */
.add-custom-objective-card {
  margin-top: 2px;
}

.add-custom-objective-btn {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.02);
  border: 1.5px dashed var(--accent-color, #38bdf8);
  border-radius: 10px;
  color: #f4f4f5;
  cursor: pointer;
  text-align: left;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  opacity: 0.9;
}

.add-custom-objective-btn:hover {
  background: rgba(var(--accent-rgb, 56, 189, 248), 0.08);
  border-color: var(--accent-color, #38bdf8);
  transform: translateY(-1px);
  box-shadow: 0 4px 20px var(--accent-glow, rgba(56, 189, 248, 0.2));
  opacity: 1;
}

.add-custom-btn-icon {
  width: 28px;
  height: 28px;
  border-radius: 7px;
  background: rgba(var(--accent-rgb, 56, 189, 248), 0.15);
  color: var(--accent-color, #38bdf8);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.2s ease;
}

.add-custom-objective-btn:hover .add-custom-btn-icon {
  transform: scale(1.08) rotate(90deg);
  background: var(--accent-color, #38bdf8);
  color: var(--accent-contrast, #09090b);
}

.add-custom-btn-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.add-custom-btn-title {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--accent-color, #38bdf8);
}

.add-custom-btn-sub {
  font-size: 10.5px;
  color: #a1a1aa;
}

.add-custom-pill {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  padding: 3px 9px;
  background: rgba(var(--accent-rgb, 56, 189, 248), 0.12);
  border: 1px solid var(--accent-color, #38bdf8);
  border-radius: 5px;
  color: var(--accent-color, #38bdf8);
  flex-shrink: 0;
  transition: all 0.2s ease;
}

.add-custom-objective-btn:hover .add-custom-pill {
  background: var(--accent-color, #38bdf8);
  color: var(--accent-contrast, #09090b);
}

/* Smooth Text Inputs with Quick Clear */
.smooth-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
}

.smooth-text-input {
  width: 100%;
  background: rgba(10, 15, 29, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  padding: 8px 32px 8px 12px;
  font-size: 13px;
  color: #f8fafc;
  outline: none;
  font-family: inherit;
  transition: border-color 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s cubic-bezier(0.16, 1, 0.3, 1), background 0.2s ease;
}

.smooth-text-input:focus {
  border-color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 0 2.5px rgba(var(--accent-rgb, 56, 189, 248), 0.2), 0 0 16px rgba(var(--accent-rgb, 56, 189, 248), 0.15);
  background: rgba(15, 23, 42, 0.9);
}

.smooth-text-input::placeholder {
  color: #64748b;
  font-size: 12px;
}

.smooth-input-clear-btn {
  position: absolute;
  right: 7px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.08);
  color: #94a3b8;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
  padding: 0;
}

.smooth-input-clear-btn:hover {
  background: rgba(239, 68, 68, 0.25);
  color: #ef4444;
  transform: translateY(-50%) scale(1.12);
}

/* Clean Day Reflection & Mistake Notes */
.clean-notes-card {
  background: rgba(15, 23, 42, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.notes-card-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.notes-card-title {
  font-size: 12px;
  font-weight: 800;
  color: #ffffff;
  white-space: nowrap;
}

