}

.inspector-action-btn:hover {
  background: rgba(255, 255, 255, 0.12);
}

.inspector-body {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.inspector-title-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.inspector-mock-name {
  font-family: var(--font-sans);
  font-size: 20px;
  font-weight: 800;
  color: #ffffff;
  margin: 0;
