}

.inspector-meta-row {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  flex-wrap: wrap;
}

.status-pill {
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 4px;
}

.status-pill.Taken {
  color: #34d399;
  background: rgba(16, 185, 129, 0.12);
}

.status-pill.Scheduled {
  color: #fbbf24;
  background: rgba(245, 158, 11, 0.12);
}

.status-pill.Not\ Started,
.status-pill {
  color: #94a3b8;
  background: rgba(255, 255, 255, 0.05);
}

.date-tag {
  color: #64748b;
}

/* Results Deck */
.inspector-score-breakdown {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.composite-score-hero {
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 10px;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.composite-left {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.score-huge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 36px;
  font-weight: 800;
  color: #ffffff;
  line-height: 1;
}

.score-huge-lbl {
  font-size: 11px;
  color: #64748b;
  font-weight: 700;
}

.composite-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}

.percentile-highlight {
  font-family: var(--font-sans);
  font-size: 16px;
  font-weight: 800;
  color: #38bdf8;
}

.delta-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 3px;
}

.delta-tag.gain {
  color: #34d399;
  background: rgba(16, 185, 129, 0.15);
}

.delta-tag.drop {
  color: #f87171;
  background: rgba(239, 68, 68, 0.15);
}

/* Sectional Meters with Progress Bars */
.sectional-meters-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sec-meter-card {
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sec-meter-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.sec-name {
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 700;
  color: #cbd5e1;
}

.sec-points {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  font-weight: 800;
  color: #ffffff;
}

.sec-meter-track {
  height: 4px;
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
}

.sec-meter-fill {
  height: 100%;
  border-radius: 9999px;
  transition: width 0.3s ease;
}

.sec-meter-fill.qa { background: #38bdf8; }
.sec-meter-fill.dilr { background: #c084fc; }
.sec-meter-fill.varc { background: #fbbf24; }

/* Strategy Notes Card */
.strategy-notes-card {
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.strategy-notes-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: #64748b;
  text-transform: uppercase;
}

.strategy-notes-text {
  font-size: 12px;
  color: #cbd5e1;
  font-style: italic;
  margin: 0;
  line-height: 1.45;
}

/* Unattempted Empty State */
.inspector-pending-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
  padding: 32px 16px;
  background: rgba(0, 0, 0, 0.25);
  border: 1px dashed rgba(255, 255, 255, 0.08);
  border-radius: 12px;
}

.pending-icon-circle {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
}

.pending-title {
  font-family: var(--font-sans);
  font-size: 15px;
  font-weight: 800;
  color: #ffffff;
  margin: 0;
}

.pending-desc {
  font-size: 12px;
  color: #64748b;
  margin: 0;
  line-height: 1.5;
  max-width: 320px;
}

.record-exam-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 7px;
  background: #38bdf8;
  color: #04101e;
  border: 1px solid #38bdf8;
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s ease;
  margin-top: 4px;
}

.record-exam-btn:hover {
  background: #7dd3fc;
}

/* ========================================================
   4. SCORE LOGGER MODAL
   ======================================================== */
.mock-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  z-index: 99999;
  padding: 24px 16px;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  box-sizing: border-box;
}

.mock-modal-box {
  background: #0b1120;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  width: 100%;
  margin: auto;
  max-width: 480px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
  animation: modalScale 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes modalScale {
  0% { transform: scale(0.95); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  padding-bottom: 12px;
}

.modal-title-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.modal-mock-id {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
  padding: 2px 6px;
  border-radius: 4px;
}

.modal-header h3 {
  font-family: var(--font-sans);
  font-size: 16px;
  font-weight: 800;
  color: #ffffff;
  margin: 0;
}

.modal-close-btn {
  background: transparent;
  border: none;
  color: #64748b;
  cursor: pointer;
  display: flex;
  align-items: center;
  padding: 4px;
}

.modal-close-btn:hover {
  color: #ffffff;
}

.modal-body-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.form-row {
  display: flex;
  gap: 10px;
}

.form-row.two-cols {
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.form-row.sectional-scores-row {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.form-field.full {
  width: 100%;
}

.form-field label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
}

.form-field input,
.form-field select,
.form-field textarea {
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 6px;
  padding: 7px 10px;
  color: #ffffff;
  font-family: var(--font-sans);
  font-size: 12px;
  outline: none;
  transition: border-color 0.15s ease;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: #38bdf8;
}

.modal-total-calc-banner {
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.25);
  border-radius: 8px;
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  text-align: center;
}

.calc-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  font-weight: 700;
  color: #64748b;
  display: block;
}

.calc-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 18px;
  font-weight: 800;
  color: #ffffff;
  line-height: 1.1;
  margin-top: 2px;
}

.calc-val.accent {
  color: #38bdf8;
}

.modal-footer-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 12px;
  margin-top: 4px;
}

.btn-cancel {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #cbd5e1;
  padding: 7px 14px;
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-cancel:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #ffffff;
}

.btn-save {
  background: #38bdf8;
  color: #04101e;
  border: 1px solid #38bdf8;
  padding: 7px 16px;
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-save:hover {
  background: #7dd3fc;
}

/* Error Log Aggregator View */
.filter-row {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.filter-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.filter-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-secondary, #cbd5e1);
}

.filter-select {
  padding: 8px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: var(--bg-secondary);
  color: #ffffff;
  font-size: 13px;
  min-width: 120px;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.filter-select:hover:not(:disabled) {
  border-color: rgba(56, 189, 248, 0.4);
  background-color: rgba(30, 41, 59, 0.85);
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.15);
}

.filter-select:focus {
  outline: none;
  border-color: var(--accent-color);
  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.25);
}

.filter-input {
  padding: 8px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: var(--bg-secondary);
  color: #ffffff;
  font-size: 13px;
}

.filter-input::placeholder {
  color: #94a3b8;
}

.filter-input:focus {
  outline: none;
  border-color: var(--accent-color);
}

.error-logs-container {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.error-log-item {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--card-shadow);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.error-log-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 8px;
}

.error-log-meta {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  color: var(--accent-color, #38bdf8);
  font-weight: 700;
}

.error-log-content {
  font-size: 13px;
  line-height: 1.5;
  white-space: pre-wrap;
}

/* Utilities */
.progress-ring {
  transform: rotate(-90deg);
  transform-origin: 50% 50%;
}

.progress-ring-circle {
  transition: stroke-dashoffset 0.35s;
  stroke: var(--accent-color);
}

.progress-ring-bg {
  stroke: var(--bg-tertiary);
}

.empty-state {
  text-align: center;
  padding: 40px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-size: 14px;
}

/* Responsive Grid Adjustments */
@media (max-width: 1024px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .dashboard-details-row, .mocks-overview-row {
    grid-template-columns: 1fr;
  }
}

/* Mobile Screen Redesign */
@media (max-width: 768px) {
  /* Mobile GPU Acceleration & Zero Stutter Enhancements */
  * {
    -webkit-backdrop-filter: none !important;
    backdrop-filter: none !important;
  }

  .app-container {
    flex-direction: column;
    max-width: 100vw;
    overflow-x: hidden;
    min-height: 100vh;
  }
  
  .sidebar {
    display: none !important; /* Hide Sidebar completely on Mobile */
  }

  .app-main-wrapper {
    margin-left: 0 !important;
    width: 100% !important;
    max-width: 100vw !important;
    min-height: 100vh;
  }

  .global-header {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: space-between !important;
    height: auto !important;
    min-height: calc(52px + env(safe-area-inset-top, 0px)) !important;
    padding: max(env(safe-area-inset-top, 0px), 12px) 16px 12px 16px !important;
    background: var(--bg-secondary) !important;
    border-bottom: 1px solid var(--border-color) !important;
    position: sticky !important;
    top: 0 !important;
    z-index: 1000 !important;
    box-sizing: border-box !important;
  }

  .brand-logo-title {
    font-size: 17px !important;
  }

  .brand-logo-tracker-tag {
    display: none !important;
  }

  .header-title-divider,
  .header-title-badge,
  .desktop-only {
    display: none !important;
  }

  .header-profile-dropdown-menu {
    position: fixed !important;
    top: calc(max(env(safe-area-inset-top, 0px), 12px) + 54px) !important;
    right: 12px !important;
    left: 12px !important;
    width: auto !important;
    max-width: 340px !important;
    margin-left: auto !important;
    z-index: 9999 !important;
  }

  .study-timer-container {
    padding-top: 48px !important;
  }

  .header-progress-container {
    max-width: 120px;
    gap: 6px;
  }

  .header-progress-label {
    font-size: 10px;
  }

  .header-stats {
    gap: 6px;
    align-items: center;
  }

  .header-stat-item {
    padding: 4px 8px;
    font-size: 11px;
  }

  /* Hide header date widget on mobile header bar to prevent narrow multi-line wrapping */
  .date-header-item {
    display: none !important;
  }

  .header-row {
    flex-direction: column;
    align-items: stretch;
    gap: 14px;
    margin-bottom: 18px;
  }

  .page-title {
    font-size: 22px;
  }

  .header-title-row {
    flex-wrap: wrap;
    gap: 6px !important;
  }

  .header-actions {
    width: 100%;
    display: flex;
    flex-direction: row;
    gap: 8px;
  }

  .header-actions button,
  .jump-today-btn {
    flex: 1;
    width: 100%;
    justify-content: center;
    white-space: nowrap;
    text-align: center;
    font-size: 12px;
    padding: 10px 12px;
  }

  .today-header-badge {
    font-size: 11px;
    padding: 3px 8px;
    margin-top: 2px;
  }

  /* Dashboard Mobile Refinements */
  .dashboard-hero-header {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .hero-greeting {
    font-size: 20px;
  }

  .hero-action-buttons {
    width: 100%;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .hero-action-buttons button {
    flex: 1 1 calc(50% - 8px);
    min-width: 140px;
    justify-content: center;
    text-align: center;
    padding: 10px 12px;
    font-size: 12px;
  }

  .download-app-hero-btn {
    display: inline-flex !important;
    border-color: var(--accent-color);
  }

  .today-focus-card {
    flex-direction: column;
    align-items: stretch;
    padding: 16px;
    gap: 14px;
  }

  .focus-card-stats {
