/* Peer Inspector Modal Styles */
/* Modal Entrance Animation & Backdrop Glassmorphism */
@keyframes backdropFadeIn {
  from {
    opacity: 0;
    backdrop-filter: blur(0px);
  }
  to {
    opacity: 1;
    backdrop-filter: blur(12px);
  }
}

@keyframes modalCardEnter {
  from {
    opacity: 0;
    transform: scale(0.92) translateY(16px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  z-index: 1000;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding: 24px 16px;
  box-sizing: border-box;
  animation: backdropFadeIn 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.modal-card {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  width: 95%;
  max-width: 650px;
  max-height: calc(100vh - 48px);
  margin: auto;
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.6), 0 0 40px rgba(99, 102, 241, 0.15);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: modalCardEnter 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Smooth Click Active Scale for All Interactive Elements */
button, .btn-primary, .btn-secondary, .nav-link, .sidebar-toggle-btn, .tracker-tab, .tracker-subtab {
  transition: transform 0.15s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

button:active, .btn-primary:active, .btn-secondary:active, .nav-link:active, .sidebar-toggle-btn:active, .tracker-tab:active, .tracker-subtab:active {
  transform: scale(0.96) !important;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 12px;
  margin-bottom: 16px;
}

.modal-title {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
}

.modal-close-btn {
  background: none;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
