}

/* Global Scroll Optimizations */
html, body {
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
}

/* Minimalist Loading Screen Overlay */
.minimal-loader-screen {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: var(--bg-primary);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 9999;
}

.loader-logo {
