  animation: pulseLogo 1.5s infinite ease-in-out;
}

.loader-bar-container {
  width: 120px;
  height: 2px;
  background-color: var(--border-color);
  border-radius: 1px;
  position: relative;
  overflow: hidden;
  margin-bottom: 12px;
}

