/* ==========================================================================
   ANIMATED UI ICONS (ZERO EMOJIS - PURE VECTOR ANIMATIONS)
   ========================================================================== */

.animated-svg-flame {
  overflow: visible;
  filter: drop-shadow(0 2px 8px rgba(249, 115, 22, 0.5));
}

.flame-outer-path {
  transform-origin: center bottom;
  animation: flameSway 1.8s ease-in-out infinite alternate;
  will-change: transform;
  transform: translateZ(0);
}

.flame-inner-path {
  transform-origin: center bottom;
  animation: flameInnerFlicker 1.2s ease-in-out infinite alternate;
  will-change: transform;
  transform: translateZ(0);
}

.flame-spark-1 {
  animation: sparkDrift1 1.6s ease-out infinite;
}

.flame-spark-2 {
  animation: sparkDrift2 2s ease-out infinite 0.4s;
}

@keyframes flameSway {
  0% { transform: scale(1) skewX(0deg); }
  50% { transform: scale(1.04, 0.97) skewX(2.5deg); }
  100% { transform: scale(0.98, 1.03) skewX(-2deg); }
}

@keyframes flameInnerFlicker {
  0% { opacity: 0.8; transform: scale(0.95); }
  100% { opacity: 1; transform: scale(1.05); }
}

@keyframes sparkDrift1 {
  0% { transform: translate(0, 0); opacity: 1; }
  100% { transform: translate(3px, -8px); opacity: 0; }
}

@keyframes sparkDrift2 {
  0% { transform: translate(0, 0); opacity: 1; }
  100% { transform: translate(-3px, -9px); opacity: 0; }
}

.animated-svg-warning {
  overflow: visible;
}

.animated-svg-warning .warning-hex-pulse {
  animation: hexGlowPulse 2s infinite ease-in-out;
}

.animated-svg-warning .warning-dot-blink {
  animation: dotBlink 1.4s infinite ease-in-out;
}

@keyframes hexGlowPulse {
  0%, 100% { opacity: 0.9; stroke-width: 1.8; }
  50% { opacity: 0.5; stroke-width: 2.2; }
}

@keyframes dotBlink {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(0.7); opacity: 0.5; }
}

.animated-svg-paw {
  overflow: visible;
  transform-origin: bottom center;
  animation: pawBeckon 2s ease-in-out infinite alternate;
}

@keyframes pawBeckon {
  0% { transform: rotate(0deg); }
  50% { transform: rotate(-10deg) translateY(-2px); }
  100% { transform: rotate(4deg); }
}

.animated-svg-tear {
  overflow: visible;
}

.animated-svg-tear .tear-drop-flow {
  animation: tearDripGleam 2.2s infinite ease-in;
}

@keyframes tearDripGleam {
  0% { transform: translateY(0); opacity: 0.6; }
  50% { opacity: 1; }
  100% { transform: translateY(3px); opacity: 0.8; }
}

.animated-svg-target .target-ring-outer {
  transform-origin: center;
  animation: radarSpin 4s linear infinite;
}

@keyframes radarSpin {
  0% { stroke-dasharray: 6 3; transform: rotate(0deg); }
  100% { stroke-dasharray: 6 3; transform: rotate(360deg); }
}

