/* Animated SVG Equalizer Waveform */
.animated-svg-audio-bars {
  overflow: visible;
}

.animated-svg-audio-bars.is-playing .audio-bar-1 {
  animation: audioBarAnim 0.7s ease-in-out infinite alternate;
  transform-origin: 3.9px 19px;
}

.animated-svg-audio-bars.is-playing .audio-bar-2 {
  animation: audioBarAnim 0.5s ease-in-out infinite alternate 0.15s;
  transform-origin: 8.4px 19px;
}

.animated-svg-audio-bars.is-playing .audio-bar-3 {
  animation: audioBarAnim 0.85s ease-in-out infinite alternate 0.05s;
  transform-origin: 12.9px 19px;
}

.animated-svg-audio-bars.is-playing .audio-bar-4 {
  animation: audioBarAnim 0.6s ease-in-out infinite alternate 0.25s;
  transform-origin: 17.4px 19px;
}

.animated-svg-audio-bars.is-playing .audio-bar-5 {
  animation: audioBarAnim 0.75s ease-in-out infinite alternate 0.1s;
  transform-origin: 21.9px 19px;
}

@keyframes audioBarAnim {
  0% { transform: scaleY(0.35); }
  100% { transform: scaleY(1.2); }
}

