  text-transform: uppercase;
}

.comic-speech-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 2px;
}

.comic-dialogue {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 12.5px;
  font-weight: 700;
