  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: var(--accent-color);
}


/* Comic Edge Peek Stance (Paws & Ears with "Will you continue?") */
.comic-edge-peek-container {
  position: fixed;
  right: 20px;
  bottom: 0px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  pointer-events: auto;
  animation: peekSlideUp 0.35s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes peekSlideUp {
  0% { transform: translateY(40px); opacity: 0; }
  100% { transform: translateY(0); opacity: 1; }
}

.comic-peek-dialogue-bubble {
  position: relative;
  background: var(--bg-primary, rgba(15, 23, 42, 0.96));
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--accent-color, #38bdf8);
  border-radius: 16px;
  padding: 12px 14px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.6), 0 0 20px var(--accent-glow, rgba(56, 189, 248, 0.25));
