  margin-bottom: 2px;
}

.comic-peek-bubble-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.comic-peek-title {
  font-family: var(--font-display, 'Syne', sans-serif);
  font-size: 13.5px;
  font-weight: 800;
  color: var(--accent-color, #38bdf8);
  letter-spacing: -0.01em;
}

.comic-peek-close-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-size: 16px;
  cursor: pointer;
  padding: 0;
  line-height: 1;
}

.comic-peek-close-btn:hover {
  color: var(--text-primary);
}

.comic-peek-subtitle {
  font-family: var(--font-sans);
  font-size: 11px;
  color: var(--text-secondary);
  margin: 4px 0 10px 0;
  line-height: 1.35;
}

.comic-peek-btn-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.comic-peek-continue-btn {
  flex: 1;
  padding: 6px 12px;
  border-radius: 20px;
  background: var(--accent-color, #38bdf8);
  color: #000000;
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 700;
  border: none;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
  transition: transform 0.15s ease;
}

.comic-peek-continue-btn:hover {
  transform: translateY(-1px);
}

.comic-peek-cancel-btn {
  padding: 6px 10px;
  border-radius: 20px;
  background: var(--bg-tertiary, rgba(255, 255, 255, 0.08));
  color: var(--text-secondary);
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 600;
  border: 1px solid var(--border-color);
  cursor: pointer;
}

.comic-peek-bubble-tail {
  position: absolute;
  bottom: -6px;
  right: 50px;
  width: 10px;
  height: 10px;
  background: var(--bg-primary, rgba(15, 23, 42, 0.96));
  border-right: 1px solid var(--accent-color, #38bdf8);
  border-bottom: 1px solid var(--accent-color, #38bdf8);
  transform: rotate(45deg);
}

.comic-ears-paws-peek-body {
  width: 120px;
  height: 72px;
  cursor: pointer;
  pointer-events: auto;
  filter: drop-shadow(0 4px 12px rgba(0, 0, 0, 0.5));
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.comic-ears-paws-peek-body:hover {
  transform: translateY(-4px);
}

.cat-ears-paws-svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

@media (max-width: 768px) {
  .comic-edge-peek-container {
    right: 12px;
    bottom: calc(70px + max(8px, env(safe-area-inset-bottom, 8px)));
  }
  .comic-peek-dialogue-bubble {
    max-width: 190px;
    padding: 10px 12px;
  }
  .comic-ears-paws-peek-body {
    width: 105px;
    height: 64px;
  }
}

