  padding: 6px 12px;
  border-radius: 20px;
  font-size: 11.5px;
  font-weight: 700;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.zen-fullscreen-trigger-btn:hover,
.zen-fullscreen-trigger-btn.active {
  background: var(--accent-gradient-subtle, rgba(56, 189, 248, 0.15));
  border-color: var(--accent-color, #38bdf8);
