  color: #ef4444;
  border-color: rgba(239, 68, 68, 0.3);
}

/* Fullscreen Immersion Mode */
.study-timer-minimal-container.zen-fullscreen-mode {
  position: fixed !important;
  inset: 0 !important;
  top: 0 !important;
  left: 0 !important;
  width: 100vw !important;
