}

.theme-svg-art {
  width: 100%;
  height: 100%;
}

/* Unique Theme Artwork Keyframe Animations */
.olive-anim {
  animation: oliveSway 2.4s ease-in-out infinite alternate;
  transform-origin: 20px 80px;
}

@keyframes oliveSway {
  0% { transform: rotate(-6deg) scale(0.96); }
  50% { transform: rotate(5deg) scale(1.04); }
  100% { transform: rotate(-2deg) scale(1); }
}

.plum-anim {
  animation: plumPulse 2s ease-in-out infinite;
}

@keyframes plumPulse {
  0% { transform: scale(0.92) rotate(0deg); filter: drop-shadow(0 0 2px rgba(170, 84, 130, 0.4)); }
  50% { transform: scale(1.08) rotate(4deg); filter: drop-shadow(0 0 10px rgba(170, 84, 130, 0.9)); }
  100% { transform: scale(0.92) rotate(0deg); filter: drop-shadow(0 0 2px rgba(170, 84, 130, 0.4)); }
}

.terracotta-anim {
  animation: terracottaRise 2.2s ease-in-out infinite alternate;
}

@keyframes terracottaRise {
  0% { transform: translateY(3px) scale(0.96); }
  100% { transform: translateY(-3px) scale(1.04); }
}

.crimson-anim {
  animation: crimsonPulse 1.8s ease-in-out infinite;
}

@keyframes crimsonPulse {
  0%, 100% { transform: scale(0.95); filter: drop-shadow(0 0 3px rgba(201, 24, 59, 0.4)); }
  50% { transform: scale(1.06); filter: drop-shadow(0 0 12px rgba(201, 24, 59, 0.8)); }
}

.sage-anim {
  animation: sageFloat 2s ease-in-out infinite alternate;
}

@keyframes sageFloat {
  0% { transform: rotate(-4deg) translateY(2px); }
  100% { transform: rotate(4deg) translateY(-2px); }
}

.slate-anim {
  animation: slateSlide 2.5s ease-in-out infinite alternate;
}

@keyframes slateSlide {
  0% { transform: translateY(2px) scale(0.98); }
  100% { transform: translateY(-2px) scale(1.02); }
}

