  }
}

/* ==========================================================================
   Real Peer Study Lounge (Rich CAT Aspirant Profile Cards)
   ========================================================================== */

.peer-lounge-container {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: border-color var(--transition-medium);
}

.peer-lounge-container.compact-lounge {
  margin-top: 24px;
}

.peer-lounge-header {
  padding: 16px 20px;
  background: var(--bg-tertiary);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
}

.lounge-header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.lounge-icon-bubble {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: rgba(99, 102, 241, 0.15);
  color: var(--accent-color);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--border-color);
}

.peer-lounge-title {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.2px;
}

.peer-lounge-subtitle {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-top: 1px;
}

.live-pulse-dot {
  width: 7px;
  height: 7px;
  background-color: #22c55e;
  border-radius: 50%;
  box-shadow: 0 0 8px #22c55e;
  animation: livePeerPulse 1.5s infinite ease-in-out;
}

@keyframes livePeerPulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.3); opacity: 0.5; }
}

.peer-search-container {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  padding: 6px 12px;
  border-radius: 20px;
  transition: var(--transition-fast);
}

.peer-search-container:focus-within {
  border-color: var(--accent-color);
}

.peer-search-container svg {
  color: var(--text-tertiary);
}

.peer-search-input {
  background: transparent;
  border: none;
  outline: none;
  font-size: 12px;
  color: var(--text-primary);
  width: 140px;
}

.peer-search-input::placeholder {
  color: var(--text-tertiary);
}

.peer-lounge-body {
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  max-height: 540px;
  overflow-y: auto;
}

.lounge-category-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.category-section-title {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--text-tertiary);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2px;
}

.peer-cards-grid {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Rich Peer Profile Cards */
.peer-profile-card {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: all var(--transition-fast);
  position: relative;
}

.peer-profile-card.self-profile-card {
  border-left: 4px solid var(--accent-color);
  background: linear-gradient(135deg, var(--bg-primary) 0%, rgba(99, 102, 241, 0.04) 100%);
}

.peer-profile-card.studying-card {
  border-left: 4px solid #22c55e;
}

.peer-profile-card.online-card {
  border-left: 4px solid var(--border-color-hover);
  padding: 12px 16px;
}

.peer-profile-card.clickable {
  cursor: pointer;
}

.peer-profile-card.clickable:hover {
  border-color: var(--accent-color);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
}

.peer-card-top-row {
  display: flex;
  align-items: center;
  gap: 12px;
  position: relative;
}

.peer-avatar-wrapper {
  position: relative;
  flex-shrink: 0;
}

.peer-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  color: #ffffff;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
}

.peer-avatar.self-avatar {
  background: var(--accent-color);
  color: var(--accent-text, #000);
}

.peer-status-indicator {
  position: absolute;
  bottom: -1px;
  right: -1px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--bg-primary);
}

.peer-status-indicator.studying {
  background-color: #22c55e;
  box-shadow: 0 0 6px rgba(34, 197, 94, 0.8);
  animation: peerStudyingRipple 2s infinite ease-in-out;
}

@keyframes peerStudyingRipple {
  0% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7); }
  70% { box-shadow: 0 0 0 6px rgba(34, 197, 94, 0); }
  100% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0); }
}

.peer-status-indicator.online {
  background-color: #22c55e;
}

.peer-identity-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex-grow: 1;
}

.peer-name-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.peer-fullname {
  font-size: 14px;
  font-weight: 800;
  color: var(--text-primary);
  font-family: var(--font-display);
}

.peer-tag {
  font-size: 9px;
  font-weight: 800;
  padding: 1px 6px;
  border-radius: 4px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.peer-tag.you-tag {
  background: var(--accent-color);
  color: var(--accent-text, #000);
}

.peer-streak-badge {
  font-size: 11px;
  font-weight: 700;
  color: #f59e0b;
  background: rgba(245, 158, 11, 0.12);
  border: 1px solid rgba(245, 158, 11, 0.25);
  padding: 1px 6px;
  border-radius: 12px;
}

.peer-status-sub {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
}

.inspect-peer-cta {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 14px;
  cursor: pointer;
  transition: all var(--transition-fast);
  margin-left: auto;
  flex-shrink: 0;
}

.inspect-peer-cta:hover {
  background: var(--accent-color);
  color: var(--accent-text, #000);
  border-color: var(--accent-color);
}

/* Current Task Box inside Profile Card */
.peer-current-task-box {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.task-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.task-timer-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  padding: 2px 8px;
  border-radius: 12px;
}

.task-timer-chip.live {
  border-color: rgba(34, 197, 94, 0.4);
  color: #22c55e;
}

.chip-timer-icon {
  font-size: 11px;
}

.task-main-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.3;
}

.task-details-text {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
}

.peer-progress-inline {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  margin-top: 4px;
  padding-top: 6px;
  border-top: 1px solid var(--border-color);
}

.progress-inline-label {
  color: var(--text-tertiary);
  font-weight: 600;
}

.progress-inline-val {
  color: var(--text-primary);
  font-weight: 700;
}

.peer-activity-snippet {
  font-size: 12px;
  color: var(--text-secondary);
  background: var(--bg-secondary);
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  line-height: 1.4;
}

.snippet-subject {
  font-weight: 800;
  color: var(--accent-color);
  font-size: 11px;
}

/* Offline Peers Mini List */
.offline-peers-row-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

@media (max-width: 600px) {
  .offline-peers-row-list {
    grid-template-columns: 1fr;
  }
}

.offline-peer-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  transition: all var(--transition-fast);
  opacity: 0.7;
}

.offline-peer-chip.clickable {
  cursor: pointer;
}

.offline-peer-chip.clickable:hover {
  opacity: 1;
  border-color: var(--border-color-hover);
  background: var(--bg-tertiary);
}

.offline-avatar-mini {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.offline-meta-mini {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex-grow: 1;
}

.offline-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.offline-last-seen {
  font-size: 10px;
  color: var(--text-tertiary);
}

.offline-streak-mini {
  font-size: 10px;
  font-weight: 700;
  color: #f59e0b;
  margin-left: auto;
  flex-shrink: 0;
}

/* ==========================================================================
   Mobile Onboarding & Native Authentication View
   ========================================================================== */

.mobile-onboarding-wrapper {
  min-height: 100vh;
  width: 100vw;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px 16px;
  background: radial-gradient(circle at 50% 0%, var(--bg-secondary) 0%, var(--bg-primary) 100%);
  box-sizing: border-box;
}

.mobile-onboarding-card {
  width: 100%;
  max-width: 420px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.25);
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-sizing: border-box;
}

.mobile-onboarding-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.onboarding-logo-glow {
  width: 58px;
  height: 58px;
  border-radius: 16px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.onboarding-title {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.5px;
}

.onboarding-badge {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.8px;
  background: rgba(34, 197, 94, 0.15);
  color: #22c55e;
  border: 1px solid rgba(34, 197, 94, 0.3);
  padding: 2px 8px;
  border-radius: 10px;
  margin-top: 4px;
  margin-bottom: 10px;
}

.onboarding-subtext {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.4;
}

.onboarding-tab-toggle {
  display: flex;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  padding: 4px;
  border-radius: 12px;
}

.tab-toggle-btn {
  flex: 1;
  padding: 8px 12px;
  font-size: 12px;
  font-weight: 700;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  border-radius: 8px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.tab-toggle-btn.active {
  background: var(--accent-color);
  color: var(--accent-text, #000);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
}

.onboarding-error-box {
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #ef4444;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
}

.onboarding-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.onboarding-input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.onboarding-input-group label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.6px;
  color: var(--text-tertiary);
}

.input-with-icon {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  transition: border-color var(--transition-fast);
}

.input-with-icon:focus-within {
  border-color: var(--accent-color);
}

.input-with-icon svg {
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.input-with-icon input,
.onboarding-select {
  background: transparent;
  border: none;
  outline: none;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  width: 100%;
}

.onboarding-select option {
  background: var(--bg-secondary);
  color: var(--text-primary);
}

.onboarding-submit-btn {
  width: 100%;
  padding: 14px;
  font-size: 14px;
  font-weight: 800;
  border-radius: var(--radius-sm);
  margin-top: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
}

.onboarding-footer-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  border-top: 1px solid var(--border-color);
  padding-top: 14px;
}

.onboarding-guest-btn {
  background: transparent;
  border: none;
  color: var(--text-tertiary);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: color var(--transition-fast);
}

.onboarding-guest-btn:hover {
  color: var(--text-primary);
}

/* ==========================================================================
   Live Over-The-Air Update Toast Banner
   ========================================================================== */

.update-toast-banner {
  position: fixed;
  bottom: calc(76px + max(12px, env(safe-area-inset-bottom, 12px)));
  left: 50%;
  transform: translateX(-50%);
  width: calc(100% - 32px);
  max-width: 440px;
  background: var(--bg-secondary);
  border: 1px solid var(--accent-color);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  z-index: 1200;
  box-sizing: border-box;
}

.update-toast-content {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.update-toast-icon {
  font-size: 22px;
  flex-shrink: 0;
}

.update-toast-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.update-toast-title {
  font-size: 13px;
  font-weight: 800;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.update-toast-subtitle {
  font-size: 11px;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.update-toast-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.update-toast-btn-apply {
  background: var(--accent-color);
  color: var(--accent-text, #000);
  border: none;
  font-size: 11px;
  font-weight: 800;
  padding: 6px 12px;
  border-radius: 6px;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
  transition: transform var(--transition-fast);
}

.update-toast-btn-apply:active {
  transform: scale(0.96);
}

.update-toast-btn-dismiss {
  background: transparent;
  border: none;
  color: var(--text-tertiary);
  font-size: 14px;
  cursor: pointer;
  padding: 4px;
}

/* ========================================================
   COMMUNITY STUDY LOUNGE CHAT & PROFILE STYLES
   ======================================================== */

.community-chat-wrapper {
  display: flex;
  flex-direction: column;
  height: 480px;
  max-height: 70vh;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}

.community-chat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--bg-tertiary);
  border-bottom: 1px solid var(--border-color);
}

.chat-title-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.chat-live-pulse-icon {
  width: 10px;
  height: 10px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pulse-dot {
  width: 8px;
  height: 8px;
  background-color: #22c55e;
  border-radius: 50%;
  box-shadow: 0 0 8px #22c55e;
  animation: pulseLive 2s infinite;
}

@keyframes pulseLive {
  0% { transform: scale(0.9); opacity: 0.8; }
  50% { transform: scale(1.3); opacity: 1; box-shadow: 0 0 12px #22c55e; }
  100% { transform: scale(0.9); opacity: 0.8; }
}

.chat-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
}

.chat-subtitle {
  font-size: 11px;
  color: var(--text-secondary);
}

.chat-close-btn {
  background: transparent;
  border: none;
  color: var(--text-tertiary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-radius: 4px;
}

.chat-close-btn:hover {
  color: var(--text-primary);
  background: var(--bg-primary);
}

/* Tag Filter Bar */
.chat-tag-filter-bar {
  display: flex;
  gap: 6px;
  padding: 8px 12px;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.chat-tag-btn {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.chat-tag-btn:hover {
  border-color: var(--accent-color);
  color: var(--text-primary);
}

.chat-tag-btn.active {
  background: var(--accent-color);
  color: var(--accent-text, #fff);
  border-color: var(--accent-color);
}

/* Messages Container */
.chat-messages-container {
  flex: 1;
  overflow-y: auto;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--bg-primary);
}

.chat-empty-state {
  text-align: center;
  padding: 40px 16px;
  color: var(--text-tertiary);
}

.chat-empty-icon {
  font-size: 32px;
  margin-bottom: 8px;
}

.chat-empty-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.chat-empty-desc {
  font-size: 12px;
  color: var(--text-secondary);
  max-width: 320px;
  margin: 0 auto;
  line-height: 1.4;
}

/* Message Rows & Bubbles */
.chat-bubble-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  max-width: 85%;
}

.chat-bubble-row.self-row {
  align-self: flex-end;
  flex-direction: row;
}

.chat-avatar {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.chat-avatar.self-avatar {
  background-color: var(--accent-color);
}

.chat-message-bubble {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  border-top-left-radius: 2px;
  padding: 8px 12px;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
  min-width: 140px;
}

.chat-bubble-row.self-row .chat-message-bubble {
  border-radius: 12px;
  border-top-right-radius: 2px;
  background: var(--bg-tertiary);
  border-color: rgba(99, 102, 241, 0.3);
}

.chat-message-header {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}

.chat-sender-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.chat-self-badge {
  font-size: 9px;
  background: var(--accent-color);
  color: #fff;
  padding: 1px 4px;
  border-radius: 4px;
  font-weight: 800;
  margin-left: 2px;
}

.chat-location-tag {
  font-size: 10px;
  color: var(--text-secondary);
  background: var(--bg-primary);
  padding: 1px 5px;
  border-radius: 4px;
  border: 1px solid var(--border-color);
}

.chat-target-tag {
  font-size: 10px;
  color: var(--accent-color);
  font-weight: 600;
}

.chat-timestamp {
  font-size: 10px;
  color: var(--text-tertiary);
  margin-left: auto;
}

.chat-message-text {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.4;
  word-break: break-word;
}

.chat-message-footer {
  margin-top: 6px;
}

.chat-tag-pill {
  font-size: 9px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: uppercase;
}

.chat-tag-pill.tag-quant { background: rgba(59, 130, 246, 0.15); color: #3b82f6; }
.chat-tag-pill.tag-lrdi { background: rgba(236, 72, 153, 0.15); color: #ec4899; }
.chat-tag-pill.tag-varc { background: rgba(139, 92, 246, 0.15); color: #8b5cf6; }
.chat-tag-pill.tag-milestone { background: rgba(34, 197, 94, 0.15); color: #22c55e; }
.chat-tag-pill.tag-break { background: rgba(245, 158, 11, 0.15); color: #f59e0b; }

/* Quick Action Chips */
.chat-quick-chips-scroll {
  display: flex;
  gap: 6px;
  padding: 8px 12px;
  background: var(--bg-tertiary);
  border-top: 1px solid var(--border-color);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.quick-chip-btn {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 11px;
  padding: 4px 8px;
  border-radius: 12px;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.15s ease;
}

.quick-chip-btn:hover {
  background: var(--bg-primary);
  color: var(--text-primary);
  border-color: var(--accent-color);
}

/* Chat Input Bar */
.chat-input-form {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
}

.chat-text-input {
  flex: 1;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  font-size: 13px;
  padding: 10px 14px;
  border-radius: 20px;
  outline: none;
  transition: border-color 0.15s ease;
}

.chat-text-input:focus {
  border-color: var(--accent-color);
}

.chat-send-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--accent-color);
  color: #fff;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: transform 0.15s ease;
}

.chat-send-btn:hover:not(:disabled) {
  transform: scale(1.05);
}

.chat-send-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn-spinner {
  width: 14px;
  height: 14px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ========================================================
   STUDY LOUNGE TOGGLE BUTTONS & HIGH CONTRAST
   ======================================================== */
.lounge-toggle-button-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: #111214;
  padding: 4px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.lounge-toggle-nav-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  font-size: 12px;
  font-weight: 700;
  border-radius: 7px;
  border: none;
  cursor: pointer;
  background: transparent;
  color: #949ba4;
  transition: all 0.15s ease;
}

.lounge-toggle-nav-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
}

.lounge-toggle-nav-btn.active {
  background: #5865f2;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(88, 101, 242, 0.4);
}

/* ========================================================
   ASPIRANT PROFILE CARD (POPUP & PREVIEW)
   ======================================================== */
.profile-card-container {
  background: #23272a;
  border-radius: 16px;
  overflow: visible;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
