  background-size: cover;
  background-position: center;
  border-radius: 18px 18px 0 0;
}

.profile-card-banner-badge {
  position: absolute;
  top: 10px;
  right: 12px;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(8px);
  color: #dbdee1;
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  gap: 5px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.profile-card-body {
  padding: 0 16px 18px 16px;
  background: #23272a;
}

.profile-card-avatar-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-top: -40px;
  margin-bottom: 12px;
}

.profile-card-avatar-wrapper {
  border: 4px solid #23272a;
  border-radius: 50%;
  background: #23272a;
}

.profile-card-class-tag-bubble {
  background: rgba(30, 31, 34, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #dbdee1;
  border-radius: 14px;
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}

.profile-card-identity-section {
  margin-bottom: 14px;
}

.profile-card-display-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.profile-card-display-name {
  font-size: 20px;
  font-weight: 800;
  color: #ffffff;
  margin: 0;
  line-height: 1.2;
}

.profile-card-self-pill {
  font-size: 10px;
  font-weight: 800;
  background: var(--accent-color, #38bdf8);
  color: var(--accent-text, #060b14);
  padding: 2px 6px;
  border-radius: 4px;
}

.profile-card-handle-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: #949ba4;
