}

.profile-card-username {
  color: #dbdee1;
  font-weight: 600;
}

.profile-card-location {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #949ba4;
}

.profile-card-dot-separator {
  color: #4e5058;
}

.profile-card-actions-row {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}

.profile-card-action-btn {
  flex: 1;
  padding: 8px 14px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
}

.profile-card-action-btn.primary {
  background: var(--accent-color, #38bdf8);
  color: var(--accent-text, #060b14);
}

.profile-card-action-btn.primary:hover {
  opacity: 0.9;
}

.profile-card-card-divider,
.profile-card-divider {
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
  margin: 12px 0;
}

.profile-card-info-block {
  margin-bottom: 12px;
}

.profile-card-section-header {
  font-size: 11px;
  font-weight: 800;
  color: #b5bac1;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}

.profile-card-bio-text {
  background: #111214;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 13px;
  color: #dbdee1;
  line-height: 1.45;
}

.profile-card-stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.profile-card-stat-cell {
  background: #111214;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  padding: 8px 10px;
}

.profile-card-stat-title {
  font-size: 10px;
  font-weight: 700;
  color: #949ba4;
  display: flex;
  align-items: center;
  gap: 4px;
