}

.profile-card-journey-info {
  background: #111214;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 12px;
  color: #dbdee1;
}

.profile-card-journey-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Profile Split Grid */
.profile-customizer-split-grid {
  display: grid;
  grid-template-columns: minmax(320px, 1.2fr) minmax(300px, 1fr);
  gap: 24px;
  align-items: start;
}

@media (max-width: 860px) {
  .profile-customizer-split-grid {
    grid-template-columns: 1fr;
  }
}

.avatar-preset-picker-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(42px, 1fr));
