  border: 1px solid rgba(255, 255, 255, 0.08);
  padding: 4px;
  border-radius: 14px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  gap: 6px;
}

.profile-subtab-btn {
  flex: 1;
