  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 700;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: #94a3b8;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
}

.profile-subtab-btn:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.05);
}

.profile-subtab-btn.active {
  background: rgba(56, 189, 248, 0.12);
  color: var(--accent-color, #38bdf8);
  border-color: rgba(56, 189, 248, 0.3);
  box-shadow: 0 4px 14px rgba(56, 189, 248, 0.18);
}

.subtab-notification-badge {
  background: #ef4444;
  color: #ffffff;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 12px;
  line-height: 1;
  box-shadow: 0 0 8px rgba(239, 68, 68, 0.5);
  animation: pulseBadge 2s infinite ease-in-out;
}

.sidebar-nav-badge-pill {
  position: absolute;
  top: 8px;
  right: 12px;
  background: #ef4444;
  color: #ffffff;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 10px;
  line-height: 1;
  box-shadow: 0 0 8px rgba(239, 68, 68, 0.6);
  animation: pulseBadge 2s infinite ease-in-out;
}

@keyframes pulseBadge {
  0%, 100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.6);
  }
  50% {
    transform: scale(1.1);
    box-shadow: 0 0 0 4px rgba(239, 68, 68, 0);
  }
}

