  flex-direction: column;
}

.profile-center-card-wrap {
  display: flex;
  justify-content: center;
  width: 100%;
  padding: 10px 0;
}

.edit-profile-trigger-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  padding: 8px 16px;
