  .hub-mobile-tabs-bar {
    display: flex;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    padding: 8px 10px;
    gap: 6px;
    flex-shrink: 0;
  }

  .hub-mobile-tab-btn {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 7px 10px;
    border-radius: 8px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border-color);
    color: var(--text-secondary);
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .hub-mobile-tab-btn.active {
    background: var(--accent-color, #38bdf8);
    color: var(--accent-text, #060b14);
    border-color: transparent;
    box-shadow: 0 2px 8px rgba(56, 189, 248, 0.3);
  }

  .hub-channels-sidebar.mobile-inactive,
  .hub-chat-area.mobile-inactive,
  .hub-right-sidebar.mobile-inactive {
    display: none !important;
  }

  .hub-channels-sidebar.mobile-active,
  .hub-chat-area.mobile-active,
  .hub-right-sidebar.mobile-active {
    display: flex !important;
    height: 100%;
    flex: 1;
    min-height: 0;
  }
}

/* ========================================================
   LEFT: CHANNELS SIDEBAR
   ======================================================== */
.hub-channels-sidebar {
  width: 220px;
  min-width: 220px;
  max-width: 240px;
  background: #11141a;
  border-right: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  height: 100%;
}

.hub-server-header {
  padding: 14px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.hub-server-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.hub-server-icon-badge {
  font-size: 16px;
}

.hub-server-title {
  font-size: 14px;
  font-weight: 800;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hub-server-sub {
  font-size: 11px;
  color: #22c55e;
  font-weight: 700;
}

.hub-channels-list-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 12px 8px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hub-channel-category {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.hub-category-label {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--text-muted, #64748b);
  padding: 0 8px;
  margin-bottom: 4px;
  letter-spacing: 0.6px;
}

.hub-channel-btn {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: 6px;
  background: transparent;
  border: none;
  color: var(--text-secondary, #94a3b8);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
  transition: all 0.15s ease;
}

.hub-channel-btn:hover {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-primary, #ffffff);
}

.hub-channel-btn.active {
  background: rgba(56, 189, 248, 0.15);
  color: var(--accent-color, #38bdf8);
  font-weight: 700;
}

.hub-channel-hash {
  font-size: 15px;
  font-weight: 800;
  color: #64748b;
  font-family: monospace;
}

.hub-channel-btn.active .hub-channel-hash {
  color: var(--accent-color, #38bdf8);
}

.hub-channel-name {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hub-badge-count {
  font-size: 10px;
  font-weight: 800;
  background: rgba(56, 189, 248, 0.2);
  color: var(--accent-color, #38bdf8);
  padding: 1px 6px;
  border-radius: 10px;
}

.hub-empty-friends-hint {
  font-size: 11px;
  color: var(--text-muted, #64748b);
  padding: 6px 10px;
  font-style: italic;
}

/* ========================================================
   CENTER: MAIN CHAT AREA
   ======================================================== */
.hub-chat-area {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  background: var(--bg-primary);
  height: 100%;
}

.hub-chat-header-bar {
  height: 52px;
  padding: 0 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
  gap: 12px;
  flex-shrink: 0;
}

.hub-chat-header-info {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.hub-header-hash {
  font-size: 20px;
  font-weight: 800;
  color: var(--accent-color, #38bdf8);
  font-family: monospace;
}

.hub-header-channel-name {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
}

.hub-header-channel-desc {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hub-chat-header-stats {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  color: #22c55e;
  background: rgba(34, 197, 94, 0.1);
  border: 1px solid rgba(34, 197, 94, 0.25);
  padding: 4px 10px;
  border-radius: 12px;
  white-space: nowrap;
}

.hub-messages-container {
  flex: 1;
  overflow-y: auto;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hub-messages-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  margin: auto 0;
  padding: 30px 16px;
}

.hub-empty-icon-wrap {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: rgba(56, 189, 248, 0.15);
  color: var(--accent-color, #38bdf8);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
}

.hub-empty-title {
  font-size: 16px;
  font-weight: 800;
  color: #ffffff;
  margin: 0 0 6px 0;
}

.hub-empty-desc {
  font-size: 13px;
  color: var(--text-secondary);
  max-width: 420px;
  margin: 0;
  line-height: 1.45;
}

.hub-message-row {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 6px 10px;
  border-radius: 8px;
  transition: background 0.15s ease;
}

.hub-message-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.hub-message-row.is-self {
  background: rgba(56, 189, 248, 0.04);
}

.hub-msg-avatar {
  flex-shrink: 0;
  margin-top: 2px;
}

.hub-msg-body-wrapper {
  flex: 1;
  min-width: 0;
}

.hub-msg-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 3px;
  flex-wrap: wrap;
}

.hub-msg-sender {
  font-size: 13px;
  font-weight: 800;
  color: var(--text-primary);
}

.hub-self-badge {
  font-size: 9px;
  font-weight: 800;
  background: var(--accent-color, #38bdf8);
  color: var(--accent-text, #060b14);
  padding: 1px 5px;
  border-radius: 3px;
}

.hub-msg-location {
  font-size: 10px;
  color: var(--text-tertiary);
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.hub-msg-timestamp {
  font-size: 10px;
  color: var(--text-tertiary);
  margin-left: auto;
}

.hub-msg-hover-actions {
  display: none;
  align-items: center;
  gap: 4px;
  margin-left: 6px;
}

.hub-message-row:hover .hub-msg-hover-actions {
  display: flex;
}

.hub-hover-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.hub-hover-btn:hover {
  background: var(--accent-color, #38bdf8);
  color: var(--accent-text, #060b14);
  border-color: transparent;
}

.hub-quoted-reply-box {
  display: flex;
  align-items: stretch;
  gap: 8px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 6px;
  padding: 4px 8px;
  margin-bottom: 6px;
  cursor: pointer;
  transition: background 0.15s ease;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.hub-quoted-reply-box:hover {
  background: rgba(56, 189, 248, 0.1);
  border-color: rgba(56, 189, 248, 0.2);
}

.hub-reply-line {
  width: 3px;
  background: var(--accent-color, #38bdf8);
  border-radius: 2px;
  flex-shrink: 0;
}

.hub-reply-meta {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  overflow: hidden;
}

.hub-reply-user {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-color, #38bdf8);
}

.hub-reply-snippet {
  font-size: 11px;
  color: var(--text-secondary, #94a3b8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hub-msg-text {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.45;
  word-break: break-word;
}

.hub-msg-tags-row {
  margin-top: 4px;
}

.hub-tag-chip {
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-secondary);
}

.hub-quick-chips-bar {
  display: flex;
  gap: 8px;
  padding: 8px 16px;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  overflow-x: auto;
  scrollbar-width: none !important;
}

.hub-quick-chips-bar::-webkit-scrollbar {
  display: none !important;
}

@media (max-width: 900px) {
  .hub-quick-chips-bar {
    display: none !important;
  }
}

.hub-quick-chip-btn,
.hub-quick-chip {
  padding: 5px 12px;
  font-size: 11px;
  font-weight: 700;
  border-radius: 12px;
  background: var(--bg-tertiary, #1e1f22);
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.1));
  color: var(--text-secondary, #94a3b8);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.hub-quick-chip-btn:hover,
.hub-quick-chip:hover {
  border-color: var(--accent-color, #38bdf8);
  background: rgba(56, 189, 248, 0.1);
  color: #38bdf8;
  transform: translateY(-1px);
}

.chip-plus {
  color: #38bdf8;
  font-weight: 800;
}

.hub-composer-form {
  padding: 8px 12px;
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  gap: 8px;
  border-top: 1px solid var(--border-color);
  width: 100%;
  box-sizing: border-box;
}

.hub-chat-input,
.hub-composer-input {
  flex: 1;
  min-width: 0;
  height: 40px;
  padding: 0 14px;
  background: var(--bg-tertiary, #1e1f22);
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.1));
  border-radius: var(--radius-md, 8px);
  color: var(--text-primary, #ffffff);
  font-size: 13px;
  outline: none;
  box-sizing: border-box;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.hub-chat-input:focus,
.hub-composer-input:focus {
  border-color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.15);
}

.hub-send-btn {
  flex-shrink: 0;
  background: var(--accent-color, #38bdf8);
  border: none;
  color: var(--accent-text, #060b14);
  width: 40px;
  height: 40px;
  padding: 0;
  border-radius: var(--radius-md, 8px);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.hub-send-btn:hover:not(:disabled) {
  opacity: 0.9;
  transform: translateY(-1px);
}

.hub-send-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.hub-send-btn:hover:not(:disabled) {
  opacity: 0.9;
}

.hub-send-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ========================================================
   RIGHT: DYNAMIC LEADERBOARD / CHANNEL MEMBERS SIDEBAR
   ======================================================== */
.hub-right-sidebar {
  width: 270px;
  min-width: 270px;
  max-width: 280px;
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  height: 100%;
}

@media (max-width: 960px) {
  .hub-right-sidebar {
    width: 100%;
    min-width: 100%;
    max-width: 100%;
    border-left: none;
  }
}

.hub-leaderboard-container,
.hub-channel-members-container {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.hub-leaderboard-header {
  padding: 12px 14px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.hub-leaderboard-title-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.hub-leaderboard-title {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--text-primary);
  letter-spacing: 0.5px;
}

.hub-leaderboard-badge {
  font-size: 10px;
  font-weight: 700;
  color: #22c55e;
  display: flex;
  align-items: center;
  gap: 5px;
}

.hub-leaderboard-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  scrollbar-width: none;
}

.hub-leaderboard-scroll::-webkit-scrollbar {
  display: none;
}

.hub-leaderboard-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 30px 14px;
  color: var(--text-tertiary);
}

.hub-leaderboard-empty h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 8px 0 4px 0;
}

.hub-leaderboard-empty p {
  font-size: 11px;
  line-height: 1.4;
  margin: 0;
}

.hub-leaderboard-card,
.hub-member-card {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s ease, border-color 0.2s ease, background 0.2s ease;
  position: relative;
  overflow: hidden;
}

.hub-leaderboard-card:hover,
.hub-member-card:hover {
  transform: translateY(-2px);
  border-color: rgba(249, 115, 22, 0.5);
  background: rgba(249, 115, 22, 0.07);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5), 0 0 16px rgba(249, 115, 22, 0.22);
}

.hub-leaderboard-card:hover .avatar-wrapper,
.hub-member-card:hover .avatar-wrapper {
  transform: scale(1.06);
  box-shadow: 0 0 0 2px #f97316, 0 0 12px rgba(249, 115, 22, 0.7);
  transition: all 0.2s ease;
}

.hub-leaderboard-card:hover .hub-student-name,
.hub-member-card:hover .hub-member-name {
  color: #ffffff;
}

.hub-leaderboard-card:hover .hub-leaderboard-timer {
  color: #f59e0b;
  transform: scale(1.02);
  transition: all 0.15s ease;
}

.hub-leaderboard-card.is-self,
.hub-member-card.is-self {
  border-color: rgba(56, 189, 248, 0.35);
  background: rgba(56, 189, 248, 0.08);
}

.hub-leaderboard-card.is-self:hover,
.hub-member-card.is-self:hover {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5), 0 0 16px rgba(56, 189, 248, 0.3);
}

.hub-rank-badge {
  font-size: 14px;
  font-weight: 800;
  min-width: 22px;
  text-align: center;
}

.hub-leaderboard-meta,
.hub-member-meta {
  flex: 1;
  min-width: 0;
}

.hub-student-name-row,
.hub-member-name-row {
  display: flex;
  align-items: center;
  gap: 5px;
}

.hub-student-name,
.hub-member-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hub-self-tag {
  font-size: 8px;
  font-weight: 800;
  background: var(--accent-color, #38bdf8);
  color: var(--accent-text, #060b14);
  padding: 1px 4px;
  border-radius: 3px;
}

.hub-leaderboard-timer {
  font-size: 11px;
  font-weight: 700;
  color: #eab308;
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 1px;
}

.hub-subject-pill {
  font-size: 9px;
  font-weight: 800;
  background: rgba(249, 115, 22, 0.2);
  color: #fb923c;
  padding: 1px 5px;
  border-radius: 4px;
  margin-left: 4px;
}

.hub-student-stats-row {
  font-size: 10px;
  color: var(--text-tertiary);
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 2px;
}

.hub-member-status-line {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  color: var(--text-secondary);
  margin-top: 2px;
}

.hub-member-sub-info {
  font-size: 10px;
  color: var(--text-tertiary);
  margin-top: 1px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Right Sidebar Navigation Tabs */
.hub-right-sidebar-nav {
  display: flex;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  padding: 4px;
  gap: 4px;
}

.hub-right-nav-tab {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-tertiary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}

.hub-right-nav-tab:hover {
  color: var(--text-primary);
  background: rgba(255, 255, 255, 0.04);
}

.hub-right-nav-tab.active {
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
}

.hub-tab-count {
  font-size: 9px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-secondary);
}

.hub-tab-count.active-pulse {
  background: rgba(34, 197, 94, 0.2);
  color: #22c55e;
  box-shadow: 0 0 6px rgba(34, 197, 94, 0.4);
}

.hub-member-card.is-active-dm {
  border-color: rgba(56, 189, 248, 0.5);
  background: rgba(56, 189, 248, 0.09);
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.15);
}

.hub-active-chat-pill {
  font-size: 8px;
  font-weight: 800;
  background: #38bdf8;
  color: #060b14;
  padding: 1px 4px;
  border-radius: 3px;
  margin-left: auto;
  letter-spacing: 0.3px;
}

.studying-status-text {
  color: #eab308;
  font-weight: 600;
}

.hub-inspect-inline-btn {
  margin-left: auto;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 4px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  transition: all 0.15s ease;
}

/* ========================================================
   STUDY ARENA & FOCUS LOUNGE (LEADERBOARD & BUDDIES TIMERS)
   ======================================================== */
.study-arena-view {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 20px 60px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.study-arena-hero {
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.85) 0%, rgba(30, 41, 59, 0.7) 100%);
  border: 1px solid rgba(56, 189, 248, 0.2);
  border-radius: var(--radius-xl, 16px);
  padding: 28px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(12px);
  position: relative;
  overflow: hidden;
}

.study-arena-hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 350px;
  height: 350px;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.12) 0%, transparent 70%);
  pointer-events: none;
}

.study-arena-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 12px;
  border-radius: 9999px;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.3);
  color: #38bdf8;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.8px;
  margin-bottom: 10px;
}

.study-arena-title {
  font-size: 26px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0 0 6px 0;
  letter-spacing: -0.5px;
}

.study-arena-subtitle {
  font-size: 13px;
  color: var(--text-secondary);
  margin: 0;
  max-width: 580px;
  line-height: 1.5;
}/* ========================================================
   ASPIRANT BATTLEGROUND & ESPORTS ARENA LEADERBOARD
   ======================================================== */
.battleground-arena-wrapper {
  display: flex;
  flex-direction: column;
  gap: 22px;
  max-width: 1380px;
  margin: 0 auto;
  width: 100%;
  padding-bottom: 95px; /* Buffer for sticky battle HUD */
  position: relative;
  contain: layout;
}

/* 1. War Room Command Marquee */
.war-room-header-strip {
  display: flex;
  justify-content: space-between;
  align-items: stretch;
  gap: 24px;
  flex-wrap: wrap;
}

.war-room-meta-col {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  min-width: 320px;
}

.season-txt-short,
.arena-live-short,
.sync-pill-short {
  display: none !important;
}

.battle-season-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.battle-season-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 800;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.25);
  padding: 4px 10px;
  border-radius: 6px;
  width: fit-content;
}

.live-radar-ping {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #ff3344;
  box-shadow: 0 0 10px #ff3344;
  animation: combatPulse 1.6s infinite;
}

@keyframes combatPulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.4); opacity: 0.5; }
}

.season-txt {
  letter-spacing: 0.08em;
}

.arena-live-count {
  color: #34d399;
  font-weight: 800;
  margin-left: 6px;
  padding-left: 8px;
  border-left: 1px solid rgba(255, 255, 255, 0.15);
}

.battleground-title {
  font-family: 'Syne', var(--font-display), sans-serif;
  font-size: clamp(32px, 4.5vw, 46px);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: #ffffff;
  margin: 4px 0 6px 0;
}

.title-highlight {
  color: #ff3344;
  text-shadow: 0 0 24px rgba(255, 51, 68, 0.5);
}

/* Live Battle Ticker */
.battle-live-ticker {
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 6px 12px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  max-width: 600px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.ticker-tag {
  color: #fbbf24;
  font-weight: 900;
  font-size: 9px;
  letter-spacing: 0.1em;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.3);
  padding: 2px 6px;
  border-radius: 4px;
  flex-shrink: 0;
}

.ticker-content {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #cbd5e1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ticker-name {
  font-weight: 800;
  color: #ffffff;
}

.ticker-event {
  color: #94a3b8;
}

.ticker-score {
  color: #34d399;
  font-weight: 800;
}

.ticker-time {
  color: #64748b;
  font-size: 10px;
}

/* Rival Overtake Challenge Card */
.rival-overtake-widget {
  background: linear-gradient(135deg, rgba(255, 51, 68, 0.09) 0%, rgba(15, 23, 42, 0.8) 100%);
  border: 1px solid rgba(255, 51, 68, 0.35);
  border-radius: 14px;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 320px;
  max-width: 440px;
  flex: 1;
  box-shadow: 0 10px 30px rgba(255, 51, 68, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.rival-widget-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.widget-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: #ff3344;
}

.widget-gap-pill {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  color: #fbbf24;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.3);
  padding: 2px 7px;
  border-radius: 4px;
}

.rival-versus-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 10px;
  padding: 10px 14px;
}

.versus-player {
  display: flex;
  flex-direction: column;
}

.versus-player.rival {
  align-items: flex-end;
}

.versus-rank {
  font-family: 'Syne', sans-serif;
  font-size: 18px;
  font-weight: 900;
  color: #ffffff;
  line-height: 1;
}

.versus-name {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 800;
  color: #38bdf8;
  margin-top: 2px;
}

.versus-player.rival .versus-name {
  color: #fca5a5;
}

.versus-stat {
  font-size: 10px;
  color: #94a3b8;
  margin-top: 1px;
  font-family: 'JetBrains Mono', monospace;
}

.versus-sword-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(255, 51, 68, 0.15);
  border: 1px solid rgba(255, 51, 68, 0.3);
  color: #ff3344;
}

.versus-zap-ico {
  animation: pulseZap 1.5s infinite;
}

@keyframes pulseZap {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.15); }
}

.rival-challenge-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 9px 14px;
  background: #ff3344;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s ease;
  box-shadow: 0 4px 16px rgba(255, 51, 68, 0.3);
  letter-spacing: 0.03em;
}

.rival-challenge-btn:hover {
  background: #ff4d5d;
  transform: translateY(-1px);
  box-shadow: 0 6px 22px rgba(255, 51, 68, 0.5);
}

/* ========================================================
   2. PHYSICAL RANKED PODIUM STAGE
   ======================================================== */
.ranked-podium-stage {
  display: grid;
  grid-template-columns: 1fr 1.2fr 1fr;
  gap: 16px;
  align-items: flex-end;
  margin-top: 6px;
}

.podium-pillar {
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transition: transform 0.2s ease, opacity 0.2s ease;
  contain: layout style;
  will-change: transform;
  transform: translateZ(0);
}

.podium-pillar:hover {
  transform: translateY(-4px);
}

.pillar-step-pedestal {
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  padding: 22px 18px 0 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 8px;
  overflow: hidden;
}

.pillar-step-pedestal.gold {
  background: linear-gradient(180deg, rgba(234, 179, 8, 0.1) 0%, rgba(15, 23, 42, 0.75) 100%);
  border-color: rgba(234, 179, 8, 0.45);
  box-shadow: 0 12px 36px rgba(234, 179, 8, 0.15);
  padding-top: 26px;
}

.pillar-step-pedestal.silver {
  background: linear-gradient(180deg, rgba(148, 163, 184, 0.08) 0%, rgba(15, 23, 42, 0.65) 100%);
  border-color: rgba(148, 163, 184, 0.35);
}

.pillar-step-pedestal.bronze {
  background: linear-gradient(180deg, rgba(249, 115, 22, 0.08) 0%, rgba(15, 23, 42, 0.65) 100%);
  border-color: rgba(249, 115, 22, 0.35);
}

.pedestal-crown-halo {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 800;
  color: #fbbf24;
  background: rgba(234, 179, 8, 0.15);
  border: 1px solid rgba(234, 179, 8, 0.35);
  padding: 3px 10px;
  border-radius: 9999px;
}

.champion-crown-svg {
  color: #fbbf24;
  animation: crownHover 2s infinite ease-in-out;
}

@keyframes crownHover {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-2px); }
}

.pedestal-rank-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  color: #e2e8f0;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.18);
  padding: 3px 8px;
  border-radius: 9999px;
}

.pedestal-rank-tag.bronze {
  color: #fdba74;
  background: rgba(249, 115, 22, 0.12);
  border-color: rgba(249, 115, 22, 0.3);
}

.pedestal-avatar-frame {
  margin: 4px 0;
}

.pedestal-avatar-frame.gold {
  filter: drop-shadow(0 0 16px rgba(234, 179, 8, 0.45));
}
.pedestal-avatar-frame.silver {
  filter: drop-shadow(0 0 12px rgba(255, 255, 255, 0.25));
}
.pedestal-avatar-frame.bronze {
  filter: drop-shadow(0 0 12px rgba(249, 115, 22, 0.25));
}

.pillar-player-name {
  font-size: 16px;
  font-weight: 800;
  color: #ffffff;
  margin: 0;
}

.pillar-player-name.apex {
  font-size: 19px;
}

.pillar-target-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  padding: 2px 7px;
  border-radius: 4px;
}

.pillar-target-tag.gold {
  color: #fbbf24;
  background: rgba(234, 179, 8, 0.08);
  border-color: rgba(234, 179, 8, 0.3);
}

.pillar-elo-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin: 4px 0;
}

.elo-val {
  font-family: 'Syne', var(--font-display), sans-serif;
  font-size: 26px;
  font-weight: 900;
  color: #ffffff;
  line-height: 1;
}

.elo-val.gold {
  color: #fbbf24;
  text-shadow: 0 0 18px rgba(234, 179, 8, 0.4);
}

.elo-lbl {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: #64748b;
  margin-top: 4px;
}

.elo-lbl.gold {
  color: rgba(234, 179, 8, 0.8);
}

.pillar-stat-chips {
  display: flex;
  gap: 6px;
  margin: 6px 0 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.stat-chip {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: #cbd5e1;
}

.stat-chip.flame {
  color: #fb923c;
  border-color: rgba(249, 115, 22, 0.3);
}

.stat-chip.gold {
  color: #fbbf24;
  border-color: rgba(234, 179, 8, 0.3);
}

.stat-chip.green {
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.3);
}

/* Physical 3D Pillar Base Step */
.pillar-base-block {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Syne', sans-serif;
  font-weight: 900;
  border-radius: 4px 4px 0 0;
}

.pillar-base-block.gold {
  height: 60px;
  font-size: 28px;
  color: #fbbf24;
  background: linear-gradient(180deg, rgba(234, 179, 8, 0.25) 0%, rgba(234, 179, 8, 0.05) 100%);
  border-top: 2px solid #fbbf24;
}

.pillar-base-block.silver {
  height: 42px;
  font-size: 22px;
  color: #94a3b8;
  background: linear-gradient(180deg, rgba(148, 163, 184, 0.2) 0%, rgba(148, 163, 184, 0.04) 100%);
  border-top: 2px solid #94a3b8;
}

.pillar-base-block.bronze {
  height: 32px;
  font-size: 20px;
  color: #f97316;
  background: linear-gradient(180deg, rgba(249, 115, 22, 0.2) 0%, rgba(249, 115, 22, 0.04) 100%);
  border-top: 2px solid #f97316;
}

/* ========================================================
   3. RANKED LADDER TOOLBAR
   ======================================================== */
.ranked-ladder-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding-bottom: 2px;
}

.division-ladder-pills {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.division-pill-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 800;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.35);
  color: #94a3b8;
  cursor: pointer;
  transition: all 0.15s ease;
}

.division-pill-btn:hover {
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.2);
}

.division-pill-btn .pill-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #64748b;
}

.division-pill-btn.active {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.3);
}

.division-pill-btn.active.diamond .pill-dot { background: #38bdf8; }
.division-pill-btn.active.platinum .pill-dot { background: #c084fc; }
.division-pill-btn.active.gold .pill-dot { background: #fbbf24; }

.timeframe-mode-cluster {
  display: flex;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 3px;
  gap: 3px;
}

.timeframe-mode-btn {
  padding: 5px 11px;
  border-radius: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: #64748b;
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}

.timeframe-mode-btn:hover {
  color: #cbd5e1;
}

.timeframe-mode-btn.active {
  background: #ff3344;
  color: #ffffff;
  box-shadow: 0 0 12px rgba(255, 51, 68, 0.4);
}

.ladder-search-box {
  display: flex;
  align-items: center;
  gap: 7px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 5px 10px;
  width: 220px;
  transition: width 0.2s ease, border-color 0.2s ease;
}

.ladder-search-box:focus-within {
  width: 260px;
  border-color: #ff3344;
}

.ladder-search-ico {
  color: #64748b;
  flex-shrink: 0;
}

.ladder-search-input {
  background: transparent;
  border: none;
  outline: none;
  color: #ffffff;
  font-size: 11px;
  width: 100%;
}

.ladder-search-clear {
  background: transparent;
  border: none;
  color: #64748b;
  cursor: pointer;
  padding: 0;
}

/* ========================================================
   4. THE RANKED LADDER ROSTER BOARD
   ======================================================== */
.ranked-roster-board {
  background: rgba(15, 23, 42, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  overflow: hidden;
  contain: layout;
}

.ladder-board-header {
  display: flex;
  align-items: center;
  padding: 12px 20px;
  background: rgba(0, 0, 0, 0.35);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #64748b;
  text-transform: uppercase;
}

.ladder-board-rows {
  display: flex;
  flex-direction: column;
}

.ladder-match-row {
  display: flex;
  align-items: center;
  padding: 14px 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
  cursor: pointer;
  contain: layout style;
  will-change: transform;
  transform: translateZ(0);
}

.ladder-match-row:last-child {
  border-bottom: none;
}

.ladder-match-row:hover {
  background: rgba(255, 255, 255, 0.03);
  border-color: rgba(255, 51, 68, 0.3);
}

.match-rank-col {
  width: 70px;
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.match-rank-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 15px;
  font-weight: 900;
  color: #ffffff;
}

.match-trend-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  font-weight: 800;
}
.match-trend-badge.up { color: #34d399; }
.match-trend-badge.down { color: #f43f5e; }
.match-trend-badge.steady { color: #64748b; }

.match-profile-col {
  flex: 2;
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.match-info-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.match-name-line {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.match-player-name {
  font-size: 13px;
  font-weight: 800;
  color: #ffffff;
}

.match-id-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: #64748b;
}

.match-tier-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  font-weight: 800;
  padding: 1px 6px;
  border-radius: 4px;
}

.match-tier-tag.diamond {
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.3);
}

.match-tier-tag.platinum {
  color: #c084fc;
  background: rgba(192, 132, 252, 0.12);
  border: 1px solid rgba(192, 132, 252, 0.3);
}

.match-tier-tag.gold {
  color: #fbbf24;
  background: rgba(251, 191, 36, 0.12);
  border: 1px solid rgba(251, 191, 36, 0.3);
}

.match-tier-tag.silver {
  color: #94a3b8;
  background: rgba(148, 163, 184, 0.12);
  border: 1px solid rgba(148, 163, 184, 0.3);
}

.ladder-archetype-tag {
  font-size: 8.5px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 3px;
  letter-spacing: 0.05em;
}

.ladder-archetype-tag.studious {
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.15);
  border: 1px solid rgba(56, 189, 248, 0.3);
}

.ladder-archetype-tag.intermediate {
  color: #c084fc;
  background: rgba(192, 132, 252, 0.15);
  border: 1px solid rgba(192, 132, 252, 0.3);
}

.ladder-archetype-tag.alright {
  color: #fbbf24;
  background: rgba(251, 191, 36, 0.15);
  border: 1px solid rgba(251, 191, 36, 0.3);
}

.ladder-archetype-tag.slacker {
  color: #94a3b8;
  background: rgba(148, 163, 184, 0.12);
  border: 1px solid rgba(148, 163, 184, 0.25);
}

.ladder-match-row.user-self-row {
  background: rgba(56, 189, 248, 0.08);
  border-left: 3px solid #38bdf8;
}

.ladder-match-row.user-self-row:hover {
  background: rgba(56, 189, 248, 0.14);
}

.user-self-name {
  color: #38bdf8 !important;
  font-weight: 900 !important;
}

.arena-sync-pill {
  font-size: 9.5px;
  font-weight: 800;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.28);
  padding: 2px 8px;
  border-radius: 9999px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
