/* ========================================================
   6. COMBATANT DOSSIER MODAL
   ======================================================== */
.battle-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(8px);
  z-index: 999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.battle-dossier-modal {
  background: #090e1a;
  border: 1px solid rgba(255, 51, 68, 0.3);
  border-radius: 16px;
  width: 100%;
