/* ========================================================
   ACTIVITY & STUDY CONTRIBUTION HEATMAP (CLEAN & CENTERED)
   ======================================================== */
.activity-heatmap-wrapper,
.github-heatmap-wrapper {
  background: #0d1117;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  width: 100%;
  box-sizing: border-box;
}

.activity-heatmap-wrapper.is-compact,
.github-heatmap-wrapper.is-compact {
  padding: 12px 14px;
  gap: 10px;
}

.heatmap-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  width: 100%;
}

.heatmap-month-tabs {
  display: flex;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 3px;
  border-radius: 6px;
  gap: 3px;
  flex-wrap: wrap;
}

.month-tab-btn {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 700;
  border: none;
  background: transparent;
  color: #949ba4;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.month-tab-btn:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.08);
}

.month-tab-btn.active {
  background: #5865f2;
  color: #ffffff;
}

.heatmap-legend-box {
  display: flex;
  align-items: center;
  gap: 4px;
}

.legend-label {
  font-size: 10px;
  font-weight: 600;
  color: #7d8590;
}

.heatmap-square {
  width: 12px;
  height: 12px;
  border-radius: 2px;
  background: #161b22;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: border-color 0.12s ease, box-shadow 0.12s ease;
  cursor: pointer;
  flex-shrink: 0;
  margin-bottom: 4px;
}

.heatmap-square:last-child {
  margin-bottom: 0;
}

.heatmap-square.single-month-square {
  width: 16px;
  height: 16px;
  border-radius: 3px;
  margin-bottom: 6px;
}

.heatmap-square:hover {
  border-color: #ffffff;
  box-shadow: 0 0 0 1.5px #ffffff, 0 0 6px var(--accent-glow, rgba(255, 255, 255, 0.4));
  z-index: 5;
}

.heatmap-square.level-0 {
  background: var(--heatmap-level-0, #161b22);
}

.heatmap-square.level-1 {
  background: var(--heatmap-level-1, #0c4a6e);
}

.heatmap-square.level-2 {
  background: var(--heatmap-level-2, #0284c7);
}

.heatmap-square.level-3 {
  background: var(--heatmap-level-3, #38bdf8);
}

.heatmap-square.level-4 {
  background: var(--heatmap-level-4, #7dd3fc);
  box-shadow: 0 0 8px var(--heatmap-glow, rgba(56, 189, 248, 0.5));
}

.heatmap-scroll-area {
  display: flex;
  justify-content: flex-start;
  overflow-x: auto;
  padding: 4px 0;
  width: 100%;
  max-width: 100%;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.heatmap-scroll-area::-webkit-scrollbar {
  display: none;
}

@media (min-width: 769px) {
  .heatmap-scroll-area {
    justify-content: center;
  }
}

.heatmap-grid-table {
  display: inline-flex;
  flex-direction: column;
  gap: 6px;
  margin: 0 auto;
}

.heatmap-week-labels-row {
  display: flex;
  align-items: center;
  font-size: 10px;
  font-weight: 700;
  color: #7d8590;
  gap: 8px;
}

.heatmap-day-label-placeholder {
  width: 34px;
  flex-shrink: 0;
}

.heatmap-labels-track {
  display: flex;
  gap: 4px;
}

.single-month-mode .heatmap-labels-track {
  gap: 6px;
}

.heatmap-month-span-label.four-weeks-span {
  width: 60px; /* 4 * 12px + 3 * 4px */
  text-align: center;
  font-size: 10px;
  font-weight: 700;
  color: #949ba4;
  flex-shrink: 0;
}

.heatmap-month-span-label.single-week-label {
  width: 16px;
  text-align: center;
  font-size: 10px;
  font-weight: 700;
  color: #949ba4;
  flex-shrink: 0;
}

.heatmap-matrix-body {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.heatmap-day-labels-col {
  display: flex;
  flex-direction: column;
  width: 34px;
  text-align: right;
  padding-right: 6px;
  flex-shrink: 0;
}

.day-label-cell {
  height: 12px;
  line-height: 12px;
  margin-bottom: 4px;
  font-size: 9px;
  font-weight: 700;
  color: #7d8590;
}

.single-month-mode .day-label-cell {
  height: 16px;
  line-height: 16px;
  margin-bottom: 6px;
  font-size: 10px;
}

.day-label-cell.empty-day-label {
  visibility: hidden;
}

.heatmap-weeks-track {
  display: flex;
  gap: 4px;
  flex: 0 0 auto;
}

.single-month-mode .heatmap-weeks-track {
  gap: 6px;
}

.heatmap-week-column {
  display: flex;
  flex-direction: column;
  flex: 0 0 auto;
}

.heatmap-cell-tooltip-status {
  font-size: 11px;
  color: #8fa0ff;
  height: 22px;
  min-height: 22px;
  max-height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  width: 100%;
  overflow: hidden;
  white-space: nowrap;
}

.month-tab-all-short {
  display: none;
}

.heatmap-month-label-short {
  display: none;
}

@media (max-width: 768px) {
  .activity-heatmap-wrapper,
  .github-heatmap-wrapper {
    padding: 12px 10px;
    gap: 10px;
  }
  .heatmap-cell-tooltip-status {
    height: auto;
    min-height: 24px;
    max-height: none;
    white-space: normal;
    font-size: 10.5px;
    line-height: 1.3;
    padding: 0 4px;
  }
}

@media (max-width: 640px) {
  .activity-heatmap-wrapper .heatmap-header-row {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
  }

  .activity-heatmap-wrapper .heatmap-month-tabs {
    display: flex;
    flex-wrap: nowrap;
    width: 100%;
    gap: 3px;
    padding: 3px;
    box-sizing: border-box;
  }

  .activity-heatmap-wrapper .month-tab-btn {
    flex: 1 1 auto;
    text-align: center;
    padding: 4px 6px;
    font-size: 10px;
    letter-spacing: 0.02em;
    white-space: nowrap;
    min-width: 0;
  }

  .activity-heatmap-wrapper .heatmap-legend-box {
    align-self: flex-end;
  }

  .heatmap-scroll-area {
    overflow-x: hidden !important;
    justify-content: center !important;
    padding: 2px 0;
    width: 100%;
  }

  .heatmap-grid-table {
    gap: 4px;
    margin: 0 auto;
  }

  .heatmap-week-labels-row {
    gap: 4px;
    font-size: 8.5px;
  }

  .heatmap-day-label-placeholder {
    width: 22px;
  }

  .heatmap-labels-track {
    gap: 3px;
  }

  .heatmap-month-span-label.four-weeks-span {
    width: 49px; /* 4 * 10px + 3 * 3px */
    font-size: 8.5px;
    text-align: center;
    white-space: nowrap;
  }

  .heatmap-month-span-label.single-week-label {
    width: 14px;
    font-size: 8.5px;
  }

  .heatmap-matrix-body {
    gap: 4px;
  }

  .heatmap-day-labels-col {
    width: 22px;
    padding-right: 3px;
  }

  .day-label-cell {
    height: 10px;
    line-height: 10px;
    margin-bottom: 3px;
    font-size: 8px;
  }

  .heatmap-square {
    width: 10px;
    height: 10px;
    margin-bottom: 3px;
    border-radius: 2px;
  }

  .heatmap-weeks-track {
    gap: 3px;
  }

  /* Single Month View on Mobile */
  .single-month-mode .heatmap-labels-track {
    gap: 5px;
  }
  .single-month-mode .heatmap-weeks-track {
    gap: 5px;
  }
  .single-month-mode .heatmap-square.single-month-square {
