  box-shadow: 0 0 16px rgba(234, 179, 8, 0.4), inset 0 0 12px rgba(234, 179, 8, 0.2) !important;
  animation: crestPulse 2.5s infinite ease-in-out;
}

@keyframes crestPulse {
  0%, 100% {
    box-shadow: 0 0 16px rgba(234, 179, 8, 0.4), inset 0 0 12px rgba(234, 179, 8, 0.2);
  }
  50% {
    box-shadow: 0 0 24px rgba(234, 179, 8, 0.7), inset 0 0 16px rgba(234, 179, 8, 0.4);
