  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
}

.profile-badge-emblem-tile.unlocked {
  background: rgba(255, 255, 255, 0.05);
  border-color: var(--badge-glow-color, rgba(255, 255, 255, 0.3));
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.4), inset 0 0 12px rgba(255, 255, 255, 0.02);
}

.profile-badge-emblem-tile.locked {
  opacity: 0.35;
  filter: grayscale(1);
  background: #0d0e10;
}

.profile-badge-emblem-tile:hover {
  transform: translateY(-3px) scale(1.1);
  z-index: 10;
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.6), 0 0 14px var(--badge-glow-color, rgba(255, 255, 255, 0.2));
}

.profile-badge-emblem-tile.unlocked:hover {
  border-color: #ffffff;
}

.badge-emblem-svg-icon {
  display: flex;
  align-items: center;
  justify-content: center;
}

.badge-emblem-active-pip {
  position: absolute;
  top: -2px;
  right: -2px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 2px solid #111214;
  box-shadow: 0 0 6px currentColor;
}

/* Special Animated Floating Hover Card */
.badge-animated-hover-card {
  position: absolute;
  bottom: calc(100% + 10px);
  left: 0;
  transform: translateY(8px) scale(0.95);
  width: 230px;
  max-width: 280px;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  background: #14161a;
  border: 1px solid var(--badge-card-accent, rgba(255, 255, 255, 0.2));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.75), 0 0 14px rgba(0, 0, 0, 0.5);
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: opacity 0.2s cubic-bezier(0.16, 1, 0.3, 1),
              transform 0.2s cubic-bezier(0.16, 1, 0.3, 1),
              visibility 0.2s ease;
}

/* Arrow indicator on tooltip */
.badge-animated-hover-card::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 19px;
  transform: translateX(-50%);
  border-width: 6px;
  border-style: solid;
  border-color: var(--badge-card-accent, rgba(255, 255, 255, 0.2)) transparent transparent transparent;
}

.badge-emblem-interactive-wrap:hover .badge-animated-hover-card,
.badge-emblem-interactive-wrap.active .badge-animated-hover-card {
  opacity: 1;
  pointer-events: auto;
  visibility: visible;
  transform: translateY(0) scale(1);
}

/* Right-aligned tooltips ONLY for badges far on the right half (6th badge onwards) */
.profile-badges-emblems-track > .badge-emblem-interactive-wrap:nth-child(n+7) .badge-animated-hover-card {
  left: auto;
  right: 0;
}

.profile-badges-emblems-track > .badge-emblem-interactive-wrap:nth-child(n+7) .badge-animated-hover-card::after {
  left: auto;
  right: 19px;
  transform: translateX(50%);
}

