  display: flex;
  align-items: center;
  gap: 12px;
}

.edit-preview-avatar-wrap {
  margin-top: -24px;
  flex-shrink: 0;
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.5));
}

.edit-preview-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
  margin-top: 4px;
}

.edit-preview-name {
  font-size: 14px;
  font-weight: 800;
  color: #ffffff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.edit-preview-target {
  font-size: 11px;
  color: #94a3b8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Tabs Bar */
.edit-modal-tabs-bar {
  display: flex;
  margin: 12px 20px 0 20px;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  padding: 3px;
  gap: 3px;
  flex-shrink: 0;
}

.edit-tab-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 10px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.edit-tab-btn.active {
  background: rgba(255, 255, 255, 0.09);
  color: #ffffff;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
}

/* Modal Body */
.edit-modal-body {
  padding: 14px 20px 18px 20px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  flex: 1;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.15) transparent;
}

.edit-modal-body::-webkit-scrollbar {
  width: 5px;
}

.edit-modal-body::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
}

/* User Assurance Success Banner inside Modal */
.edit-modal-success-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-radius: 10px;
  background: rgba(34, 197, 94, 0.14);
  border: 1px solid rgba(34, 197, 94, 0.35);
  color: #4ade80;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 12px;
  box-shadow: 0 4px 12px rgba(34, 197, 94, 0.15);
}

/* Global Floating Assurance Toast on Top of View */
.profile-global-floating-toast {
  position: fixed;
  top: 74px;
  left: 50%;
  transform: translateX(-50%);
  background: #0f172a;
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.35);
  padding: 8px 18px;
  border-radius: 30px;
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 9px;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.8), 0 0 16px rgba(56, 189, 248, 0.3);
  z-index: 999999;
  backdrop-filter: blur(8px);
}

.profile-global-floating-toast .toast-success-icon {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #22c55e;
  color: #040914;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-weight: 900;
}

/* Uniform Edit Card Block */
.edit-uniform-block {
  background: rgba(255, 255, 255, 0.025);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  padding: 14px 16px;
}

.edit-block-title-row {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  color: #e2e8f0;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding-bottom: 8px;
}

.edit-block-icon {
  color: var(--accent-color, #38bdf8);
}

.edit-upload-action-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
  flex-wrap: wrap;
}

.edit-uniform-upload-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 14px;
  border-radius: 8px;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.28);
  color: var(--accent-color, #38bdf8);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.edit-uniform-upload-btn:hover {
  background: rgba(56, 189, 248, 0.2);
  border-color: rgba(56, 189, 248, 0.45);
  transform: translateY(-1px);
}

.edit-default-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.edit-default-toggle-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
}

.edit-default-toggle-btn.active {
  background: rgba(56, 189, 248, 0.15);
  border-color: var(--accent-color, #38bdf8);
  color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.2);
}

.edit-upload-hint {
  font-size: 11px;
  color: #64748b;
}

.edit-url-input-group {
  display: flex;
  gap: 6px;
  margin-bottom: 12px;
}

.edit-uniform-input,
.edit-uniform-select,
.edit-uniform-textarea {
  width: 100%;
  padding: 8px 12px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 8px;
  color: #f1f5f9;
  font-size: 12px;
  font-family: inherit;
  box-sizing: border-box;
  transition: all 0.15s ease;
}

.edit-uniform-input:focus,
.edit-uniform-select:focus,
.edit-uniform-textarea:focus {
  outline: none;
  border-color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.12);
  background: rgba(0, 0, 0, 0.5);
}

.edit-uniform-select {
  cursor: pointer;
}

.edit-uniform-select option {
  background: #18191c;
  color: #ffffff;
}

.edit-input-apply-btn {
  padding: 0 14px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #e2e8f0;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
  flex-shrink: 0;
}

.edit-input-apply-btn:hover {
  background: rgba(255, 255, 255, 0.14);
  color: #ffffff;
}

.edit-sub-label {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  margin-bottom: 7px;
}

.avatar-preset-picker-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(38px, 1fr));
  gap: 6px;
}

.avatar-preset-btn {
  width: 100%;
  aspect-ratio: 1;
  max-width: 44px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: #94a3b8;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.avatar-preset-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.2);
  transform: scale(1.05);
}

.avatar-preset-btn.active {
  background: rgba(56, 189, 248, 0.18);
  border-color: var(--accent-color, #38bdf8);
  color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.3);
}

.edit-color-swatches-row {
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
}

.edit-color-swatch-circle {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all 0.15s ease;
}

.edit-color-swatch-circle:hover {
  transform: scale(1.15);
}

.edit-color-swatch-circle.active {
  border-color: #ffffff;
  transform: scale(1.2);
  box-shadow: 0 0 8px currentColor;
}

.edit-banner-swatch-rect {
  width: 26px;
  height: 22px;
  border-radius: 5px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all 0.15s ease;
}

.edit-banner-swatch-rect:hover {
  transform: scale(1.12);
}

.edit-banner-swatch-rect.active {
  border-color: #ffffff;
  transform: scale(1.18);
  box-shadow: 0 0 8px currentColor;
}

.edit-grid-2col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

@media (max-width: 520px) {
  .edit-grid-2col {
    grid-template-columns: 1fr;
  }
}

.edit-form-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.edit-field-label {
  font-size: 11px;
  font-weight: 700;
  color: #cbd5e1;
}

/* Modal Footer */
.edit-modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(20, 22, 28, 0.95);
  flex-shrink: 0;
}

.edit-modal-cancel-btn {
  padding: 8px 16px;
  border-radius: 8px;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #94a3b8;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.edit-modal-cancel-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #ffffff;
}

.edit-modal-save-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 18px;
  border-radius: 8px;
  background: var(--accent-color, #38bdf8);
  color: var(--accent-text, #060b14);
  border: none;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s ease;
  box-shadow: 0 4px 14px rgba(56, 189, 248, 0.3);
}

.edit-modal-save-btn:hover:not(:disabled) {
  opacity: 0.92;
  transform: translateY(-1px);
  box-shadow: 0 6px 18px rgba(56, 189, 248, 0.45);
}

.edit-modal-save-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ========================================================
   DASHBOARD DUAL-ROW STREAK & HEATMAP LAYOUT
   ======================================================== */
.dashboard-heatmap-dual-row {
  display: grid;
  grid-template-columns: 440px 1fr;
  gap: 20px;
  align-items: stretch;
  width: 100%;
  max-width: 100%;
}

@media (max-width: 960px) {
  .dashboard-heatmap-dual-row {
    grid-template-columns: 100%;
    gap: 16px;
  }
  .heatmap-matrix-left-col {
    max-width: 100% !important;
    width: 100% !important;
    min-width: 0 !important;
  }
  .streak-analytics-right-col {
    min-width: 0 !important;
    width: 100% !important;
  }
}

.heatmap-matrix-left-col {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 440px;
  min-width: 0;
}

.streak-analytics-right-col {
  display: flex;
  flex-direction: column;
  gap: 12px;
  justify-content: space-between;
  min-width: 220px;
}

/* Avant-Garde General Cards */
.avant-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 22px;
  margin-bottom: 20px;
  position: relative;
  overflow: hidden;
}

.avant-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  border-bottom: 1px dashed var(--border-color);
  padding-bottom: 14px;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 12px;
}

.avant-header-tag {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-tertiary);
  margin-bottom: 4px;
}

.avant-card-heading {
  font-family: 'Syne', var(--font-display), sans-serif;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: var(--text-primary);
  margin: 0;
}

.avant-card-subheading {
  font-size: 12px;
  color: var(--text-secondary);
  margin: 4px 0 0 0;
  line-height: 1.4;
}

.avant-card-header-badge, .avant-phase-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 2px;
  color: var(--text-primary);
}

/* Avant-Garde Streak Tiles */
.avant-streak-tile {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.avant-streak-tile:hover {
  transform: translateY(-2px);
  border-color: var(--border-color-hover);
}

.active-streak-border {
  border-left: 3px solid #ff3344;
}

.consistency-record-border {
  border-left: 3px solid #38bdf8;
}

.streak-tile-header {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  color: var(--text-tertiary);
  display: flex;
  align-items: center;
  gap: 6px;
  letter-spacing: 0.08em;
}

.streak-tile-number {
  font-family: 'Syne', var(--font-display), sans-serif;
  font-size: 24px;
  font-weight: 900;
  color: var(--text-primary);
  line-height: 1.1;
}

.streak-unit {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
}

.streak-tile-desc {
  font-size: 11px;
  color: var(--text-secondary);
  line-height: 1.3;
}

.avant-perks-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--bg-primary);
  border: 1px solid rgba(234, 179, 8, 0.4);
  color: #eab308;
  font-family: 'Syne', sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.avant-perks-btn:hover {
  background: rgba(234, 179, 8, 0.12);
  border-color: #eab308;
  transform: translateY(-2px);
  box-shadow: 0 4px 14px rgba(234, 179, 8, 0.15);
}

.perks-btn-content {
  display: flex;
  align-items: center;
  gap: 8px;
}

.perks-arrow {
  font-size: 14px;
  font-weight: 900;
}

/* Avant-Garde Curriculum Focus Grid */
.avant-weekly-focus-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

@media (max-width: 800px) {
  .avant-weekly-focus-grid {
    grid-template-columns: 1fr;
  }
}

.avant-focus-box {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.avant-focus-box:hover {
  border-color: var(--border-color-hover);
  transform: translateY(-2px);
}

.focus-box-top {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.focus-subject-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--text-tertiary);
}

.focus-subject-title {
  font-family: 'Syne', sans-serif;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  text-transform: uppercase;
}

.focus-box-detail {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* Month tab buttons in Heatmap Component */
.month-tab-btn {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 10px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 2px;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.month-tab-btn:hover {
  color: var(--text-primary);
  border-color: var(--border-color-hover);
}

.month-tab-btn.active {
  background: var(--text-primary);
  color: var(--bg-primary);
  border-color: var(--text-primary);
  font-weight: 800;
}

.heatmap-square {
  border-radius: 2px;
  transition: transform 0.15s ease, filter 0.15s ease;
}

.heatmap-square:hover {
  transform: scale(1.3);
  z-index: 5;
  outline: 1px solid #ffffff;
}

/* ========================================================
   SETTINGS PAGE & THEME EMBLEMS SYSTEM
   ======================================================== */
.settings-page-wrapper {
  display: flex;
  flex-direction: column;
  gap: 20px;
  max-width: 900px;
  width: 100%;
  margin: 0 auto;
  padding-bottom: 40px;
}

.settings-page-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-color);
}

.settings-header-icon-box {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: rgba(88, 101, 242, 0.15);
  color: #5865f2;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.settings-page-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  letter-spacing: -0.5px;
}

.settings-page-subtitle {
  font-size: 13px;
  color: var(--text-secondary);
  margin: 2px 0 0 0;
}

.settings-cards-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

@media (max-width: 860px) {
  .settings-cards-grid {
    grid-template-columns: 1fr;
  }
}

.settings-card-container {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.settings-card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 18px;
  background: var(--bg-tertiary);
  border-bottom: 1px solid var(--border-color);
}

.settings-card-icon-box {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.settings-card-icon-box.cloud-icon { background: rgba(59, 130, 246, 0.15); color: #3b82f6; }
.settings-card-icon-box.theme-icon { background: rgba(236, 72, 153, 0.15); color: #ec4899; }
.settings-card-icon-box.font-icon { background: rgba(168, 85, 247, 0.15); color: #a855f7; }
.settings-card-icon-box.date-icon { background: rgba(34, 197, 94, 0.15); color: #22c55e; }
.settings-card-icon-box.data-icon { background: rgba(249, 115, 22, 0.15); color: #f97316; }

.settings-card-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
}

.settings-card-subtitle {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 2px 0 0 0;
  line-height: 1.3;
}

.settings-card-body {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1;
}

/* Theme Emblems Bar */
.settings-theme-emblems-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  padding: 8px 10px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
}

.settings-theme-emblem-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--theme-bg-preview, #09090b);
  border: 2px solid rgba(255, 255, 255, 0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.settings-theme-emblem-btn:hover {
