/* ========================================================
   SKIPER-UI (skiper103) MINIMAL AUTH WITH DASHBOARD CUBES
   ======================================================== */
.skiper-auth-root {
  min-height: 100vh;
  min-height: 100dvh;
  width: 100%;
  max-width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #080b11;
  position: relative;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 36px 20px;
  box-sizing: border-box;
  font-family: var(--font-sans, 'Plus Jakarta Sans', -apple-system, sans-serif);
}

/* High-Performance WebGL Retro Dither Wave Backdrop (ReactBits) */
.auth-dither-backdrop {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  overflow: hidden;
  filter: blur(2.5px);
}

/* Ambient Darkening Veil with Frosted Blur - Ensures Elements Are 100% Crisp & Visible */
.auth-bg-veil {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background: radial-gradient(circle at 50% 45%, rgba(10, 14, 24, 0.82) 0%, rgba(6, 9, 16, 0.94) 100%);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
}

/* Split Screen Outer Layout with High-Contrast Glassmorphism & Transitions */
.skiper-split-card {
  position: relative;
  z-index: 10;
  width: 100%;
  max-width: 980px;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
  gap: 32px;
  align-items: stretch;
  background: rgba(12, 17, 29, 0.88);
  backdrop-filter: blur(36px) saturate(190%);
  -webkit-backdrop-filter: blur(36px) saturate(190%);
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 24px;
  box-shadow: 
    0 32px 80px -12px rgba(0, 0, 0, 0.8),
    0 0 0 1px rgba(255, 255, 255, 0.05);
  padding: 32px;
  box-sizing: border-box;
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.5s cubic-bezier(0.16, 1, 0.3, 1), filter 0.5s cubic-bezier(0.16, 1, 0.3, 1);
  animation: authCardFloatIn 0.65s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes authCardFloatIn {
  from {
    opacity: 0;
    transform: scale(0.98) translateY(14px);
    filter: blur(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
    filter: blur(0);
  }
}

/* Minimal & Aesthetic Component-Wise Cascading Stagger */
.skiper-form-column .skiper-brand-header {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.05s both;
}
.skiper-form-column .auth-signature-title-group {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.11s both;
}
.skiper-form-column .skiper-input-group {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.18s both;
}
.skiper-form-column .skiper-submit-btn {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.24s both;
}
.skiper-form-column .skiper-divider {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.28s both;
}
.skiper-form-column .skiper-google-btn {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.32s both;
}
.skiper-form-column .skiper-toggle-wrap,
.skiper-form-column .skiper-guest-wrap {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.38s both;
}

/* Right Feature Column Cascading Stagger (Preloaded Mascot enters promptly) */
.skiper-feature-column .skiper-mascot-header {
  animation: authItemCascade 0.55s cubic-bezier(0.34, 1.56, 0.64, 1) 0.08s both;
}
.skiper-feature-column .accordion-section-header {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.16s both;
}
.skiper-feature-column .skiper103-accordion-item:nth-child(1) {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.22s both;
}
.skiper-feature-column .skiper103-accordion-item:nth-child(2) {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.28s both;
}
.skiper-feature-column .skiper103-accordion-item:nth-child(3) {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.34s both;
}
.skiper-feature-column .skiper103-accordion-item:nth-child(4) {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.40s both;
}
.skiper-feature-column .skiper-feature-footer {
  animation: authItemCascade 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.46s both;
}

@keyframes authItemCascade {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Smooth Exit Animation When Sign In / Guest Succeeded */
.split-card-exit {
  transform: scale(0.95) translateY(-12px);
  opacity: 0;
  filter: blur(10px);
  pointer-events: none;
}

/* Smooth Return Animation When Sign In / Up Fails or Cancels */
.split-card-return {
  animation: authReturnShake 0.6s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
}

@keyframes authReturnShake {
  0% { transform: scale(0.98) translateY(-4px); opacity: 0.85; }
  25% { transform: scale(1.01) translateY(2px) translateX(-5px); opacity: 1; }
  50% { transform: scale(0.995) translateX(4px); }
  75% { transform: scale(1) translateX(-2px); }
  100% { transform: scale(1) translateX(0); opacity: 1; }
}

@media (max-width: 900px) {
  .skiper-split-card {
    grid-template-columns: minmax(0, 1fr);
    max-width: 440px;
    gap: 0;
    padding: 24px;
    width: 100%;
    box-sizing: border-box;
  }

  /* User requirement: for mobile view just the sign up part is alright, no need to add the features section */
  .skiper-feature-column {
