/* Skiper106 Smooth Caret Input Component */
.skiper106-input-wrapper {
  position: relative;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  box-sizing: border-box;
}

.skiper106-input-field {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  padding: 10.5px 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9px;
  color: #ffffff;
  font-size: 13.5px;
  font-family: var(--font-sans, 'Plus Jakarta Sans', sans-serif);
  outline: none;
  caret-color: transparent !important; /* Hide native browser rigid caret */
  transition: border-color 0.2s cubic-bezier(0.16, 1, 0.3, 1), background 0.2s ease, box-shadow 0.2s ease;
  box-sizing: border-box;
}

.skiper106-input-field::placeholder {
  color: #475569;
}

.skiper106-input-wrapper:hover .skiper106-input-field:not(:disabled) {
  border-color: rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.05);
}

.skiper106-input-wrapper.is-focused .skiper106-input-field {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.04);
  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.2), 0 4px 16px rgba(56, 189, 248, 0.08);
}

.skiper106-smooth-caret {
  position: absolute;
  top: 50%;
  left: 0;
  width: 2px;
  height: 17px;
  background: #38bdf8;
  border-radius: 1px;
  pointer-events: none;
  z-index: 4;
  box-shadow: 0 0 7px #38bdf8, 0 0 12px rgba(56, 189, 248, 0.5);
  will-change: transform;
  transition: transform 0.12s cubic-bezier(0.16, 1, 0.3, 1);
}

.skiper106-smooth-caret.is-idle {
  animation: skiper106CaretBlink 0.95s ease-in-out infinite;
}

.skiper106-smooth-caret.is-typing {
  opacity: 1 !important;
  animation: none !important;
}

@keyframes skiper106CaretBlink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

/* Skiper106 Multiline Smooth Caret Textarea */
.skiper106-textarea-wrapper {
  position: relative;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  display: block;
  box-sizing: border-box;
}

.skiper106-textarea-field {
  width: 100%;
  max-width: 100%;
