.animated-select-container.is-open .animated-select-trigger {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.05);
  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.22), 0 4px 16px rgba(56, 189, 248, 0.1);
}

.animated-select-trigger.small {
