}

.trigger-chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
  flex-shrink: 0;
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), color 0.2s ease;
}

.animated-select-trigger:hover .trigger-chevron {
  color: #94a3b8;
}

.animated-select-container.is-open .trigger-chevron {
