/* Dropdown Menu Panel - Solid High-Contrast Canvas */
.animated-select-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  min-width: 100%;
  width: max-content;
  max-width: min(340px, 100%);
  z-index: 10001 !important;
  background: #0c111d !important; /* Solid opaque dark canvas so buttons underneath never bleed through */
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 12px;
  box-shadow: 
    0 24px 50px -4px rgba(0, 0, 0, 0.95),
    0 0 0 1px rgba(56, 189, 248, 0.25),
    0 8px 24px rgba(0, 0, 0, 0.7);
  padding: 5px;
  box-sizing: border-box;
  animation: selectMenuSpringIn 0.2s cubic-bezier(0.16, 1, 0.3, 1) both;
  transform-origin: top center;
  overflow: hidden;
}

@keyframes selectMenuSpringIn {
  0% {
    opacity: 0;
    transform: translateY(-8px) scale(0.97);
    filter: blur(4px);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

