  100% { transform: translateY(-3px); }
}

.auth-zen-mascot-badge:hover {
  transform: scale(1.08) translateY(-2px);
}

.auth-zen-mascot-badge:active {
  transform: scale(0.95);
}

/* When Patted: Rich Happy Celebration Animation */
.auth-zen-mascot-badge.is-happy {
  animation: mascotHappyPulse 0.7s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.auth-zen-mascot-badge.is-happy .mascot-head {
  animation: mascotBobHappy 0.45s ease-in-out 3 !important;
}

.auth-zen-mascot-badge.is-happy .mascot-tail {
  animation: mascotTailHappyWag 0.35s ease-in-out 4 !important;
}

.auth-zen-mascot-badge.is-happy .mascot-soft-glow {
  background: radial-gradient(circle, rgba(244, 63, 94, 0.45) 0%, rgba(56, 189, 248, 0.35) 50%, transparent 75%) !important;
  filter: blur(14px) !important;
}

@keyframes mascotBobHappy {
  0%, 100% {
    transform: translateY(0) rotate(0deg) scale(1);
  }
  25% {
    transform: translateY(-5px) rotate(-4deg) scale(1.08);
  }
  50% {
    transform: translateY(1.5px) rotate(3deg) scale(0.96);
  }
  75% {
    transform: translateY(-4px) rotate(-2deg) scale(1.05);
  }
}

@keyframes mascotHappyPulse {
  0% {
    transform: scale(1);
  }
  30% {
    transform: scale(1.14);
  }
  60% {
    transform: scale(0.96);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes mascotTailHappyWag {
  0%, 100% {
    transform: rotate(0deg);
  }
  30% {
    transform: rotate(22deg);
  }
  70% {
    transform: rotate(-12deg);
  }
}

/* Floating Vector Heart/Sparkle Burst Particles */
.mascot-pat-burst {
  position: absolute;
  inset: -12px;
  pointer-events: none;
  z-index: 20;
}

.burst-spark {
  position: absolute;
  filter: drop-shadow(0 0 6px rgba(244, 63, 94, 0.6));
}

.burst-s1 {
  top: 6px;
  left: 4px;
  animation: sparkFloatUp1 0.9s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.burst-s2 {
  top: 2px;
  right: 6px;
  animation: sparkFloatUp2 0.85s cubic-bezier(0.16, 1, 0.3, 1) 0.08s forwards;
}

.burst-s3 {
  top: -2px;
  left: 42%;
  animation: sparkFloatUp3 0.95s cubic-bezier(0.16, 1, 0.3, 1) 0.04s forwards;
}

@keyframes sparkFloatUp1 {
  0% { opacity: 0; transform: translate(0, 0) scale(0.4); }
  25% { opacity: 1; transform: translate(-10px, -14px) scale(1.2); }
  100% { opacity: 0; transform: translate(-18px, -32px) scale(0.7); }
}

@keyframes sparkFloatUp2 {
  0% { opacity: 0; transform: translate(0, 0) scale(0.4); }
  25% { opacity: 1; transform: translate(12px, -16px) scale(1.2); }
  100% { opacity: 0; transform: translate(20px, -36px) scale(0.7); }
}

@keyframes sparkFloatUp3 {
  0% { opacity: 0; transform: translate(0, 0) scale(0.4); }
  25% { opacity: 1; transform: translate(2px, -20px) scale(1.3); }
  100% { opacity: 0; transform: translate(4px, -42px) scale(0.8); }
}

.mascot-soft-glow {
  position: absolute;
  inset: -4px;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.3) 0%, transparent 70%);
  filter: blur(10px);
  pointer-events: none;
  transition: background 0.6s ease, filter 0.6s ease;
}

.auth-mascot-svg {
  width: 52px;
  height: 40px;
  overflow: visible;
  display: block;
}

/* Mascot Smooth Animations */
.mascot-tail {
  transform-origin: 70px 60px;
  animation: mascotTailSwaySmooth 3.2s ease-in-out infinite alternate;
}

@keyframes mascotTailSwaySmooth {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(8deg); }
}

.mascot-head {
  transform-origin: 50px 66px;
  animation: mascotBreatheSmooth 4s ease-in-out infinite alternate;
}

@keyframes mascotBreatheSmooth {
  0% { transform: translateY(0); }
  100% { transform: translateY(-1.2px); }
}

.mascot-ear-l {
  transform-origin: 34px 26px;
  animation: earTwitchLSmooth 6s ease-in-out infinite;
}

.mascot-ear-r {
  transform-origin: 66px 26px;
  animation: earTwitchRSmooth 6s ease-in-out infinite;
}

@keyframes earTwitchLSmooth {
  0%, 88%, 100% { transform: rotate(0deg); }
  92% { transform: rotate(-5deg); }
  96% { transform: rotate(2deg); }
}

@keyframes earTwitchRSmooth {
  0%, 86%, 100% { transform: rotate(0deg); }
  90% { transform: rotate(5deg); }
  94% { transform: rotate(-2deg); }
}

.mascot-pupils {
  animation: pupilGlanceSmooth 7s ease-in-out infinite;
}

@keyframes pupilGlanceSmooth {
  0%, 80%, 100% { transform: translate(0, 0); }
  85% { transform: translate(-1px, 0.5px); }
  90% { transform: translate(1px, -0.5px); }
}

