/* ========================================================
   PRECISION FOCUS RETICLE CURSOR (CAT EXAM FOCUS THEME)
   ======================================================== */
.focus-cursor-core {
  position: fixed;
  top: 0;
  left: 0;
  width: 6px;
  height: 6px;
  background: var(--accent-color, #38bdf8);
  border-radius: 50%;
  pointer-events: none;
  z-index: 99999;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 12px var(--accent-color, #38bdf8), 0 0 4px #ffffff;
  transition: opacity 0.2s ease, width 0.2s ease, height 0.2s ease;
}

.focus-cursor-core.text {
  width: 2px;
  height: 18px;
  border-radius: 1px;
  box-shadow: 0 0 8px var(--accent-color, #38bdf8);
}

.focus-cursor-reticle {
  position: fixed;
  top: 0;
  left: 0;
  width: 28px;
  height: 28px;
  pointer-events: none;
  z-index: 99998;
  transform: translate(-50%, -50%);
  transition: opacity 0.2s ease, filter 0.25s ease, border-color 0.2s ease;
  border: 1px solid var(--accent-color, #38bdf8);
  border-radius: 50%;
  opacity: 0.35;
  box-shadow: 0 0 8px var(--accent-glow, rgba(56, 189, 248, 0.25));
  box-sizing: border-box;
}

.reticle-corner {
  position: absolute;
  width: 6px;
  height: 6px;
  border-color: var(--accent-color, #38bdf8);
  opacity: 0.75;
  transition: all 0.2s ease;
  pointer-events: none;
}

.reticle-corner.top-left {
  top: -1px;
  left: -1px;
  border-top: 2px solid;
  border-left: 2px solid;
  border-top-left-radius: 4px;
}

.reticle-corner.top-right {
  top: -1px;
  right: -1px;
  border-top: 2px solid;
  border-right: 2px solid;
  border-top-right-radius: 4px;
}

.reticle-corner.bottom-left {
  bottom: -1px;
  left: -1px;
  border-bottom: 2px solid;
  border-left: 2px solid;
  border-bottom-left-radius: 4px;
}

.reticle-corner.bottom-right {
  bottom: -1px;
  right: -1px;
  border-bottom: 2px solid;
  border-right: 2px solid;
  border-bottom-right-radius: 4px;
}

.focus-cursor-reticle.target,
.focus-cursor-reticle.target-locked {
  opacity: 0.92;
  border: 1px solid var(--accent-glow, rgba(56, 189, 248, 0.35));
  background: var(--accent-glow, rgba(56, 189, 248, 0.03));
  box-shadow: 0 0 16px var(--accent-glow, rgba(56, 189, 248, 0.25));
}

.focus-cursor-reticle.target-locked .reticle-corner {
  width: 10px;
  height: 10px;
  opacity: 1;
  border-color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 10px var(--accent-glow, rgba(56, 189, 248, 0.6));
}

.focus-cursor-reticle.card-lock {
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
}

.focus-cursor-reticle.card-lock .reticle-corner {
  width: 18px;
  height: 18px;
  border-width: 2.5px;
  opacity: 1;
  border-color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 12px var(--accent-color, #38bdf8);
}

.focus-cursor-reticle.card-lock .reticle-corner.top-left {
  border-top-left-radius: 6px;
}

.focus-cursor-reticle.card-lock .reticle-corner.top-right {
  border-top-right-radius: 6px;
}

.focus-cursor-reticle.card-lock .reticle-corner.bottom-left {
  border-bottom-left-radius: 6px;
}

.focus-cursor-reticle.card-lock .reticle-corner.bottom-right {
  border-bottom-right-radius: 6px;
}

.focus-cursor-reticle.text {
  opacity: 0 !important;
}

/* Suppress reticle cursor completely in Roguelike Gauntlet, combat arena, and card deck */
body:has(.arena-gauntlet-view) .focus-cursor-reticle,
body:has(.arena-gauntlet-view) .focus-cursor-core,
body:has(.slay-spire-arena-fullscreen) .focus-cursor-reticle,
body:has(.slay-spire-arena-fullscreen) .focus-cursor-core,
.arena-gauntlet-view .focus-cursor-reticle,
.combat-hand-row .focus-cursor-reticle,
.combat-action-card .focus-cursor-reticle {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

.combat-action-card,
.combat-action-card * {
  cursor: pointer !important;
}

@media (pointer: coarse), (hover: none) {
  .focus-cursor-core,
  .focus-cursor-reticle {
    display: none !important;
  }
}

