/* ========================================================
   ANIMATED SVG VECTOR ICONS KEYFRAMES
   ======================================================== */
.animated-svg-flame {
  display: inline-block;
  vertical-align: middle;
}

.flame-outer-path {
  transform-origin: center bottom;
  animation: flameFlicker 1.8s ease-in-out infinite alternate;
}

@keyframes flameFlicker {
  0% { transform: scale(1) rotate(-1deg); }
  50% { transform: scale(1.05, 0.96) rotate(1deg); }
  100% { transform: scale(0.98, 1.04) rotate(0deg); }
}

.flame-spark-1 {
  animation: emberFloat1 2s infinite ease-out;
}

.flame-spark-2 {
  animation: emberFloat2 2.4s infinite ease-out 0.6s;
}

@keyframes emberFloat1 {
  0% { transform: translateY(0); opacity: 0; }
  50% { opacity: 1; }
  100% { transform: translateY(-8px); opacity: 0; }
}

@keyframes emberFloat2 {
  0% { transform: translateY(0); opacity: 0; }
  50% { opacity: 1; }
  100% { transform: translateY(-7px); opacity: 0; }
}

.animated-svg-crown {
  filter: drop-shadow(0 0 10px rgba(251, 191, 36, 0.5));
  animation: crownFloat 2.8s ease-in-out infinite;
}

@keyframes crownFloat {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-3px) rotate(1deg); }
}

.crown-jewel-center {
  animation: jewelTwinkle 1.5s infinite alternate;
}

@keyframes jewelTwinkle {
  0% { opacity: 0.6; transform: scale(0.9); }
  100% { opacity: 1; transform: scale(1.3); }
}

.animated-svg-lightning {
  filter: drop-shadow(0 0 8px rgba(255, 51, 68, 0.6));
  animation: lightningStrike 2s infinite ease-in-out;
}

@keyframes lightningStrike {
  0%, 85%, 100% { transform: scale(1); opacity: 0.9; }
  88% { transform: scale(1.2) rotate(-3deg); opacity: 1; filter: drop-shadow(0 0 14px #ff3344); }
  92% { transform: scale(0.95) rotate(2deg); opacity: 0.8; }
  95% { transform: scale(1.1); opacity: 1; }
}

.animated-svg-swords {
  filter: drop-shadow(0 0 8px rgba(255, 51, 68, 0.4));
}

.sword-left {
  transform-origin: 12px 12px;
  animation: swordClashLeft 3s infinite ease-in-out;
}

.sword-right {
  transform-origin: 12px 12px;
  animation: swordClashRight 3s infinite ease-in-out;
}

.swords-clash-spark {
  transform-origin: 12px 12px;
  animation: clashSpark 3s infinite;
}

@keyframes swordClashLeft {
  0%, 100% { transform: rotate(0deg); }
  45% { transform: rotate(-5deg); }
  50% { transform: rotate(4deg); }
  55% { transform: rotate(0deg); }
}

@keyframes swordClashRight {
  0%, 100% { transform: rotate(0deg); }
  45% { transform: rotate(5deg); }
  50% { transform: rotate(-4deg); }
  55% { transform: rotate(0deg); }
}

@keyframes clashSpark {
  0%, 48%, 56%, 100% { opacity: 0; transform: scale(0); }
  50% { opacity: 1; transform: scale(2.2); filter: drop-shadow(0 0 8px #ffffff); }
}

