/* ========================================================
   MODALS (EDIT PROFILE & AUTH)
   ======================================================== */
.edit-profile-modal-box {
  background: #0b1120;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 18px;
  width: 100%;
  max-width: min(880px, 94vw);
  padding: 22px 26px 14px 26px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.8), 0 0 35px rgba(56, 189, 248, 0.12);
  animation: modalScale 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  max-height: min(92vh, 880px);
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  margin: auto;
  box-sizing: border-box;
  scrollbar-width: thin;
  scrollbar-color: rgba(56, 189, 248, 0.35) rgba(15, 23, 42, 0.5);
}

.edit-profile-modal-box::-webkit-scrollbar {
  width: 7px;
}

.edit-profile-modal-box::-webkit-scrollbar-track {
  background: rgba(15, 23, 42, 0.5);
  border-radius: 4px;
}

.edit-profile-modal-box::-webkit-scrollbar-thumb {
  background: rgba(56, 189, 248, 0.4);
  border-radius: 4px;
}

.edit-profile-modal-box::-webkit-scrollbar-thumb:hover {
  background: rgba(56, 189, 248, 0.7);
}

.edit-profile-modal-box .modal-header {
  position: sticky;
  top: -22px;
  background: #0b1120;
  padding-top: 6px;
  padding-bottom: 10px;
  z-index: 30;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.auth-modal-box {
  background: #0b1120;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 16px;
  width: 100%;
  max-width: 480px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.7);
  animation: modalScale 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  max-height: 90vh;
  overflow-y: auto;
  margin: auto;
  box-sizing: border-box;
}

.modal-live-preview-card {
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 14px;
