/* ========================================================
   ANIMATED UI SVG KEYFRAMES
   ======================================================== */
.animated-svg-sparkle {
  animation: sparkleTwinkle 2.4s infinite ease-in-out;
  transform-origin: 12px 12px;
}

@keyframes sparkleTwinkle {
  0%, 100% { transform: scale(1) rotate(0deg); opacity: 0.85; }
  50% { transform: scale(1.2) rotate(15deg); opacity: 1; filter: drop-shadow(0 0 6px #38bdf8); }
}

.animated-svg-shield-check {
  animation: shieldGentlePulse 3s infinite ease-in-out;
}

@keyframes shieldGentlePulse {
  0%, 100% { transform: scale(1); filter: drop-shadow(0 0 4px rgba(52, 211, 153, 0.3)); }
  50% { transform: scale(1.05); filter: drop-shadow(0 0 10px rgba(52, 211, 153, 0.6)); }
}

.shield-check-tick {
  stroke-dasharray: 20;
  stroke-dashoffset: 0;
  animation: checkDraw 2s ease-in-out infinite alternate;
}

@keyframes checkDraw {
  0% { stroke-dashoffset: 3; opacity: 0.75; }
  100% { stroke-dashoffset: 0; opacity: 1; }
}

.animated-svg-radar .radar-ring-1 {
  animation: radarWave 2s infinite ease-out;
  transform-origin: 12px 12px;
}

.animated-svg-radar .radar-ring-2 {
  animation: radarWave 2s infinite ease-out 0.6s;
  transform-origin: 12px 12px;
}

@keyframes radarWave {
  0% { transform: scale(0.6); opacity: 0.8; }
  100% { transform: scale(1.3); opacity: 0; }
}

