/* Full-Screen Theme Switch Ripple Bloom Wave (120fps GPU-Accelerated Bloom) */
.theme-switch-ripple-portal {
  position: fixed;
  top: 0;
  left: 0;
  width: 140px;
  height: 140px;
  margin-top: -70px;
  margin-left: -70px;
  transform: translate3d(var(--ripple-x, 50vw), var(--ripple-y, 50vh), 0) scale(0.1);
  border-radius: 50%;
  pointer-events: none;
  z-index: 99999;
  background: radial-gradient(circle, var(--ripple-color, #38bdf8) 0%, rgba(255, 255, 255, 0.45) 25%, transparent 72%);
  mix-blend-mode: screen;
  will-change: transform, opacity;
  animation: themeRippleExpand 0.55s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes themeRippleExpand {
  0% {
    transform: translate3d(var(--ripple-x, 50vw), var(--ripple-y, 50vh), 0) scale(0.1);
    opacity: 0.85;
  }
  35% {
    opacity: 0.45;
  }
  100% {
    transform: translate3d(var(--ripple-x, 50vw), var(--ripple-y, 50vh), 0) scale(32);
    opacity: 0;
  }
}

