/* Typography Sandbox */
.typography-sandbox-card {
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.9) 0%, rgba(2, 6, 23, 0.95) 100%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 14px;
  padding: 22px 26px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.sandbox-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding-bottom: 8px;
}

.sandbox-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9.5px;
  font-weight: 800;
  color: #38bdf8;
  letter-spacing: 0.08em;
}

.sandbox-active-font {
  font-size: 11px;
  color: #94a3b8;
  font-weight: 700;
}

.sandbox-headline {
  font-size: clamp(18px, 2.5vw, 24px);
  font-weight: 800;
  color: #ffffff;
  margin: 0;
  line-height: 1.3;
}

.sandbox-body {
  font-size: 13px;
  color: #cbd5e1;
  margin: 0;
  line-height: 1.5;
}

/* Font Family Selection Grid */
.font-family-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 12px;
}

.font-card-btn {
  background: rgba(15, 23, 42, 0.6);
  border: 1.5px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 14px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: left;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.font-card-btn:hover {
  transform: translateY(-2px);
  border-color: rgba(255, 255, 255, 0.25);
  background: rgba(15, 23, 42, 0.8);
}

.font-card-btn.active {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.08);
  box-shadow: 0 0 16px rgba(56, 189, 248, 0.2);
  transform: translateY(-2px);
}

.font-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.font-sample-name {
  font-size: 15px;
  font-weight: 700;
  color: #ffffff;
}

.font-active-badge {
  font-size: 10px;
  font-weight: 800;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.15);
  padding: 2px 6px;
  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.font-sub-desc {
  font-size: 11px;
  color: #94a3b8;
}

.font-specimen {
  font-size: 13px;
  color: #64748b;
  margin-top: 4px;
}

/* Typography Controls Grid */
.typography-controls-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.typo-control-card {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.typo-control-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.control-title {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 800;
  color: #ffffff;
}

.control-value-pill {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 800;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.1);
  padding: 2px 8px;
  border-radius: 12px;
}

.control-desc {
  font-size: 11px;
  color: #94a3b8;
  margin: 0;
  line-height: 1.4;
}

.scale-buttons-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.scale-btn {
  padding: 7px 4px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #94a3b8;
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  text-align: center;
  transition: all 0.15s ease;
}

.scale-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

.scale-btn.active {
  background: #38bdf8;
  color: #0b1120;
  border-color: #38bdf8;
  font-weight: 800;
}

/* Cyber Toggle */
.cyber-toggle-wrap {
  position: relative;
  display: inline-block;
  width: 40px;
  height: 22px;
  cursor: pointer;
}

.cyber-toggle-input {
  opacity: 0;
  width: 0;
  height: 0;
}

.cyber-toggle-track {
  position: absolute;
  inset: 0;
  background: #334155;
  border-radius: 20px;
  transition: 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.cyber-toggle-thumb {
  position: absolute;
  height: 16px;
  width: 16px;
  left: 2px;
  bottom: 2px;
  background: #ffffff;
  border-radius: 50%;
  transition: 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.cyber-toggle-input:checked + .cyber-toggle-track {
  background: #38bdf8;
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.4);
}

.cyber-toggle-input:checked + .cyber-toggle-track .cyber-toggle-thumb {
  transform: translateX(18px);
}

.bold-status-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #94a3b8;
  font-weight: 600;
}

.bold-status-chip .status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #64748b;
}

.bold-status-chip .status-dot.active {
  background: #34d399;
  box-shadow: 0 0 8px #34d399;
}

/* Schedule Card */
.schedule-setting-card {
