  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 18px;
}

.schedule-input-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.schedule-field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
  min-width: 240px;
}

.schedule-field-group label {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.schedule-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.schedule-cal-icon {
  position: absolute;
  left: 12px;
  color: #38bdf8;
  pointer-events: none;
}

.schedule-date-input {
  width: 100%;
  padding: 9px 14px 9px 36px;
  background: rgba(15, 23, 42, 0.8);
