}

.sched-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 700;
  color: #cbd5e1;
}

.sched-pill.highlight {
  border-color: rgba(56, 189, 248, 0.35);
