  gap: 4px;
}

.audio-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 800;
  color: #ffffff;
}

.audio-desc {
  font-size: 11px;
