}

/* Cloud Account Card */
.cloud-account-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 18px 22px;
}

.cloud-account-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

.cloud-account-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cloud-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.cloud-display-name {
  font-family: var(--font-sans);
  font-size: 16px;
  font-weight: 800;
  color: #ffffff;
}

.cloud-verified-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 800;
  color: #34d399;
  background: rgba(52, 211, 153, 0.12);
  border: 1px solid rgba(52, 211, 153, 0.25);
  padding: 2px 6px;
  border-radius: 12px;
}

.cloud-email {
  font-size: 12px;
