}

.cloud-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: #34d399;
}

.cloud-signout-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 6px;
  background: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.25);
  color: #f87171;
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.cloud-signout-btn:hover {
  background: rgba(239, 68, 68, 0.2);
  border-color: #ef4444;
}

/* Cloud Auth Box */
.cloud-auth-box {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 20px;
  max-width: 480px;
  margin: 0 auto;
  width: 100%;
}

.auth-tab-switch-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  background: rgba(0, 0, 0, 0.4);
  padding: 4px;
  border-radius: 8px;
  margin-bottom: 16px;
}

.auth-tab-btn {
  padding: 8px;
  border-radius: 6px;
  background: transparent;
  border: none;
  color: #94a3b8;
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.auth-tab-btn.active {
  background: #38bdf8;
  color: #0b1120;
  font-weight: 800;
}

.cloud-auth-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.auth-form-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.auth-form-field label {
  font-size: 11px;
  color: #94a3b8;
  font-weight: 700;
}

.auth-input-container {
  position: relative;
  display: flex;
  align-items: center;
}

.auth-input-container .auth-icon {
  position: absolute;
  left: 12px;
  color: #64748b;
  pointer-events: none;
}

.auth-input-container input {
  width: 100%;
  padding: 9px 12px 9px 34px;
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  color: #ffffff;
  font-size: 12px;
  outline: none;
}

.auth-input-container input:focus {
  border-color: #38bdf8;
}

.auth-primary-btn {
  padding: 10px;
  border-radius: 6px;
  background: #38bdf8;
  color: #0b1120;
  border: none;
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  margin-top: 4px;
  transition: all 0.15s ease;
}

.auth-primary-btn:hover:not(:disabled) {
