}

.auth-divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 4px 0;
}

.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.divider-label {
  padding: 0 10px;
  font-size: 10px;
  color: #64748b;
  font-weight: 700;
}

/* Portability Cards */
.portability-cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
}

.portability-action-card {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 14px;
}

.port-card-top {
  display: flex;
  gap: 12px;
}

.port-icon-wrap {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.port-icon-wrap.export {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
}

.port-icon-wrap.import {
  background: rgba(52, 211, 153, 0.12);
  color: #34d399;
}

.port-icon-wrap.reset {
  background: rgba(239, 68, 68, 0.12);
  color: #ef4444;
}

.port-card-title {
  display: block;
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 800;
  color: #ffffff;
}

.port-card-desc {
  display: block;
  font-size: 11px;
  color: #94a3b8;
  margin-top: 2px;
  line-height: 1.4;
}

.port-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.port-btn.export {
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.3);
  color: #38bdf8;
}

.port-btn.export:hover {
  background: #38bdf8;
  color: #0b1120;
}

.port-btn.import {
  background: rgba(52, 211, 153, 0.12);
  border: 1px solid rgba(52, 211, 153, 0.3);
  color: #34d399;
}

.port-btn.import:hover {
  background: #34d399;
  color: #0b1120;
}

.port-btn.reset {
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #f87171;
}

.port-btn.reset:hover {
  background: #ef4444;
  color: #ffffff;
}

