    justify-content: center !important;
  }

  .vip-code-form {
    flex-direction: column !important;
  }

  .vip-submit-btn {
    width: 100% !important;
  }
}

/* ==========================================================================
   CLEAN & MINIMAL SESSION COMPLETION MODAL (Theme-Adaptive)
   ========================================================================== */

.session-modal-overlay {
  position: fixed !important;
  inset: 0 !important;
  z-index: 1000000 !important;
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  animation: sessionBackdropFade 0.2s ease-out;
}

.session-modal-card {
  position: relative;
  background: var(--bg-secondary, #121215);
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.12));
  border-radius: 16px;
  max-width: 440px;
  width: 100%;
  padding: 20px 22px;
  box-shadow: var(--card-shadow, 0 16px 50px rgba(0, 0, 0, 0.6));
  animation: sessionCardScale 0.22s cubic-bezier(0.16, 1, 0.3, 1);
  color: var(--text-primary, #ffffff);
}

.session-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
  margin-bottom: 14px;
}

.session-modal-head-left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.session-subject-badge {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  padding: 3px 8px;
  border-radius: 5px;
  text-transform: uppercase;
  background: var(--bg-tertiary, rgba(255, 255, 255, 0.06));
  color: var(--text-primary, #ffffff);
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.1));
}

.session-subject-badge.quant {
  border-color: rgba(56, 189, 248, 0.4);
  color: #38bdf8;
}

.session-subject-badge.lrdi {
  border-color: rgba(192, 132, 252, 0.4);
  color: #c084fc;
}

.session-subject-badge.varc {
  border-color: rgba(251, 191, 36, 0.4);
  color: #fbbf24;
}

.session-duration-tag {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary, #94a3b8);
  font-family: 'JetBrains Mono', monospace;
}

.session-modal-close-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary, #94a3b8);
  cursor: pointer;
  padding: 4px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast, 0.15s ease);
}

.session-modal-close-btn:hover {
  background: var(--bg-tertiary, rgba(255, 255, 255, 0.08));
  color: var(--text-primary, #ffffff);
}

.session-modal-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary, #ffffff);
  margin: 0 0 14px 0;
  letter-spacing: -0.01em;
}

/* Compact Quota Strip */
.session-clean-quota-strip {
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: var(--bg-primary, rgba(0, 0, 0, 0.3));
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
  border-radius: 12px;
  padding: 12px 14px;
  margin-bottom: 12px;
}

.quota-summary-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.quota-summary-item {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 11px;
}

.summary-lbl {
  color: var(--text-secondary, #94a3b8);
  font-weight: 600;
}

.summary-val {
  color: var(--text-primary, #ffffff);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 800;
}

.week-item {
  font-size: 10px;
  opacity: 0.85;
}

.clean-progress-track {
  width: 100%;
  height: 5px;
  background: var(--bg-tertiary, rgba(255, 255, 255, 0.08));
  border-radius: 999px;
  overflow: hidden;
}

.clean-progress-fill {
  height: 100%;
