}

.clean-quota-diff-line {
  display: flex;
  align-items: center;
}

.status-badge {
  font-size: 11px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.status-badge.under {
  color: var(--text-secondary, #cbd5e1);
}

.status-badge.cleared {
  color: #10b981;
  font-weight: 700;
}

/* Minimal Stepper & Chips */
.clean-stepper-box {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 4px;
}

.clean-input-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary, #94a3b8);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.clean-stepper-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.clean-stepper-wrap {
  display: inline-flex;
  align-items: center;
  background: var(--bg-tertiary, rgba(0, 0, 0, 0.45));
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.12));
  border-radius: 8px;
  overflow: hidden;
}

.stepper-arrow-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary, #94a3b8);
  width: 30px;
  height: 30px;
  font-size: 14px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast, 0.15s ease);
}

.stepper-arrow-btn:hover {
  background: var(--bg-secondary, rgba(255, 255, 255, 0.08));
  color: var(--text-primary, #ffffff);
}

.clean-stepper-input {
  width: 42px;
  height: 30px;
  text-align: center;
  background: transparent;
  border: none;
  color: var(--text-primary, #ffffff);
  font-family: 'JetBrains Mono', monospace;
  font-size: 13px;
  font-weight: 800;
  outline: none;
  -moz-appearance: textfield;
  appearance: textfield;
}

.clean-stepper-input::-webkit-outer-spin-button,
.clean-stepper-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
  display: none;
}

.clean-chips-wrap {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.clean-chip-btn {
  background: var(--bg-tertiary, rgba(255, 255, 255, 0.04));
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
  border-radius: 6px;
  padding: 4px 9px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary, #94a3b8);
  cursor: pointer;
  transition: all var(--transition-fast, 0.15s ease);
}

.clean-chip-btn:hover {
  background: var(--bg-secondary, rgba(255, 255, 255, 0.1));
  color: var(--text-primary, #ffffff);
}

.clean-chip-btn.selected {
  background: var(--accent-glow, rgba(56, 189, 248, 0.2));
  border-color: var(--accent-color, #38bdf8);
  color: var(--accent-color, #38bdf8);
}

/* Clean Checkbox */
.clean-checkbox-row {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  margin-top: 2px;
  user-select: none;
}

.clean-check-box {
  width: 15px;
  height: 15px;
  accent-color: var(--accent-color, #10b981);
  cursor: pointer;
}

.clean-check-text {
  font-size: 11px;
  color: var(--text-secondary, #cbd5e1);
}

/* General Note */
.clean-general-note {
  font-size: 12px;
  color: var(--text-secondary, #cbd5e1);
  background: var(--bg-primary, rgba(0, 0, 0, 0.3));
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
  border-radius: 8px;
  padding: 10px 12px;
  margin-bottom: 12px;
}

/* Note input */
.clean-note-wrap {
  margin-bottom: 14px;
}

.clean-note-input {
  width: 100%;
  box-sizing: border-box;
  background: var(--bg-primary, rgba(0, 0, 0, 0.25));
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
  border-radius: 8px;
  padding: 8px 10px;
  color: var(--text-primary, #ffffff);
  font-size: 11px;
  font-family: inherit;
  outline: none;
  transition: border-color var(--transition-fast, 0.15s ease);
}

.clean-note-input:focus {
  border-color: var(--accent-color, #38bdf8);
}

/* Clean Modal Foot */
.clean-modal-foot {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
}

.clean-foot-btn {
  font-size: 11px;
  font-weight: 700;
  padding: 7px 14px;
  border-radius: 7px;
  cursor: pointer;
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.12));
}

.clean-foot-btn.primary {
  background: var(--accent-color, #38bdf8);
  color: var(--accent-text, #000000);
  border-color: var(--accent-color, #38bdf8);
}

/* ==========================================================================
   DAILY QUOTA CONQUERED CELEBRATION MODAL & HEATMAP STAMP
   ========================================================================== */

.quota-celebrate-backdrop {
  position: fixed !important;
  inset: 0 !important;
  z-index: 1000000 !important;
  background: rgba(0, 0, 0, 0.82);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: celebrateBackdropFade 0.25s ease-out;
}

@keyframes celebrateBackdropFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

.quota-celebrate-card {
  position: relative;
  background: var(--bg-secondary, #0f172a);
  border: 1.5px solid var(--accent-color, #10b981);
  border-radius: 24px;
  max-width: 480px;
  width: 100%;
  padding: 34px 28px 26px 28px;
  text-align: center;
  color: var(--text-primary, #ffffff);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.8), 0 0 50px var(--accent-glow, rgba(16, 185, 129, 0.28));
  animation: celebratePopIn 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
}

@keyframes celebratePopIn {
  0% { transform: scale(0.82) translateY(24px); opacity: 0; }
  70% { transform: scale(1.02) translateY(-2px); opacity: 1; }
  100% { transform: scale(1) translateY(0); }
}

.celebrate-glow-halo {
  position: absolute;
  top: -60px;
  left: 50%;
  transform: translateX(-50%);
  width: 280px;
  height: 280px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--accent-glow, rgba(16, 185, 129, 0.35)) 0%, transparent 70%);
  filter: blur(50px);
  pointer-events: none;
}

/* Floating Particles */
.celebrate-particles-wrap {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.celebrate-particle {
  position: absolute;
  top: 40%;
  left: 50%;
  background: var(--accent-color, #10b981);
  border-radius: 50%;
  opacity: 0;
  animation: celebrateParticleBurst 1.8s infinite cubic-bezier(0.25, 1, 0.5, 1);
  animation-delay: var(--delay, 0s);
}

@keyframes celebrateParticleBurst {
  0% {
    transform: translate(-50%, -50%) scale(0.2);
    opacity: 1;
  }
  60% {
    opacity: 0.85;
  }
  100% {
    transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1.1);
    opacity: 0;
  }
}

/* Cat Art SVG */
.celebrate-cat-art-wrap {
  display: flex;
  justify-content: center;
  margin-bottom: 8px;
}

.celebrate-cat-svg {
  animation: celebrateCatFloat 3.2s infinite ease-in-out;
  filter: drop-shadow(0 10px 24px rgba(0, 0, 0, 0.45));
}

@keyframes celebrateCatFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-5px); }
}

.scholar-cap-float {
  animation: capTasselSway 2.8s infinite alternate ease-in-out;
  transform-origin: 85px 36px;
}

@keyframes capTasselSway {
  0% { transform: rotate(-1.5deg); }
  100% { transform: rotate(1.5deg); }
}

/* Badge */
.celebrate-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--accent-color, #10b981);
  background: var(--accent-glow, rgba(16, 185, 129, 0.14));
  border: 1px solid var(--accent-color, #10b981);
  padding: 4px 14px;
  border-radius: 12px;
  margin-bottom: 12px;
}

/* Title & Message */
.celebrate-title {
  font-family: 'Syne', sans-serif;
  font-size: 24px;
  font-weight: 900;
  color: var(--text-primary, #ffffff);
  margin: 0 0 10px 0;
  letter-spacing: -0.02em;
  line-height: 1.25;
}

.celebrate-message {
  font-size: 13px;
  line-height: 1.55;
  color: var(--text-secondary, #cbd5e1);
  margin: 0 0 18px 0;
  font-weight: 500;
}

/* Heatmap Stamp Box */
.celebrate-heatmap-box {
  background: var(--bg-primary, rgba(0, 0, 0, 0.35));
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.1));
  border-radius: 14px;
  padding: 14px 16px;
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.heatmap-box-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary, #94a3b8);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.heatmap-box-streak {
  color: #f59e0b;
  font-family: 'JetBrains Mono', monospace;
  font-weight: 800;
}

.heatmap-mini-week-row {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
  align-items: center;
  margin: 4px 0;
}

.mini-day-cell-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.mini-heatmap-cell {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  border-radius: 6px;
  background: var(--bg-tertiary, rgba(255, 255, 255, 0.05));
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
  transition: all 0.4s ease;
}

.mini-heatmap-cell.pending-today {
  border: 1.5px dashed var(--accent-color, #10b981);
}

.mini-heatmap-cell.stamped-today {
  background: #10b981 !important;
  border-color: #34d399 !important;
  box-shadow: 0 0 16px rgba(16, 185, 129, 0.8) !important;
  animation: stampPop 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

@keyframes stampPop {
  0% { transform: scale(0.6); opacity: 0.4; }
  60% { transform: scale(1.25); }
  100% { transform: scale(1); opacity: 1; }
}

.stamp-sparkle-dot {
  position: absolute;
  inset: 2px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 4px;
  animation: sparkleFlash 1.5s infinite alternate ease-in-out;
}

@keyframes sparkleFlash {
  0% { opacity: 0.2; }
  100% { opacity: 0.8; }
}

.mini-day-name {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-secondary, #94a3b8);
}

.heatmap-stamp-caption {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 11.5px;
  color: #10b981;
  font-weight: 600;
}

.heatmap-stamp-caption strong {
  font-weight: 800;
}

/* Button & Cross */
.celebrate-btn-row {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.celebrate-claim-btn {
  width: 100%;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 800;
  background: var(--accent-color, #10b981);
  color: var(--accent-text, #000000);
  border: none;
  cursor: pointer;
  box-shadow: 0 8px 24px var(--accent-glow, rgba(16, 185, 129, 0.4));
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.celebrate-claim-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 32px var(--accent-glow, rgba(16, 185, 129, 0.6));
}

.celebrate-close-cross {
  position: absolute;
  top: 16px;
  right: 16px;
  background: transparent;
  border: none;
  color: var(--text-secondary, #94a3b8);
  cursor: pointer;
  padding: 6px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.celebrate-close-cross:hover {
  background: var(--bg-tertiary, rgba(255, 255, 255, 0.08));
  color: var(--text-primary, #ffffff);
}

/* Clickable Quota Tally on Daily Drills */
.day-quota-tally.clickable-celebrate {
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.day-quota-tally.clickable-celebrate:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px var(--accent-glow, rgba(16, 185, 129, 0.25));
}

