/* ==========================================================================
   REACTBITS ANIMATIONS (DecryptedText, Counter, Dock)
   ========================================================================== */

/* 1. DecryptedText */
.decrypted-text-root {
  display: inline-block;
  user-select: none;
  font-family: inherit;
  letter-spacing: inherit;
}

.decrypted-char-scrambled {
  color: var(--accent-color, #38bdf8);
  opacity: 0.85;
  text-shadow: 0 0 8px var(--accent-glow, rgba(56, 189, 248, 0.5));
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  display: inline-block;
  transform: scale(1.05);
  transition: color 0.1s ease;
}

.decrypted-char-real {
  display: inline;
  color: inherit;
}

/* 2. Counter (Mechanical Odometer / Ticker) */
.reactbits-counter-root {
  display: inline-flex;
  align-items: center;
  overflow: hidden;
  line-height: 1;
  vertical-align: middle;
}

.counter-digit-window {
  display: inline-block;
  position: relative;
  overflow: hidden;
  height: 1.15em;
}

.counter-digit-track {
  will-change: transform;
}

.counter-number-val {
  height: 1.15em;
  display: flex;
  align-items: center;
  justify-content: center;
  font-variant-numeric: tabular-nums;
  line-height: 1.15em;
}

.counter-symbol {
  display: inline-flex;
  align-items: center;
}

/* 3. Dock (macOS-Style Magnification Dock) */
.reactbits-dock-container {
  position: relative;
  transition: padding 0.2s ease;
}

.reactbits-dock-container.vertical {
  width: 100%;
  gap: 6px;
}

.reactbits-dock-container.horizontal {
  gap: 4px;
}

.reactbits-dock-item {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  color: var(--text-secondary, #94a3b8);
  padding: 0;
  outline: none;
  will-change: transform;
}

.reactbits-dock-item:hover {
  color: var(--text-primary, #ffffff);
}

.reactbits-dock-item.active {
  color: var(--accent-color, #38bdf8);
}

.dock-icon-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.dock-active-glow-pill {
  position: absolute;
  background: var(--accent-color, #38bdf8);
  box-shadow: 0 0 10px var(--accent-glow, rgba(56, 189, 248, 0.6));
  border-radius: 4px;
  pointer-events: none;
}

.vertical .dock-active-glow-pill {
  left: -8px;
  width: 3px;
  height: 18px;
  top: 50%;
  transform: translateY(-50%);
}

.horizontal .dock-active-glow-pill {
  bottom: -4px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  left: 50%;
  transform: translateX(-50%);
}

/* Mobile Bottom Navigation Dock Styling */
.mobile-dock-wrap {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-around;
  height: 100%;
}

.mobile-dock-btn {
  border-radius: 14px;
}

.mobile-dock-btn.active {
  color: var(--accent-color, #38bdf8);
}

/* 4. Skiper UI 37 Animated Timer */
.skiper-animated-timer-root {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.skiper-digit-window {
  display: inline-block;
  overflow: hidden;
  height: 1.08em;
  line-height: 1.08em;
}

.skiper-digit-track {
  will-change: transform;
}

.skiper-digit-number {
  height: 1.08em;
  display: flex;
  align-items: center;
  justify-content: center;
  font-variant-numeric: tabular-nums;
  line-height: 1.08em;
}

.skiper-timer-colon {
  display: inline-block;
  margin: 0 0.04em;
  opacity: 0.85;
  animation: colonPulse 1.6s infinite ease-in-out;
}

@keyframes colonPulse {
  0%, 100% { opacity: 0.9; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.96); }
}

