/* ==========================================================================
   CHRONOGRAPH HUD TIMER BEZEL
   ========================================================================== */
.chrono-hud-container {
  position: relative;
  width: 320px;
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto;
}

.chrono-hud-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.chrono-center-content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.chrono-beacon-dot {
  animation: beaconPulse 1.2s infinite alternate ease-in-out;
}

@keyframes beaconPulse {
  0% { r: 3.5; opacity: 0.8; }
  100% { r: 5; opacity: 1; filter: drop-shadow(0 0 8px #ffffff); }
}

.chrono-progress-arc.static-stopwatch {
  filter: drop-shadow(0 0 6px var(--accent-glow, rgba(56, 189, 248, 0.4)));
}

/* ==========================================================================
   WORD HOVER KINETIC EFFECT
   ========================================================================== */
.word-hover-root {
  display: inline-block;
  position: relative;
  overflow: hidden;
  vertical-align: bottom;
  cursor: pointer;
  line-height: inherit;
  font-family: inherit;
}

.word-hover-track {
  display: inline-flex;
  flex-direction: column;
  line-height: 1.15em;
  transform: translateY(0);
  transition: transform 0.32s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: transform;
}

.word-hover-root:hover .word-hover-track {
  transform: translateY(-50%);
}

.word-hover-primary {
  display: inline-block;
  color: inherit;
  transition: opacity 0.2s ease;
}

.word-hover-secondary {
  display: inline-block;
  color: var(--accent-color, #38bdf8);
  font-style: italic;
  text-shadow: 0 0 12px var(--accent-glow, rgba(56, 189, 248, 0.6));
  letter-spacing: inherit;
}

