/* ==========================================================================
   JAPANESE CAT STAMP RALLY & WASHI PAPER CARD (スタンプラリー)
   ========================================================================== */

.stamp-rally-backdrop {
  position: fixed;
  inset: 0;
  z-index: 999999;
  background: rgba(5, 7, 15, 0.84);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  animation: fadeIn 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.stamp-rally-dialog-card {
  position: relative;
  width: 100%;
  max-width: 660px;
  max-height: 94vh;
  overflow-y: auto;
  overflow-x: hidden;
  background: #0d111d;
  border: 1px solid rgba(244, 63, 94, 0.35);
  border-radius: 20px;
  padding: 24px;
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.8), 0 0 40px rgba(244, 63, 94, 0.15);
  color: #f8fafc;
  display: flex;
  flex-direction: column;
  gap: 18px;
  animation: stampModalEntrance 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes stampModalEntrance {
  0% {
    opacity: 0;
    transform: scale(0.92) translateY(20px);
  }
  60% {
    transform: scale(1.01) translateY(-2px);
  }
  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.stamp-rally-ambient-glow {
  position: absolute;
  top: -80px;
  left: 50%;
  transform: translateX(-50%);
  width: 380px;
  height: 200px;
  background: radial-gradient(circle, rgba(244, 63, 94, 0.24) 0%, rgba(251, 191, 36, 0.14) 60%, transparent 100%);
  filter: blur(40px);
  pointer-events: none;
  animation: lanternBreathe 4.5s ease-in-out infinite alternate;
}

@keyframes lanternBreathe {
  0% {
    opacity: 0.45;
    transform: translateX(-50%) scale(0.92);
  }
  50% {
    opacity: 0.85;
    transform: translateX(-50%) scale(1.08);
  }
  100% {
    opacity: 0.45;
    transform: translateX(-50%) scale(0.92);
  }
}

.stamp-rally-close-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #94a3b8;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 10;
}

.stamp-rally-close-btn:hover {
  background: rgba(244, 63, 94, 0.25);
  color: #ffffff;
  border-color: rgba(244, 63, 94, 0.6);
  transform: rotate(90deg) scale(1.08);
}

.stamp-rally-modal-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  position: relative;
  z-index: 2;
  padding: 0 8px;
}

.stamp-badge-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  background: rgba(244, 63, 94, 0.14);
  border: 1px solid rgba(244, 63, 94, 0.3);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: #fb7185;
  box-shadow: 0 0 12px rgba(244, 63, 94, 0.15);
  max-width: 100%;
}

.shinto-sun-circle {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #f43f5e;
  box-shadow: 0 0 8px #f43f5e;
  flex-shrink: 0;
  animation: sunPulse 2s ease-in-out infinite;
}

@keyframes sunPulse {
  0%, 100% { transform: scale(1); opacity: 0.9; }
  50% { transform: scale(1.25); opacity: 1; }
}

.stamp-rally-modal-title {
  font-family: var(--font-display, 'Outfit', sans-serif);
  font-size: clamp(20px, 4.5vw, 26px);
  font-weight: 900;
  letter-spacing: 0.04em;
  color: #ffffff;
  margin: 0;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.6);
}

.stamp-rally-instructions {
  font-size: clamp(11px, 2.8vw, 12px);
  color: #94a3b8;
  letter-spacing: 0.02em;
  margin: 0;
  max-width: 480px;
  line-height: 1.45;
}

/* 2. Minimalist Japanese Washi-Paper Stamp Card */
.washi-paper-card-wrapper {
  background: linear-gradient(155deg, #fefcf9 0%, #f7f3ea 100%);
  border: 1px solid rgba(214, 199, 178, 0.65);
  border-radius: 16px;
  padding: 18px 20px;
  box-shadow: 
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    0 12px 36px rgba(0, 0, 0, 0.45);
  color: #292524;
  position: relative;
  overflow: hidden;
}

/* Subtle Washi Silk Shimmer Reflection */
.washi-paper-card-wrapper::after {
  content: '';
  position: absolute;
  top: 0;
  left: -120%;
  width: 60%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.45), transparent);
  transform: skewX(-20deg);
  pointer-events: none;
  animation: washiSilkSweep 8s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

@keyframes washiSilkSweep {
  0% { left: -120%; }
  22%, 100% { left: 220%; }
}

.washi-card-inner {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.washi-card-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(180, 150, 120, 0.22);
  padding-bottom: 10px;
  gap: 8px;
}

.washi-card-title-lockup {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.washi-stamp-seal-emblem {
  width: 30px;
  height: 30px;
  border: 1.5px solid #b91c1c;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(185, 28, 28, 0.06);
  color: #b91c1c;
  font-family: serif;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.05em;
  flex-shrink: 0;
  box-shadow: 0 0 8px rgba(185, 28, 28, 0.15);
}

.washi-title-text-group {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.washi-top-title {
  font-size: clamp(13.5px, 3.8vw, 15px);
  font-weight: 800;
  color: #1c1917;
  letter-spacing: 0.08em;
  line-height: 1.1;
  white-space: nowrap;
}

.washi-card-sub-japanese {
  font-size: clamp(9.5px, 2.7vw, 10.5px);
  font-weight: 600;
  color: #78716c;
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.washi-card-progress-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: rgba(185, 28, 28, 0.07);
  border: 1px solid rgba(185, 28, 28, 0.2);
  border-radius: 999px;
  padding: 3px 9px;
  font-size: clamp(9.5px, 2.5vw, 10.5px);
  font-weight: 800;
  color: #b91c1c;
  letter-spacing: 0.08em;
  white-space: nowrap;
  flex-shrink: 0;
}

.washi-pill-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #b91c1c;
  box-shadow: 0 0 6px rgba(185, 28, 28, 0.5);
  animation: sunPulse 1.8s ease-in-out infinite;
}

/* Washi Slots Grid (Fluid 3 columns) */
.washi-slots-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px 8px;
  padding-top: 2px;
}

.washi-slot-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: transform 0.28s cubic-bezier(0.34, 1.56, 0.64, 1);
  user-select: none;
  min-width: 0;
}

.washi-slot-box:hover {
  transform: translateY(-4px) scale(1.03);
}

.washi-slot-circle {
  width: clamp(66px, 18vw, 92px);
  height: clamp(66px, 18vw, 92px);
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  background: #ffffff;
  box-shadow: 
    inset 0 2px 4px rgba(0, 0, 0, 0.03),
    0 2px 6px rgba(0, 0, 0, 0.04);
  border: 1.5px dashed rgba(180, 150, 120, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.washi-slot-box:hover .washi-slot-circle {
  border-color: rgba(185, 28, 28, 0.55);
  box-shadow: 0 6px 18px rgba(185, 28, 28, 0.16), 0 0 0 2.5px rgba(185, 28, 28, 0.12);
}

.washi-slot-box.stamped .washi-slot-circle {
  border-style: solid;
  border-color: rgba(185, 28, 28, 0.3);
  background: #fffdf9;
}

/* Minimalist watermark when not yet stamped */
.washi-slot-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  transition: all 0.2s ease;
}

.washi-kanji-watermark {
  font-family: serif;
  font-size: clamp(20px, 5.5vw, 26px);
  font-weight: 700;
  color: #a89f91;
  opacity: 0.28;
  line-height: 1;
  transition: all 0.25s ease;
}

.washi-slot-box:hover .washi-kanji-watermark {
  transform: scale(1.15);
  opacity: 0.6;
  color: #b91c1c;
}

.washi-slot-number {
  font-size: clamp(8.5px, 2.2vw, 9.5px);
  font-weight: 700;
  color: #a89f91;
  letter-spacing: 0.1em;
  margin-top: 2px;
  opacity: 0.65;
}

/* Hanko Vermilion Red Ink Seal */
.hanko-ink-seal {
  position: relative;
  width: 90%;
  height: 90%;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #b91c1c;
  background: radial-gradient(circle, rgba(254, 242, 242, 0.55) 0%, rgba(254, 202, 202, 0.18) 80%, transparent 100%);
}

.hanko-slam-in {
  animation: hankoStampSlam 0.55s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}

@keyframes hankoStampSlam {
  0% {
    transform: scale(2.8) rotate(-18deg);
    opacity: 0;
    filter: blur(4px);
  }
  50% {
    transform: scale(0.88) rotate(3deg);
    opacity: 1;
    filter: blur(0);
  }
  75% {
    transform: scale(1.06) rotate(-1deg);
  }
  100% {
    transform: scale(1) rotate(0deg);
    opacity: 1;
  }
}

.hanko-ink-shockwave {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid rgba(185, 28, 28, 0.6);
  animation: inkShockwave 0.85s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  pointer-events: none;
}

@keyframes inkShockwave {
  0% {
    transform: scale(0.7);
    opacity: 0.9;
  }
  100% {
    transform: scale(1.4);
    opacity: 0;
  }
}

.hanko-scallop-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.hanko-top-arc {
  position: absolute;
  top: 6px;
  font-size: clamp(6.5px, 1.8vw, 7.5px);
  font-weight: 900;
  letter-spacing: 0.12em;
  color: #b91c1c;
}

.hanko-mascot-art {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
}

.hanko-kanji-label {
  position: absolute;
  bottom: 6px;
  font-size: clamp(7.5px, 2vw, 8.5px);
  font-weight: 900;
  letter-spacing: 0.1em;
  color: #b91c1c;
  background: rgba(255, 255, 255, 0.78);
  padding: 0 4px;
  border-radius: 3px;
}

.hanko-ink-texture {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(circle, transparent 70%, rgba(185, 28, 28, 0.08) 100%);
  pointer-events: none;
}

.washi-slot-caption {
  font-size: clamp(8.5px, 2.2vw, 10.5px);
  font-weight: 700;
  color: #78716c;
  margin-top: 5px;
  letter-spacing: 0.04em;
  text-align: center;
  font-family: 'JetBrains Mono', monospace;
  transition: color 0.15s ease;
  width: 100%;
  line-height: 1.25;
  overflow-wrap: break-word;
  word-break: break-word;
}

.washi-slot-caption .caption-stamped {
  color: #b91c1c;
  font-weight: 800;
}

/* 3. Prize Redemption Tray */
.stamp-rally-rewards-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 14px;
  padding: 14px 16px;
}

.rewards-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
}

.rewards-header-tag {
  color: #f43f5e;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.rewards-stamp-counter {
  color: #94a3b8;
  font-size: 11px;
}

.rewards-stamp-counter strong {
  color: #fbbf24;
  font-size: 12px;
}

.rewards-progress-bar {
  width: 100%;
  height: 5px;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 999px;
  overflow: hidden;
}

.rewards-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #f43f5e 0%, #fb923c 35%, #f59e0b 70%, #f43f5e 100%);
  background-size: 250% 100%;
  border-radius: 999px;
  transition: width 0.5s cubic-bezier(0.16, 1, 0.3, 1);
  animation: fluidShine 3.5s linear infinite;
}

@keyframes fluidShine {
  0% { background-position: 0% 50%; }
  100% { background-position: 250% 50%; }
}

.rewards-cards-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.reward-prize-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(18, 24, 38, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  padding: 10px 14px;
  gap: 12px;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.reward-prize-card:hover {
  background: rgba(18, 24, 38, 0.9);
  border-color: rgba(255, 255, 255, 0.14);
  transform: translateY(-1px);
}

.reward-prize-card.eligible {
  border-color: rgba(251, 191, 36, 0.45);
  background: rgba(251, 191, 36, 0.06);
  box-shadow: 0 0 16px rgba(251, 191, 36, 0.08);
}

.reward-prize-card.claimed {
  border-color: rgba(52, 211, 153, 0.35);
  background: rgba(52, 211, 153, 0.04);
}

.prize-card-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}

.prize-swatch-cluster {
  display: flex;
  gap: 3px;
  padding: 4px;
  background: rgba(0, 0, 0, 0.4);
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  flex-shrink: 0;
}

.prize-swatch-cluster span {
  width: 9px;
  height: 16px;
  border-radius: 2.5px;
}

.prize-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.prize-name {
  font-size: 12.5px;
  font-weight: 700;
  color: #ffffff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.prize-sub {
  font-size: 10.5px;
  color: #71717a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.prize-status-pill {
  font-size: 10px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 6px;
  white-space: nowrap;
  font-family: 'JetBrains Mono', monospace;
  flex-shrink: 0;
}

.prize-status-pill.locked {
  background: rgba(255, 255, 255, 0.04);
  color: #71717a;
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.prize-status-pill.unlocked {
  background: rgba(16, 185, 129, 0.15);
  color: #10b981;
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.prize-redeem-btn {
  padding: 6px 12px;
  border-radius: 7px;
  border: none;
  background: #f43f5e;
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
  transition: all 0.2s ease;
  box-shadow: 0 0 10px rgba(244, 63, 94, 0.3);
}

.prize-redeem-btn:hover {
  background: #fb7185;
  transform: translateY(-1px);
  box-shadow: 0 0 14px rgba(244, 63, 94, 0.5);
}

.prize-redeem-btn.grand-prize {
  background: #f59e0b;
  color: #09090b;
  box-shadow: 0 0 10px rgba(245, 158, 11, 0.3);
}

.prize-redeem-btn.grand-prize:hover {
  background: #fbbf24;
  box-shadow: 0 0 14px rgba(245, 158, 11, 0.5);
}

/* 4. Mobile Responsive Rules (< 540px) */
@media (max-width: 540px) {
  .stamp-rally-backdrop {
    padding: 8px;
  }
  .stamp-rally-dialog-card {
    padding: 16px 12px;
    gap: 12px;
    border-radius: 16px;
    max-height: 96vh;
  }
  .stamp-rally-close-btn {
    top: 12px;
    right: 12px;
    width: 28px;
    height: 28px;
  }
  .stamp-rally-modal-header {
    padding-right: 30px;
    gap: 4px;
  }
  .stamp-badge-tag {
    font-size: 9.5px;
    padding: 3px 8px;
    letter-spacing: 0.08em;
  }
  .stamp-rally-modal-title {
    font-size: clamp(16px, 5vw, 20px);
  }
  .stamp-rally-instructions {
    font-size: 10.5px;
    line-height: 1.35;
  }
  .washi-paper-card-wrapper {
    padding: 12px 10px;
    border-radius: 12px;
  }
  .washi-card-header-row {
    padding-bottom: 8px;
    gap: 6px;
  }
  .washi-stamp-seal-emblem {
    width: 26px;
    height: 26px;
    font-size: 9.5px;
  }
  .washi-top-title {
    font-size: 12.5px;
  }
  .washi-card-sub-japanese {
    font-size: 9px;
  }
  .washi-card-progress-pill {
    font-size: 9px;
    padding: 2px 7px;
  }
  .washi-slots-grid {
    gap: 10px 4px;
  }
  .washi-slot-circle {
    width: clamp(62px, 20vw, 76px);
    height: clamp(62px, 20vw, 76px);
  }
  .washi-kanji-watermark {
    font-size: clamp(18px, 5.5vw, 22px);
  }
  .washi-slot-number {
    font-size: 8px;
  }
  .washi-slot-caption {
    font-size: clamp(8px, 2.3vw, 9.5px);
    letter-spacing: 0.01em;
    line-height: 1.2;
    margin-top: 4px;
  }
  .rewards-panel-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 3px;
  }
  .reward-prize-card {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
    padding: 10px;
  }
  .prize-card-left {
    width: 100%;
  }
  .prize-card-right {
    width: 100%;
    display: flex;
    justify-content: flex-end;
  }
  .prize-name {
    font-size: 12px;
    white-space: normal;
  }
  .prize-sub {
    font-size: 10px;
    white-space: normal;
  }
}

/* 5. Lore Inspection Popover */
.stamp-lore-popover {
  position: fixed;
  inset: 0;
  z-index: 1000000;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  animation: fadeIn 0.2s ease-out;
}

.stamp-lore-card {
  background: #141a29;
  border: 1px solid rgba(244, 63, 94, 0.4);
  border-radius: 16px;
  padding: 20px;
  max-width: 440px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.75);
  animation: scrollUnfurl 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes scrollUnfurl {
  0% {
    opacity: 0;
    transform: scale(0.9) translateY(14px);
  }
  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.lore-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.lore-reason-pill {
  font-size: 10.5px;
  font-weight: 700;
  color: #f43f5e;
  background: rgba(244, 63, 94, 0.12);
  padding: 3px 8px;
  border-radius: 4px;
}

.lore-close-x {
  background: transparent;
  border: none;
  color: #94a3b8;
  font-size: 20px;
  cursor: pointer;
  line-height: 1;
}

.lore-stamp-title {
  font-size: 17px;
  font-weight: 800;
  color: #ffffff;
  margin: 0;
}

.lore-stamp-text {
  font-size: 13px;
  line-height: 1.6;
  color: #cbd5e1;
  margin: 0;
}

.lore-confirm-btn {
  align-self: flex-end;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #ffffff;
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.lore-confirm-btn:hover {
  background: rgba(244, 63, 94, 0.2);
  border-color: rgba(244, 63, 94, 0.4);
}

/* Celebration Modal Stamp Rally Action Button */
.stamp-rally-action-btn {
  background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%) !important;
  color: #ffffff !important;
  box-shadow: 0 6px 20px rgba(220, 38, 38, 0.4) !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}

.celebrate-sub-btn {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #94a3b8;
  padding: 11px 20px;
  border-radius: 8px;
  font-size: 13.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.celebrate-sub-btn:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.06);
}

/* Cyber-Bento Stamp Rally Badge Button for Header / Top Bar */
.stamp-rally-header-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  box-sizing: border-box;
  background: rgba(244, 63, 94, 0.08);
  border: 1px solid rgba(244, 63, 94, 0.28);
  border-radius: 8px;
  padding: 0 10px;
  color: #f43f5e;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  user-select: none;
}

.stamp-rally-header-pill:hover {
  background: rgba(244, 63, 94, 0.16);
  border-color: #f43f5e;
  transform: translateY(-1px);
  box-shadow: 0 0 14px rgba(244, 63, 94, 0.3);
  color: #ffffff;
}

.stamp-pill-icon {
  width: 14px;
  height: 14px;
}

/* Mobile Responsiveness for Stamp Rally Card */
@media (max-width: 640px) {
  .stamp-rally-dialog-card {
    padding: 16px 12px;
    max-height: 96vh;
    border-radius: 16px;
    gap: 14px;
  }

  .washi-slot-circle {
    width: 78px;
    height: 78px;
  }

  .hanko-ink-seal {
    width: 70px;
    height: 70px;
  }

  .hanko-mascot-art svg {
    width: 32px;
    height: 32px;
  }

  .hanko-top-arc {
