/* ========================================================
   SCRATCHPAD ANIMATIONS & TELEMETRY
   ======================================================== */
@keyframes scratchpadSlideIn {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.scratchpad-animated-section {
  animation: scratchpadSlideIn 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  transition: all 0.2s ease;
}

.scratchpad-animated-textarea {
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.scratchpad-animated-textarea:focus {
  border-color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 18px var(--accent-glow, rgba(56, 189, 248, 0.25));
  background: var(--bg-primary);
}

.scratchpad-pulse-indicator {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--text-secondary);
}

.scratchpad-pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  transition: all 0.3s ease;
}

.scratchpad-pulse-dot.saved {
  background: #22c55e;
  box-shadow: 0 0 8px #22c55e;
}

.scratchpad-pulse-dot.typing {
  background: #f59e0b;
  box-shadow: 0 0 8px #f59e0b;
  animation: pulseDot 1s infinite alternate ease-in-out;
}

@keyframes pulseDot {
  from { transform: scale(0.85); opacity: 0.7; }
  to { transform: scale(1.3); opacity: 1; }
}

