   ======================================================== */
.passport-tactical-hero-container {
  width: 100%;
  max-width: 580px;
  margin: 0 auto 24px auto;
  display: flex;
  justify-content: center;
}

.tactical-modal-wrapper {
  max-width: 520px;
  width: 100%;
  margin: auto;
  position: relative;
  z-index: 10;
}

.tactical-operative-banner {
  position: relative;
  width: 100%;
  background: linear-gradient(160deg, #090c14 0%, #0d121c 60%, #080a10 100%);
  border: 1.5px solid rgba(var(--accent-rgb, 56, 189, 248), 0.32);
  border-radius: 18px;
  padding: clamp(14px, 3vw, 22px);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.85), 0 0 30px rgba(var(--accent-rgb, 56, 189, 248), 0.18);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-sizing: border-box;
  animation: tacticalBannerIn 0.28s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes tacticalBannerIn {
  from { opacity: 0; transform: scale(0.95) translateY(12px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

.tactical-shimmer-sweep {
  position: absolute;
  top: -100%;
  left: -100%;
  width: 300%;
  height: 300%;
  background: linear-gradient(
    135deg,
    transparent 45%,
    rgba(255, 255, 255, 0.03) 50%,
    rgba(56, 189, 248, 0.06) 52%,
    transparent 55%
  );
  pointer-events: none;
  animation: tacticalSheen 7s infinite ease-in-out;
}

@keyframes tacticalSheen {
  0% { transform: translate(-35%, -35%); }
  50% { transform: translate(15%, 15%); }
  100% { transform: translate(-35%, -35%); }
}

.tactical-top-hud {
