/* ========================================================
   UNLOCKABLE SPECIAL AVATAR FRAMES (HIGH-TIER VECTOR SVGS)
   ======================================================== */
.avatar-cosmetic-frame-wrap {
  position: absolute;
  inset: -15%;
  width: 130%;
  height: 130%;
  pointer-events: none;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cosmetic-svg-frame {
  width: 100%;
  height: 100%;
  overflow: visible;
  display: block;
}

/* ========================================================
   COSMETIC AVATAR FRAMES (FULL-SUITE SMOOTH ANIMATIONS)
   ======================================================== */

.cosmetic-svg-frame {
  width: 100%;
  height: 100%;
  overflow: visible;
  display: block;
}

/* Base transform-box setup for all SVG rotators & scalers */
.cosmetic-svg-frame * {
  transform-box: view-box;
}

/* 1. Titanium Operative (Level 1 • Common) */
.frame-svg-default {
  animation: titaniumFrameGlow 4s ease-in-out infinite alternate;
}

.titanium-armor-bezel {
  animation: titaniumArmorPulse 3.5s ease-in-out infinite alternate;
  transform-origin: 50px 50px;
}

.titanium-reticle-ring {
  animation: gyroSpin 18s linear infinite;
  transform-origin: 50px 50px;
}

.titanium-crosshairs {
  animation: titaniumCrosshairPulse 3s ease-in-out infinite alternate;
}

.titanium-bolt {
  animation: titaniumBoltGleam 2s ease-in-out infinite alternate;
}
.titanium-bolt.bolt-1 { animation-delay: 0s; }
.titanium-bolt.bolt-2 { animation-delay: 0.5s; }
.titanium-bolt.bolt-3 { animation-delay: 1s; }
.titanium-bolt.bolt-4 { animation-delay: 1.5s; }

@keyframes titaniumFrameGlow {
  0% { filter: drop-shadow(0 0 2px rgba(148, 163, 184, 0.3)); }
  100% { filter: drop-shadow(0 0 8px rgba(203, 213, 225, 0.65)); }
}

@keyframes titaniumArmorPulse {
  0% { stroke: #94a3b8; stroke-width: 2.8; }
  100% { stroke: #e2e8f0; stroke-width: 3.2; }
}

@keyframes titaniumCrosshairPulse {
  0% { opacity: 0.5; }
  100% { opacity: 1; filter: drop-shadow(0 0 4px #38bdf8); }
}

@keyframes titaniumBoltGleam {
  0% { fill: #94a3b8; stroke: #475569; }
  100% { fill: #38bdf8; stroke: #0ea5e9; filter: drop-shadow(0 0 4px #38bdf8); }
}

/* 2. Electric Gyro (Level 3 • Rare) */
.gyro-spin-ring {
  animation: gyroSpin 8s linear infinite;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

.gyro-counter-ring {
  animation: gyroCounterSpin 12s linear infinite;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

.frame-svg-neon_cyber {
  filter: drop-shadow(0 0 8px rgba(56, 189, 248, 0.7));
  animation: gyroNeonAura 3s ease-in-out infinite alternate;
  will-change: opacity, transform;
  transform: translateZ(0);
}

@keyframes gyroSpin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes gyroCounterSpin {
  0% { transform: rotate(360deg); }
  100% { transform: rotate(0deg); }
}

@keyframes gyroNeonAura {
  0% { opacity: 0.75; transform: scale(0.98); }
  100% { opacity: 1; transform: scale(1); }
}

/* 3. Solar Corona (Level 5 • Epic) */
.frame-svg-solar_flare {
  filter: drop-shadow(0 0 10px rgba(249, 115, 22, 0.7));
  animation: solarFlareBreath 3s ease-in-out infinite alternate;
  will-change: opacity, transform;
  transform: translateZ(0);
}

.solar-flame-burst {
  filter: drop-shadow(0 0 8px #f97316);
  animation: solarBurstPulse 2.4s ease-in-out infinite alternate;
  transform-origin: 50px 50px;
  will-change: transform, opacity;
  transform: translateZ(0);
}

.solar-spin-inner {
  animation: gyroSpin 10s linear infinite;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

.solar-plasma-corona {
  animation: solarCoronaHeat 2.8s ease-in-out infinite alternate;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

@keyframes solarBurstPulse {
  0% { transform: scale(0.95); opacity: 0.82; }
  100% { transform: scale(1.05); opacity: 1; }
}

@keyframes solarCoronaHeat {
  0% { stroke-width: 2.8; stroke: #f97316; }
  100% { stroke-width: 3.8; stroke: #fbbf24; }
}

@keyframes solarFlareBreath {
  0% { opacity: 0.75; transform: scale(0.98); }
  100% { opacity: 1; transform: scale(1); }
}

/* 4. Void Sorcery (Level 8 • Epic) */
.frame-svg-amethyst_void {
  filter: drop-shadow(0 0 10px rgba(168, 85, 247, 0.65));
  animation: voidAuraBreath 3.2s ease-in-out infinite alternate;
  will-change: opacity, transform;
  transform: translateZ(0);
}

.void-runic-seal {
  animation: voidPulseSpin 8s ease-in-out infinite alternate;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

.void-nodes {
  filter: drop-shadow(0 0 5px #c084fc);
  animation: voidNodesPulse 2.2s ease-in-out infinite alternate;
  transform-origin: 50px 50px;
  will-change: transform, opacity;
  transform: translateZ(0);
}

.void-pulse-inner {
  animation: gyroCounterSpin 12s linear infinite;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

@keyframes voidPulseSpin {
  0% { transform: scale(0.96) rotate(0deg); }
  100% { transform: scale(1.04) rotate(45deg); }
}

@keyframes voidNodesPulse {
  0% { opacity: 0.5; transform: scale(0.9); }
  100% { opacity: 1; transform: scale(1.15); }
}

@keyframes voidAuraBreath {
  0% { opacity: 0.75; transform: scale(0.98); }
  100% { opacity: 1; transform: scale(1); }
}

/* 5. Matrix Infiltrator (Level 12 • Legendary) */
.frame-svg-emerald_matrix {
  filter: drop-shadow(0 0 10px rgba(16, 185, 129, 0.75));
  animation: matrixScanGlow 3s ease-in-out infinite alternate;
  will-change: opacity, transform;
  transform: translateZ(0);
}

.matrix-rain-stream {
  animation: matrixRainFlow 2s linear infinite;
}
.matrix-rain-stream.col-1 { animation-duration: 2s; animation-delay: 0s; }
.matrix-rain-stream.col-2 { animation-duration: 1.6s; animation-delay: 0.4s; }
.matrix-rain-stream.col-3 { animation-duration: 2.2s; animation-delay: 0.2s; }
.matrix-rain-stream.col-4 { animation-duration: 1.8s; animation-delay: 0.6s; }

@keyframes matrixRainFlow {
  0% { stroke-dashoffset: 0; opacity: 0.3; }
  50% { opacity: 1; }
  100% { stroke-dashoffset: -50; opacity: 0.3; }
}

.matrix-beam-line {
  animation: matrixLaserSweep 2.5s ease-in-out infinite;
  transform-origin: 50px 50px;
  will-change: transform, opacity;
  transform: translateZ(0);
}

@keyframes matrixLaserSweep {
  0% { transform: translateY(-38px); opacity: 0.1; }
  25% { opacity: 0.95; }
  50% { transform: translateY(0px); opacity: 1; }
  75% { opacity: 0.95; }
  100% { transform: translateY(38px); opacity: 0.1; }
}

.matrix-inner-reticle {
  transform-origin: 50px 50px;
  animation: gyroSpin 10s linear infinite;
  will-change: transform;
  transform: translateZ(0);
}

@keyframes matrixScanGlow {
  0% { opacity: 0.8; transform: scale(0.98); }
  100% { opacity: 1; transform: scale(1.01); }
}

/* 6. Imperial Laurel (Level 15 • Legendary) */
.frame-svg-imperial_gold {
  filter: drop-shadow(0 0 8px rgba(234, 179, 8, 0.7));
  animation: imperialGleam 2.8s ease-in-out infinite alternate;
  will-change: opacity, transform;
  transform: translateZ(0);
}

.imperial-apex-star {
  filter: drop-shadow(0 0 8px #eab308);
  animation: imperialStarShine 2.4s ease-in-out infinite alternate;
  transform-origin: 50px 13px;
  will-change: transform, opacity;
  transform: translateZ(0);
}

.imperial-spin-halo {
  animation: gyroSpin 16s linear infinite;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

.imperial-wreath {
  filter: drop-shadow(0 0 5px rgba(234, 179, 8, 0.6));
  animation: imperialWreathShimmer 3s ease-in-out infinite alternate;
  will-change: opacity;
}

@keyframes imperialStarShine {
  0% { transform: scale(0.9); opacity: 0.8; }
  100% { transform: scale(1.15); opacity: 1; }
}

@keyframes imperialWreathShimmer {
  0% { opacity: 0.75; }
  100% { opacity: 1; }
}

@keyframes imperialGleam {
  0% { opacity: 0.8; transform: scale(0.99); }
  100% { opacity: 1; transform: scale(1.01); }
}

/* 7. Omni Dragon (Level 20 • Mythic) */
.dragon-spin-ring {
  animation: gyroSpin 5s linear infinite;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

.dragon-horns-wrap {
  filter: drop-shadow(0 0 8px #ec4899);
  animation: dragonHornsBreathe 2.6s ease-in-out infinite alternate;
  transform-origin: 50px 14px;
  will-change: transform, opacity;
  transform: translateZ(0);
}

.dragon-plasma-reticle {
  animation: gyroCounterSpin 7s linear infinite;
  transform-origin: 50px 50px;
  will-change: transform;
  transform: translateZ(0);
}

.frame-svg-mythic_dragon {
  filter: drop-shadow(0 0 10px #ec4899) drop-shadow(0 0 3px #38bdf8);
  animation: dragonAuraPulse 3s ease-in-out infinite alternate;
  will-change: opacity, transform;
  transform: translateZ(0);
}

@keyframes dragonHornsBreathe {
  0% { transform: scale(0.97); opacity: 0.85; }
  100% { transform: scale(1.04); opacity: 1; }
}

@keyframes dragonAuraPulse {
  0% { opacity: 0.82; transform: scale(0.98); }
  50% { opacity: 1; transform: scale(1.02); }
  100% { opacity: 0.9; transform: scale(1); }
}

/* ========================================================
   ANIMATED PROFILE BANNERS (HIGH-TIER PROGRESSION LOADOUT)
   ======================================================== */
.banner-anim-grid {
  position: relative;
  overflow: hidden;
  background-image: 
    radial-gradient(ellipse at 50% 100%, rgba(236, 72, 153, 0.45) 0%, transparent 60%),
    linear-gradient(rgba(56, 189, 248, 0.22) 1px, transparent 1px),
    linear-gradient(90deg, rgba(56, 189, 248, 0.22) 1px, transparent 1px) !important;
  background-size: 100% 100%, 28px 28px, 28px 28px !important;
  animation: gridScroll 10s linear infinite;
}

.banner-anim-grid::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 140px;
  height: 2px;
  background: #38bdf8;
  box-shadow: 0 0 16px 4px #ec4899, 0 0 32px 8px #38bdf8;
  border-radius: 50%;
}

@keyframes gridScroll {
  0% { background-position: center, 0 0, 0 0; }
  100% { background-position: center, 28px 28px, 28px 28px; }
}

.banner-anim-rain {
  position: relative;
  overflow: hidden;
  background-image: 
    linear-gradient(180deg, rgba(56, 189, 248, 0.4) 2px, transparent 2px),
    linear-gradient(180deg, rgba(168, 85, 247, 0.25) 1px, transparent 1px) !important;
  background-size: 100% 32px, 100% 18px !important;
  animation: rainDrop 0.65s linear infinite;
}

.banner-anim-rain::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 75% 30%, rgba(56, 189, 248, 0.18) 0%, transparent 50%);
  pointer-events: none;
}

@keyframes rainDrop {
  0% { background-position: 0 -32px, 0 -18px; }
  100% { background-position: 0 32px, 0 18px; }
}

.banner-anim-nebula {
  position: relative;
  overflow: hidden;
  background-image: 
    radial-gradient(circle at 20% 30%, rgba(192, 132, 252, 0.35) 0%, transparent 45%),
    radial-gradient(circle at 80% 70%, rgba(56, 189, 248, 0.25) 0%, transparent 45%),
    radial-gradient(circle at 50% 50%, rgba(236, 72, 153, 0.2) 0%, transparent 55%) !important;
  animation: nebulaDrift 10s ease-in-out infinite alternate;
}

.banner-anim-nebula::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(1px 1px at 15px 25px, #ffffff 100%, transparent),
                    radial-gradient(1px 1px at 75px 65px, #ffffff 100%, transparent),
                    radial-gradient(1.5px 1.5px at 140px 30px, #c084fc 100%, transparent),
                    radial-gradient(1px 1px at 210px 50px, #ffffff 100%, transparent);
  background-size: 260px 100px;
  animation: starTwinkle 3s ease-in-out infinite alternate;
  pointer-events: none;
}

@keyframes nebulaDrift {
  0% { filter: hue-rotate(0deg) saturate(1.1); transform: scale(1); }
  50% { filter: hue-rotate(30deg) saturate(1.4); transform: scale(1.02); }
  100% { filter: hue-rotate(-20deg) saturate(1.3); transform: scale(1); }
}

@keyframes starTwinkle {
  0% { opacity: 0.4; }
  100% { opacity: 1; }
}

.banner-anim-solar {
  position: relative;
  overflow: hidden;
  background-image: 
    radial-gradient(circle at 50% 120%, rgba(251, 146, 60, 0.6) 0%, rgba(234, 88, 12, 0.3) 40%, transparent 70%),
    radial-gradient(circle at 20% 0%, rgba(245, 158, 11, 0.25) 0%, transparent 40%) !important;
  animation: solarFlareShift 5s ease-in-out infinite alternate;
}

.banner-anim-solar::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-radial-gradient(circle at 50% 120%, transparent 0, transparent 8px, rgba(251, 146, 60, 0.08) 9px, transparent 10px);
  animation: coronalRings 4s linear infinite;
  pointer-events: none;
}

@keyframes solarFlareShift {
  0% { filter: brightness(1) contrast(1); }
  100% { filter: brightness(1.35) contrast(1.2); }
}

@keyframes coronalRings {
  0% { transform: scale(0.9); opacity: 0.5; }
  100% { transform: scale(1.15); opacity: 0.85; }
}

.banner-anim-cat {
  position: relative;
  overflow: hidden;
  background: radial-gradient(circle at 60% 40%, rgba(20, 184, 166, 0.35) 0%, rgba(6, 78, 59, 0.25) 45%, #011110 90%) !important;
  animation: catRadarPulse 3.5s ease-in-out infinite alternate;
}

.banner-anim-cat::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: 
    linear-gradient(rgba(45, 212, 191, 0.18) 1px, transparent 1px),
    linear-gradient(90deg, rgba(45, 212, 191, 0.18) 1px, transparent 1px);
  background-size: 28px 28px;
  opacity: 0.65;
  pointer-events: none;
}

.banner-anim-cat::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 60%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(45, 212, 191, 0.4), rgba(94, 234, 212, 0.7), transparent);
  animation: radarSweep 2.8s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  pointer-events: none;
}

@keyframes catRadarPulse {
  0% { filter: drop-shadow(0 0 4px rgba(45, 212, 191, 0.4)) brightness(1); }
  100% { filter: drop-shadow(0 0 16px rgba(45, 212, 191, 0.8)) brightness(1.25); }
}

@keyframes radarSweep {
  0% { left: -60%; }
  100% { left: 160%; }
}

.banner-anim-gold {
  position: relative;
  overflow: hidden;
  background-image: 
    radial-gradient(circle at 50% -20%, rgba(251, 191, 36, 0.55) 0%, rgba(217, 119, 6, 0.25) 45%, transparent 70%),
    linear-gradient(135deg, rgba(251, 191, 36, 0.15) 0%, transparent 100%) !important;
  animation: goldShimmer 6s ease-in-out infinite alternate;
}

.banner-anim-gold::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(1.5px 1.5px at 20px 20px, #fbbf24 100%, transparent),
                    radial-gradient(2px 2px at 80px 40px, #fef08a 100%, transparent),
                    radial-gradient(1.5px 1.5px at 150px 15px, #f59e0b 100%, transparent),
                    radial-gradient(1.5px 1.5px at 220px 45px, #fbbf24 100%, transparent);
  background-size: 240px 80px;
  animation: goldParticles 4s linear infinite;
  pointer-events: none;
}

@keyframes goldShimmer {
  0% { filter: drop-shadow(0 0 6px rgba(251, 191, 36, 0.25)) brightness(1); }
  100% { filter: drop-shadow(0 0 16px rgba(251, 191, 36, 0.55)) brightness(1.3); }
}

@keyframes goldParticles {
  0% { background-position: 0 0; }
  100% { background-position: 0 -80px; }
}

.banner-anim-warp {
  position: relative;
  overflow: hidden;
  background: radial-gradient(circle at 50% 50%, rgba(244, 63, 94, 0.6) 0%, rgba(139, 92, 246, 0.4) 35%, #05000a 85%) !important;
  animation: warpPulse 2.6s ease-in-out infinite alternate;
}

.banner-anim-warp::before {
  content: '';
  position: absolute;
  inset: -50px;
  background: conic-gradient(
    from 0deg at 50% 50%, 
    transparent 0deg, 
    rgba(244, 63, 94, 0.4) 30deg, 
    transparent 60deg, 
    rgba(56, 189, 248, 0.4) 120deg, 
    transparent 150deg, 
    rgba(168, 85, 247, 0.4) 220deg, 
    transparent 260deg,
    rgba(244, 63, 94, 0.4) 310deg,
    transparent 360deg
  );
  animation: warpSpin 6s linear infinite;
  pointer-events: none;
}

.banner-anim-warp::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, transparent 40%, rgba(2, 6, 23, 0.7) 90%);
  pointer-events: none;
}

@keyframes warpPulse {
  0% { filter: hue-rotate(0deg) contrast(1.15) brightness(1); transform: scale(1); }
  100% { filter: hue-rotate(35deg) contrast(1.35) brightness(1.25); transform: scale(1.02); }
}

@keyframes warpSpin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* ========================================================
   MYTHIC BANNER FULL-BLEED CANVAS VISUALIZERS (60FPS)
   ======================================================== */
.mythic-overlay-container {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
  overflow: hidden;
}

.mythic-overlay-container canvas {
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

/* ========================================================
   LOWER WORKSPACE GRID (BELOW PANORAMIC CARD)
   ======================================================== */
.tactical-lower-workspace-grid {
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: 20px;
  width: 100%;
  align-items: flex-start;
}

.tactical-lower-main-col,
.tactical-lower-side-col {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

@media (max-width: 960px) {
  .panoramic-trackers-grid {
    grid-template-columns: 1fr;
  }

  .medals-pins-row {
    grid-template-columns: repeat(2, 1fr);
  }

  .panoramic-hero-info-row {
    flex-direction: column;
    align-items: flex-start;
  }

  .panoramic-action-slot {
