/* ========================================================
   LEVEL UP ANIMATED POP-UP MODAL (STANDARD & DECADE MILESTONE)
   ======================================================== */
.level-up-modal-overlay {
  z-index: 999999 !important;
  background: rgba(3, 7, 18, 0.85);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.level-up-modal-box {
  width: 100%;
  max-width: 480px;
  max-height: min(92vh, 640px);
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  border-radius: 20px;
  padding: 24px 26px 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-sizing: border-box;
  position: relative;
  margin: auto;
  opacity: 0;
  transform: scale(0.92) translateY(12px);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  scrollbar-width: thin;
  scrollbar-color: rgba(56, 189, 248, 0.3) rgba(15, 23, 42, 0.6);
}

.level-up-modal-box.modal-animate-in {
  opacity: 1;
  transform: scale(1) translateY(0);
}

/* Standard Level-Up Card */
.standard-level-box {
  background: linear-gradient(180deg, #0f172a 0%, #0b1120 100%);
  border: 1px solid rgba(56, 189, 248, 0.35);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.8), 0 0 30px rgba(56, 189, 248, 0.18);
}

/* Grand Decade Milestone Card (Level 10 Legendary) */
.milestone-decade-box {
  background: linear-gradient(180deg, #1e1302 0%, #0c0800 50%, #080500 100%);
  border: 2px solid rgba(251, 191, 36, 0.7);
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.9), 0 0 45px rgba(251, 191, 36, 0.35), inset 0 0 30px rgba(251, 191, 36, 0.12);
  animation: milestoneBorderShimmer 4s ease-in-out infinite alternate;
}

/* Grand Mythic Milestone Card (Levels 20, 30... Radiant Ruby Rose) */
.milestone-mythic-box {
  background: linear-gradient(180deg, #2b0414 0%, #15020a 50%, #080005 100%);
  border: 2px solid rgba(244, 63, 94, 0.85);
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.9), 0 0 50px rgba(244, 63, 94, 0.45), inset 0 0 30px rgba(244, 63, 94, 0.15);
  animation: mythicBorderShimmer 3.5s ease-in-out infinite alternate;
}

@keyframes mythicBorderShimmer {
  0% { border-color: rgba(244, 63, 94, 0.7); box-shadow: 0 0 35px rgba(244, 63, 94, 0.35); }
  50% { border-color: rgba(236, 72, 153, 0.95); box-shadow: 0 0 55px rgba(236, 72, 153, 0.55); }
  100% { border-color: rgba(168, 85, 247, 0.85); box-shadow: 0 0 40px rgba(168, 85, 247, 0.4); }
}

@keyframes milestoneBorderShimmer {
  0% { border-color: rgba(251, 191, 36, 0.6); box-shadow: 0 0 30px rgba(251, 191, 36, 0.25); }
  50% { border-color: rgba(245, 158, 11, 0.9); box-shadow: 0 0 50px rgba(245, 158, 11, 0.45); }
  100% { border-color: rgba(251, 191, 36, 0.75); box-shadow: 0 0 35px rgba(251, 191, 36, 0.3); }
}

/* Rotating Sunburst Rays for Decade Milestones */
.milestone-rays-fx {
  position: absolute;
  top: -150px;
  left: 50%;
  transform: translateX(-50%);
  width: 500px;
  height: 500px;
  background: conic-gradient(from 0deg at 50% 50%, transparent 0deg, rgba(251, 191, 36, 0.15) 15deg, transparent 30deg, rgba(251, 191, 36, 0.12) 45deg, transparent 60deg, rgba(251, 191, 36, 0.15) 75deg, transparent 90deg, rgba(251, 191, 36, 0.12) 105deg, transparent 120deg, rgba(251, 191, 36, 0.15) 135deg, transparent 150deg, rgba(251, 191, 36, 0.12) 165deg, transparent 180deg, rgba(251, 191, 36, 0.15) 195deg, transparent 210deg, rgba(251, 191, 36, 0.12) 225deg, transparent 240deg, rgba(251, 191, 36, 0.15) 255deg, transparent 270deg, rgba(251, 191, 36, 0.12) 285deg, transparent 300deg, rgba(251, 191, 36, 0.15) 315deg, transparent 330deg, rgba(251, 191, 36, 0.12) 345deg, transparent 360deg);
  animation: raysRotate 24s linear infinite;
  pointer-events: none;
  border-radius: 50%;
  opacity: 0.8;
}

@keyframes raysRotate {
  0% { transform: translateX(-50%) rotate(0deg); }
  100% { transform: translateX(-50%) rotate(360deg); }
}

/* Particle Confetti */
.milestone-confetti-wrap {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.milestone-particle {
  position: absolute;
  width: 5px;
  height: 5px;
  background: #fbbf24;
  border-radius: 50%;
  box-shadow: 0 0 6px #fbbf24;
  opacity: 0;
  animation: confettiFloat 3.5s ease-in-out infinite;
}

.particle-1 { top: 15%; left: 10%; animation-delay: 0.1s; background: #fbbf24; }
.particle-2 { top: 25%; left: 88%; animation-delay: 0.4s; background: #38bdf8; }
.particle-3 { top: 40%; left: 8%; animation-delay: 0.7s; background: #ec4899; }
.particle-4 { top: 60%; left: 92%; animation-delay: 1.1s; background: #fbbf24; }
.particle-5 { top: 75%; left: 14%; animation-delay: 1.5s; background: #c084fc; }
.particle-6 { top: 18%; left: 82%; animation-delay: 0.3s; background: #34d399; }
.particle-7 { top: 50%; left: 94%; animation-delay: 0.9s; background: #f59e0b; }
.particle-8 { top: 80%; left: 86%; animation-delay: 1.3s; background: #fbbf24; }
.particle-9 { top: 30%; left: 12%; animation-delay: 0.5s; background: #38bdf8; }
.particle-10 { top: 70%; left: 6%; animation-delay: 1.2s; background: #ec4899; }
.particle-11 { top: 10%; left: 75%; animation-delay: 0.2s; background: #fbbf24; }
.particle-12 { top: 85%; left: 25%; animation-delay: 1.6s; background: #38bdf8; }
.particle-13 { top: 90%; left: 78%; animation-delay: 0.8s; background: #f59e0b; }
.particle-14 { top: 22%; left: 20%; animation-delay: 1.0s; background: #34d399; }

.milestone-particle.mythic-spark {
  background: #f43f5e;
  box-shadow: 0 0 8px #fb7185;
}
.milestone-particle.mythic-spark:nth-child(even) {
  background: #ec4899;
  box-shadow: 0 0 8px #f472b6;
}
.milestone-particle.mythic-spark:nth-child(3n) {
  background: #c084fc;
  box-shadow: 0 0 8px #d8b4fe;
}
.milestone-particle.mythic-spark:nth-child(5n) {
  background: #38bdf8;
  box-shadow: 0 0 8px #7dd3fc;
}

@keyframes confettiFloat {
  0% { transform: translateY(0) scale(0.5); opacity: 0; }
  50% { opacity: 1; transform: translateY(-16px) scale(1.1); }
  100% { transform: translateY(-32px) scale(0.6); opacity: 0; }
}

