}

/* Top System Status Bar: Spacious, single-line high-tech HUD */
.blueprint-top-bar {
  padding: 12px 54px 12px 24px;
  background: var(--bg-tertiary, rgba(10, 20, 38, 0.94));
  border-bottom: 1px solid var(--border-color, rgba(56, 189, 248, 0.2));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 46px;
  box-sizing: border-box;
}

.blueprint-id-cluster {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.blueprint-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  color: var(--accent-color, #38bdf8);
  letter-spacing: 0.08em;
}

.blueprint-version-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 4px;
  background: var(--accent-glow, rgba(56, 189, 248, 0.12));
  border: 1px solid var(--border-color, rgba(56, 189, 248, 0.3));
  color: var(--text-primary, #e0f2fe);
  font-size: 10.5px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
}

.blueprint-date {
  font-size: 10.5px;
  color: var(--text-secondary, #94a3b8);
  font-family: 'JetBrains Mono', monospace;
}

.blueprint-status-indicator {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 700;
  color: #34d399;
  flex-shrink: 0;
}

.blueprint-pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #34d399;
  box-shadow: 0 0 8px #34d399;
  animation: pulse 1.6s infinite;
}

/* Hero Section: Generous Spacing & Uniform Controls */
.blueprint-hero-section {
  padding: 20px 24px 18px;
  border-bottom: 1px solid var(--border-color, rgba(56, 189, 248, 0.16));
  background: var(--bg-secondary, rgba(8, 16, 32, 0.6));
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.blueprint-hero-text {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.blueprint-hero-title {
  font-family: 'JetBrains Mono', monospace;
  font-size: 1.12rem;
  font-weight: 800;
  color: var(--text-primary, #f0f9ff);
  letter-spacing: -0.01em;
  margin: 0;
  line-height: 1.35;
}

.blueprint-hero-summary {
  font-size: 12.5px;
  color: var(--text-secondary, #94a3b8);
  line-height: 1.55;
  margin: 0;
}

/* Structured Controls Panel with Uniform 5-Column Alignment */
.blueprint-controls-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 4px;
  width: 100%;
}

.blueprint-control-row {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  box-sizing: border-box;
}

.blueprint-control-label {
  width: 74px;
  flex-shrink: 0;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  color: var(--text-tertiary, #64748b);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* Identical 5-Column Grid Alignment for BOTH Release & Category */
.blueprint-version-grid,
.blueprint-filter-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  flex: 1;
  width: 100%;
  box-sizing: border-box;
}

.blueprint-version-tab,
.blueprint-filter-chip {
  height: 28px;
  padding: 0 4px;
  border-radius: 6px;
  background: var(--bg-tertiary, rgba(15, 23, 42, 0.8));
  border: 1px solid var(--border-color, rgba(56, 189, 248, 0.18));
  color: var(--text-secondary, #94a3b8);
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  white-space: nowrap;
  width: 100%;
  box-sizing: border-box;
  text-align: center;
  user-select: none;
}

.blueprint-version-tab:hover,
.blueprint-filter-chip:hover {
  background: var(--accent-glow, rgba(56, 189, 248, 0.1));
  border-color: var(--accent-color, #38bdf8);
  color: var(--text-primary, #f8fafc);
  transform: translateY(-1px);
}

/* Active Selection Fluid Scale Animation */
.blueprint-version-tab.active,
.blueprint-filter-chip.active {
  background: var(--accent-glow, rgba(56, 189, 248, 0.18));
  border-color: var(--accent-color, #38bdf8);
  color: var(--accent-color, #38bdf8);
  font-weight: 800;
  box-shadow: 0 0 12px var(--accent-glow, rgba(56, 189, 248, 0.28));
  animation: tabPillSelect 0.24s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes tabPillSelect {
  0% { transform: scale(0.92); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

.tab-latest-badge {
  font-size: 8px;
  font-weight: 800;
  padding: 1px 4px;
  border-radius: 3px;
  background: var(--accent-glow, rgba(56, 189, 248, 0.3));
  color: var(--accent-color, #38bdf8);
}

/* Compact, Uniform Oscilloscope & Telemetry Strip */
.blueprint-waveform-module {
  background: var(--bg-primary, rgba(4, 10, 22, 0.92));
  border-bottom: 1px solid var(--border-color, rgba(56, 189, 248, 0.2));
  padding: 12px 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: all 0.3s ease;
}

.waveform-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.waveform-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10.5px;
  font-weight: 800;
  color: var(--text-primary, #e2e8f0);
  letter-spacing: 0.04em;
}

.waveform-time {
  color: var(--text-tertiary, #64748b);
  font-size: 9.5px;
  font-weight: 500;
}

.blueprint-benchmark-btn {
  height: 28px;
  padding: 0 12px;
  border-radius: 6px;
  background: var(--accent-glow, rgba(56, 189, 248, 0.12));
  border: 1px solid var(--accent-color, rgba(56, 189, 248, 0.35));
  color: var(--accent-color, #38bdf8);
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.blueprint-benchmark-btn:hover:not(:disabled) {
  background: var(--accent-glow, rgba(56, 189, 248, 0.25));
  border-color: var(--accent-color, #38bdf8);
  color: #ffffff;
  box-shadow: 0 0 12px var(--accent-glow, rgba(56, 189, 248, 0.35));
  transform: translateY(-1px);
}

.blueprint-benchmark-btn.running {
  opacity: 0.85;
  cursor: wait;
  box-shadow: 0 0 14px var(--accent-glow, rgba(56, 189, 248, 0.4));
}

.spin-anim-fast {
  animation: spinFast 0.5s linear infinite;
}

@keyframes spinFast {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Animated Vector Oscilloscope Canvas & Laser Scanner */
.waveform-canvas-wrap {
  height: 28px;
  width: 100%;
  border: 1px solid var(--border-color, rgba(56, 189, 248, 0.2));
  border-radius: 6px;
  background: rgba(2, 6, 14, 0.95);
  overflow: hidden;
  position: relative;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}

.waveform-canvas-wrap.testing-active {
  border-color: var(--accent-color, #38bdf8);
  box-shadow: 0 0 18px var(--accent-glow, rgba(56, 189, 248, 0.45)), inset 0 0 14px rgba(56, 189, 248, 0.15);
}

.waveform-canvas-wrap.testing-success {
  animation: benchmarkSuccessFlash 1s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes benchmarkSuccessFlash {
  0% {
    border-color: #34d399;
    box-shadow: 0 0 24px rgba(52, 211, 153, 0.6), inset 0 0 12px rgba(52, 211, 153, 0.2);
  }
  100% {
    border-color: var(--border-color, rgba(56, 189, 248, 0.2));
    box-shadow: none;
  }
}

/* Unique Laser Scanner Animation during Benchmark */
.waveform-laser-scanner {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(180deg, transparent, var(--accent-color, #38bdf8), #ffffff, var(--accent-color, #38bdf8), transparent);
  box-shadow: 0 0 12px var(--accent-color, #38bdf8), 0 0 20px #ffffff;
  z-index: 6;
  animation: laserScanSweep 0.55s ease-in-out infinite alternate;
  pointer-events: none;
}

@keyframes laserScanSweep {
  0% { left: 0%; opacity: 0.8; }
  100% { left: 99%; opacity: 1; }
}

/* Oscilloscope Left-to-Right Phosphor Sweep Beam */
.waveform-sweep-beam {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 90px;
  background: linear-gradient(90deg, 
    transparent 0%, 
    rgba(56, 189, 248, 0.04) 20%,
    var(--accent-glow, rgba(56, 189, 248, 0.25)) 80%, 
    var(--accent-color, #38bdf8) 98%,
    transparent 100%
  );
  box-shadow: 2px 0 10px var(--accent-color, #38bdf8);
  pointer-events: none;
  z-index: 4;
  opacity: 0.85;
  animation: oscilloscopeSweep 2.6s cubic-bezier(0.2, 0, 0.2, 1) infinite;
  mix-blend-mode: screen;
}

@keyframes oscilloscopeSweep {
  0% {
    left: -90px;
    opacity: 0;
  }
  6% {
    opacity: 0.9;
  }
  92% {
    opacity: 0.9;
  }
  100% {
    left: 100%;
    opacity: 0;
  }
}

.waveform-sweep-beam.beam-turbo {
  animation: oscilloscopeSweep 0.55s linear infinite;
  opacity: 1;
  box-shadow: 4px 0 20px var(--accent-color, #38bdf8);
}

.waveform-svg-track {
  width: 100%;
  height: 100%;
  display: block;
  animation: waveInitialReveal 0.85s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes waveInitialReveal {
  0% {
    clip-path: inset(0 100% 0 0);
    opacity: 0.3;
  }
  100% {
    clip-path: inset(0 0% 0 0);
    opacity: 1;
  }
}

.animated-wave {
  fill: none;
  stroke-linecap: round;
}

.wave-primary {
  stroke: var(--accent-color, #38bdf8);
  stroke-width: 1.6;
  stroke-dasharray: 8 4;
  filter: drop-shadow(0 0 5px var(--accent-glow, rgba(56, 189, 248, 0.65)));
  animation: waveTravelLeftToRight 3s linear infinite;
  transition: stroke 0.2s ease;
}

.wave-secondary {
  stroke: var(--accent-secondary, #818cf8);
  stroke-width: 1.2;
  stroke-dasharray: 6 4;
  opacity: 0.6;
  filter: drop-shadow(0 0 3px rgba(129, 140, 248, 0.4));
  animation: waveTravelLeftToRightSecondary 4.2s linear infinite;
  transition: stroke 0.2s ease;
}

/* Continuous Fluid Left-to-Right Traveling Waves */
@keyframes waveTravelLeftToRight {
  0% { stroke-dashoffset: 0; }
  100% { stroke-dashoffset: 120; }
}

@keyframes waveTravelLeftToRightSecondary {
  0% { stroke-dashoffset: 0; }
  100% { stroke-dashoffset: 120; }
}

/* Turbo Speed Waveform Animation during Benchmark */
.wave-turbo .wave-primary {
  stroke-width: 2.4;
  filter: drop-shadow(0 0 10px var(--accent-color, #38bdf8));
  animation: waveTravelLeftToRight 0.5s linear infinite !important;
}

.wave-turbo .wave-secondary {
  stroke-width: 1.8;
  opacity: 0.9;
  animation: waveTravelLeftToRightSecondary 0.65s linear infinite !important;
}

/* Uniform Telemetry Metric Chips & Jitter Animation */
.waveform-telemetry-readouts {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.telemetry-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  background: var(--bg-tertiary, rgba(56, 189, 248, 0.05));
  border: 1px solid var(--border-color, rgba(56, 189, 248, 0.16));
  border-radius: 5px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  transition: all 0.2s ease;
}

.telemetry-chip.testing {
  border-color: var(--accent-color, #38bdf8);
  animation: chipJitter 0.12s infinite alternate;
}

@keyframes chipJitter {
  0% { transform: translateY(-0.8px); }
  100% { transform: translateY(0.8px); }
}

.telemetry-chip.success {
  border-color: #34d399;
  box-shadow: 0 0 10px rgba(52, 211, 153, 0.3);
}

.telemetry-chip.success .telemetry-val {
  color: #34d399;
  text-shadow: 0 0 8px #34d399;
}

.telemetry-label {
  color: var(--text-tertiary, #64748b);
  font-weight: 600;
}

.telemetry-val {
  color: var(--accent-color, #38bdf8);
  font-weight: 800;
  transition: color 0.3s ease;
}

/* Changelog Body: Spacious, Uniform & Key-Driven Animated Feed */
.blueprint-dialog-body {
  padding: 20px 24px;
  overflow-y: auto;
  flex: 1;
  min-height: 240px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Fluid Entrance Animation when switching Version or Category */
.blueprint-feed-animate {
  animation: feedSlideIn 0.28s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes feedSlideIn {
  0% {
    opacity: 0;
    transform: translateY(10px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Staggered Card Micro-Entrance */
.blueprint-feed-animate .blueprint-card {
  animation: cardStagger 0.24s cubic-bezier(0.16, 1, 0.3, 1) backwards;
}
.blueprint-feed-animate .blueprint-card:nth-child(1) { animation-delay: 0.02s; }
.blueprint-feed-animate .blueprint-card:nth-child(2) { animation-delay: 0.05s; }
.blueprint-feed-animate .blueprint-card:nth-child(3) { animation-delay: 0.08s; }
.blueprint-feed-animate .blueprint-card:nth-child(4) { animation-delay: 0.11s; }

@keyframes cardStagger {
  0% {
    opacity: 0;
    transform: translateY(8px) scale(0.99);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.blueprint-section-block {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.blueprint-section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10.5px;
  font-weight: 800;
  color: var(--accent-color, #38bdf8);
  letter-spacing: 0.06em;
}

.section-count {
  color: var(--text-tertiary, #475569);
}

.blueprint-item-cards {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.blueprint-card {
  background: var(--bg-secondary, rgba(11, 20, 38, 0.75));
  border: 1px solid var(--border-color, rgba(56, 189, 248, 0.16));
  border-radius: 8px;
