}

.blueprint-card:hover {
  border-color: var(--accent-color, rgba(56, 189, 248, 0.4));
  background: var(--bg-tertiary, rgba(14, 25, 48, 0.85));
  transform: translateY(-1px);
}

.blueprint-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.blueprint-card-title-group {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* Standardized Chips across all card types */
.blueprint-chip {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9.5px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 4px;
  letter-spacing: 0.04em;
}

.blueprint-chip.feature {
  background: var(--accent-glow, rgba(56, 189, 248, 0.14));
