  border: 1px solid var(--accent-color, rgba(56, 189, 248, 0.3));
}

.blueprint-chip.balance {
  background: rgba(245, 158, 11, 0.14);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.blueprint-chip.security {
  background: rgba(16, 185, 129, 0.14);
  color: #34d399;
