}

.blueprint-chip.engine {
  background: rgba(168, 85, 247, 0.14);
  color: #c084fc;
  border: 1px solid rgba(168, 85, 247, 0.3);
}

.blueprint-card-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary, #f8fafc);
  line-height: 1.35;
}

.blueprint-action-btn {
  height: 26px;
  padding: 0 10px;
  border-radius: 5px;
  background: var(--accent-glow, rgba(56, 189, 248, 0.12));
  border: 1px solid var(--accent-color, rgba(56, 189, 248, 0.35));
  color: var(--accent-color, #38bdf8);
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
}

.blueprint-action-btn:hover {
  background: var(--accent-glow, rgba(56, 189, 248, 0.25));
  color: #ffffff;
  border-color: var(--accent-color, #38bdf8);
  transform: translateY(-1px);
}

.blueprint-card-text {
  font-size: 12px;
  color: var(--text-secondary, #94a3b8);
  line-height: 1.55;
  margin: 0;
}

.blueprint-callout {
  font-size: 11px;
  color: var(--text-secondary, #cbd5e1);
  padding: 6px 12px;
  background: var(--accent-glow, rgba(56, 189, 248, 0.04));
