/* Footer: Clean, spacious bar */
.blueprint-footer {
  padding: 14px 24px;
  background: var(--bg-tertiary, rgba(6, 12, 24, 0.96));
  border-top: 1px solid var(--border-color, rgba(56, 189, 248, 0.2));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.blueprint-audit-seal {
