/* ==========================================================================
   TACTICAL BLUEPRINT RESPONSIVE BREAKPOINTS (Mobile, Tablet, Desktop)
   ========================================================================== */

@media (max-width: 640px) {
  .patch-hub-overlay {
    padding: 10px 8px;
  }

  .tactical-blueprint-dialog {
    width: 96%;
    max-height: 94vh;
    border-radius: 8px;
  }

  .blueprint-close-btn {
    top: 8px;
    right: 10px;
    width: 26px;
    height: 26px;
  }

  .blueprint-top-bar {
    padding: 10px 44px 10px 14px;
    gap: 8px;
  }

  .blueprint-hero-section {
    padding: 14px 14px 12px;
    gap: 10px;
  }

  .blueprint-hero-title {
    font-size: 0.98rem;
  }

  .blueprint-hero-summary {
    font-size: 11.5px;
  }

  .blueprint-control-row {
    flex-direction: column;
    align-items: flex-start;
