    padding: 10px 14px;
    gap: 8px;
  }

  .waveform-canvas-wrap {
    height: 24px;
  }

  .blueprint-dialog-body {
    padding: 14px 14px;
    gap: 14px;
  }

  .blueprint-card {
    padding: 12px 14px;
    gap: 6px;
  }

  .blueprint-footer {
    padding: 12px 14px;
  }
}

@media (max-width: 440px) {
  .corner-crosshair {
    font-size: 11px;
  }
