  height: 50px;
  background: radial-gradient(circle, rgba(251, 191, 36, 0.45) 0%, rgba(245, 158, 11, 0) 70%);
  border-radius: 50%;
  pointer-events: none;
  filter: blur(4px);
}

.lamp-aura.aura-pulse {
  animation: auraBreathe 3s ease-in-out infinite;
}

@keyframes auraBreathe {
  0%, 100% { opacity: 0.6; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.2); }
}

.flicker-flame {
  transform-box: fill-box;
  transform-origin: 50% 85%;
  animation: flameSanctuaryBreathe 2.5s ease-in-out infinite alternate;
}

@keyframes flameSanctuaryBreathe {
  0% {
    transform: scale(0.96, 0.94) skewX(-0.8deg);
    opacity: 0.88;
    filter: drop-shadow(0 0 2px rgba(251, 191, 36, 0.5));
  }
  50% {
    transform: scale(1.03, 1.05) skewX(0.8deg);
    opacity: 1;
    filter: drop-shadow(0 0 5px rgba(251, 191, 36, 0.85));
  }
  100% {
    transform: scale(0.98, 1.01) skewX(-0.4deg);
    opacity: 0.92;
    filter: drop-shadow(0 0 3px rgba(251, 191, 36, 0.65));
  }
}

.lamp-glow-pulse {
