/* Individual Icon Button */
.fan-icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--bg-card, rgba(24, 24, 27, 0.92));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid var(--border-color, rgba(255, 255, 255, 0.12));
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
  outline: none;
  padding: 0;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1),
              border-color 0.2s ease,
              box-shadow 0.2s ease,
              background 0.2s ease;
}

.fan-icon-btn:hover {
  transform: scale(1.18);
  border-color: var(--accent-primary, #6366f1);
  box-shadow: 0 6px 18px rgba(99, 102, 241, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

.fan-icon-btn.active-ring {
  border-color: var(--accent-primary, #6366f1);
  background: var(--bg-card, rgba(39, 39, 42, 0.98));
  box-shadow: 0 0 0 2px var(--accent-primary, #6366f1), 0 4px 16px rgba(99, 102, 241, 0.4);
}

.fan-item-node.is-locked .fan-icon-btn {
  opacity: 0.55;
  cursor: pointer;
}

.fan-item-node.is-locked .fan-icon-btn:hover {
  opacity: 0.85;
}

/* Check / Lock Indicators */
.fan-check-indicator {
  position: absolute;
  top: -2px;
  right: -2px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #22c55e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.35);
}

.fan-lock-indicator {
  position: absolute;
  top: -2px;
  right: -2px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #475569;
  color: #cbd5e1;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.35);
}

/* Item Tooltip */
.fan-item-tooltip {
  position: absolute;
  bottom: calc(100% + 7px);
  left: 50%;
  transform: translateX(-50%);
  background: rgba(15, 23, 42, 0.96);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  padding: 3px 8px;
  font-size: 11px;
  white-space: nowrap;
  color: #f8fafc;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.45);
