  color: #22c55e;
  font-size: 9px;
  font-weight: 600;
}

/* Fullscreen mode adjustment */
.study-timer-minimal-container.zen-fullscreen-mode .corner-fan-menu-container {
  bottom: 24px;
  right: 24px;
}

/* Mobile responsive styling */
@media (max-width: 640px) {
  .corner-fan-menu-container {
    bottom: 12px;
    right: 14px;
    width: 38px;
    height: 38px;
  }
  .fan-menu-main-trigger {
    width: 38px;
    height: 38px;
  }
  .fan-item-node {
    width: 38px;
    height: 38px;
  }
  .fan-icon-btn {
    width: 34px;
    height: 34px;
  }
}

