}

/* Staggered Placeholder Rotation Layer */
.staggered-placeholder-layer {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  pointer-events: none;
  user-select: none;
  font-family: 'JetBrains Mono', monospace;
  font-size: 13px;
  color: var(--text-tertiary, #64748b);
  line-height: 1.6;
}

.staggered-char {
  display: inline-block;
  opacity: 0;
  animation: staggeredIn 0.34s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.staggered-placeholder-layer.fade-out .staggered-char {
  animation: staggeredOut 0.22s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes staggeredIn {
  0% {
    opacity: 0;
    transform: translateY(7px) scale(0.94);
    filter: blur(2px);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

@keyframes staggeredOut {
  0% {
    opacity: 1;
    transform: translateY(0);
  }
  100% {
    opacity: 0;
    transform: translateY(-7px) scale(0.96);
    filter: blur(2px);
  }
}

.animated-input-bar-textarea {
