}

.gooey-switch-interactive-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* Gooey Switch Track & Fluid Blobs */
.gooey-switch-track {
  position: relative;
  width: 74px;
  height: 36px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.12);
  cursor: pointer;
  padding: 3px;
  outline: none;
  overflow: hidden;
  transition: border-color 0.22s ease, box-shadow 0.22s ease;
}

.gooey-switch-track:hover {
  border-color: rgba(255, 255, 255, 0.24);
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.15);
}

.gooey-blobs-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: 999px;
}

.gooey-base-pill {
  position: absolute;
  inset: 2px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
}

.gooey-liquid-thumb {
  position: absolute;
  top: 4px;
  left: 5px;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-color, #38bdf8);
  box-shadow: 0 0 14px var(--accent-color, #38bdf8);
  transition: transform 0.42s cubic-bezier(0.34, 1.56, 0.64, 1), background-color 0.3s ease;
}

.gooey-switch-track.is-toggled .gooey-liquid-thumb {
  transform: translateX(36px);
}

.gooey-droplet {
  position: absolute;
  top: 8px;
  left: 12px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent-color, #38bdf8);
  opacity: 0.8;
  transition: transform 0.38s cubic-bezier(0.25, 1, 0.5, 1);
}

.gooey-switch-track.is-toggled .droplet-1 {
  transform: translateX(28px) scale(0.7);
}

.gooey-switch-track.is-toggled .droplet-2 {
  transform: translateX(18px) scale(0.5);
}

.gooey-icons-overlay {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 100%;
  padding: 0 6px;
  pointer-events: none;
}

.switch-icon-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
}

.switch-color-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.6);
  box-shadow: 0 0 4px rgba(0, 0, 0, 0.5);
  transition: transform 0.22s ease;
}

.switch-icon-wrapper.active .switch-color-dot {
  transform: scale(1.25);
  border-color: #ffffff;
}

.gooey-config-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--text-tertiary, #64748b);
  cursor: pointer;
  transition: all 0.2s ease;
}

.gooey-config-btn:hover,
.gooey-config-btn.is-active {
  background: rgba(255, 255, 255, 0.1);
  color: var(--accent-color, #38bdf8);
  border-color: rgba(56, 189, 248, 0.35);
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.2);
}

