/* ==========================================================================
   REACTICX COMPONENT 2: ANIMATED CHIP
   Dynamic selection chip with icon bounce and expanding background pill
   ========================================================================== */
.animated-chips-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  overflow-x: auto;
  scrollbar-width: none;
}

.animated-chips-wrapper::-webkit-scrollbar {
  display: none;
}

.animated-chip-item {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-secondary, #94a3b8);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  outline: none;
  white-space: nowrap;
  user-select: none;
  transition: color 0.22s ease, border-color 0.22s ease, transform 0.16s ease;
}

.animated-chip-backdrop {
  position: absolute;
  inset: 0;
  border-radius: 10px;
  background: transparent;
  opacity: 0;
  transform: scale(0.92);
  transition: all 0.26s cubic-bezier(0.16, 1, 0.3, 1);
  pointer-events: none;
  z-index: 0;
}

.animated-chip-item:hover {
  color: var(--text-primary, #f8fafc);
}

.animated-chip-item:hover .animated-chip-backdrop {
  opacity: 0.45;
  transform: scale(1);
  background: rgba(255, 255, 255, 0.05);
}

.animated-chip-item.is-active {
  color: #ffffff;
  font-weight: 600;
  border-color: rgba(56, 189, 248, 0.32);
}

.animated-chip-item.is-active .animated-chip-backdrop {
  opacity: 1;
  transform: scale(1);
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.16) 0%, rgba(2, 132, 199, 0.08) 100%);
  border: 1px solid rgba(56, 189, 248, 0.24);
  box-shadow: 0 2px 12px rgba(56, 189, 248, 0.12);
}

.animated-chip-icon-box {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--chip-accent, var(--accent-color, #38bdf8));
  transition: transform 0.24s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.animated-chip-item.is-active .animated-chip-icon-box {
  animation: chipIconBounce 0.42s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

@keyframes chipIconBounce {
  0% {
    transform: scale(0.85) rotate(-10deg);
  }
  50% {
    transform: scale(1.22) rotate(6deg);
  }
  100% {
    transform: scale(1) rotate(0deg);
  }
}

.animated-chip-label {
  position: relative;
  z-index: 1;
}

.animated-chip-badge {
  position: relative;
  z-index: 1;
  font-size: 10px;
  padding: 1px 5px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: var(--text-primary, #f8fafc);
}


