/* Selectable Route Highlight Ring (Beacon Effect on Spire Map - Encircles Node Icon Only) */
.selectable-route-ring {
  position: absolute;
  inset: -7px;
  border-radius: 50%;
  border: 2px dashed rgba(56, 189, 248, 0.85);
  pointer-events: none;
  animation: routeBeaconRotate 8s linear infinite;
}

.route-ring-ping {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid rgba(56, 189, 248, 0.8);
  animation: routeRingPing 1.8s cubic-bezier(0, 0, 0.2, 1) infinite;
}

@keyframes routeBeaconRotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes routeRingPing {
  0% { transform: scale(0.95); opacity: 1; }
  100% { transform: scale(1.35); opacity: 0; }
}

