.spire-map-sub-bar {
  position: sticky;
  top: 0;
  z-index: 50;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 8px 24px;
  min-height: 40px;
  background: rgba(8, 12, 22, 0.95);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0 !important;
  border-left: none !important;
  border-right: none !important;
  border-top: none !important;
  width: 100%;
  box-sizing: border-box;
}

.spire-sub-meta {
  display: flex;
  align-items: center;
}

.spire-sub-tagline {
  font-size: 11.5px;
  color: #94a3b8;
  font-style: italic;
  letter-spacing: 0.02em;
}

.spire-map-legend {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.spire-map-legend .legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #cbd5e1;
}

.spire-map-jump-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.spire-jump-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 6px;
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.28);
  color: #38bdf8;
  font-size: 10.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.spire-jump-btn:hover {
  background: rgba(56, 189, 248, 0.2);
  border-color: #38bdf8;
  color: #ffffff;
}

.spire-jump-btn.bottom-active {
  background: rgba(56, 189, 248, 0.16);
  border-color: #38bdf8;
  color: #ffffff;
}

/* Spire Map Tower */
.spire-map-tower {
  display: flex;
  flex-direction: column;
  gap: 40px;
  padding: 40px 24px 110px;
  background: radial-gradient(circle at 50% 10%, rgba(56, 189, 248, 0.07) 0%, rgba(10, 15, 29, 0.95) 75%);
  border: none !important;
  border-radius: 0 !important;
  position: relative;
  width: 100%;
  box-sizing: border-box;
}

.spire-floor-row {
  display: flex;
  align-items: center;
  position: relative;
  min-height: 120px;
  padding: 6px 12px;
  transition: background 0.3s ease;
}

.spire-floor-row.active-floor {
  background: linear-gradient(90deg, rgba(56, 189, 248, 0.1) 0%, rgba(56, 189, 248, 0.02) 60%, transparent 100%);
  border-left: 3px solid #38bdf8;
  border-radius: 0 !important;
}

.floor-marker {
  width: 64px;
  font-size: 12px;
  font-weight: 800;
  color: #64748b;
  text-align: center;
}

.floor-nodes-track {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-around;
  position: relative;
}

.spire-map-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  position: relative;
  padding: 8px 14px;
  border-radius: 12px;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.spire-map-node:hover {
  transform: translateY(-4px) scale(1.08);
}

.node-icon-wrapper {
  position: relative;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(15, 23, 42, 0.85);
  border: 1.5px solid rgba(255, 255, 255, 0.14);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
}

.spire-map-node.current .node-icon-wrapper {
  border-color: #38bdf8;
  box-shadow: 0 0 16px rgba(56, 189, 248, 0.6);
  background: rgba(2, 132, 199, 0.25);
}

.spire-map-node.selectable .node-icon-wrapper {
  border-color: #34d399;
  box-shadow: 0 0 12px rgba(52, 211, 153, 0.4);
}

.spire-map-node.boss .node-icon-wrapper {
  width: 52px;
  height: 52px;
  border-color: #f43f5e;
  box-shadow: 0 0 20px rgba(244, 63, 94, 0.5);
}

.spire-map-node .node-label {
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
  transition: color 0.2s ease, text-shadow 0.2s ease;
}

.spire-map-node.current .node-label {
  color: #38bdf8;
  font-weight: 800;
  text-shadow: 0 0 10px rgba(56, 189, 248, 0.6);
}

.current-player-aura {
  position: absolute;
  top: -16px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.current-player-aura .aura-label {
  font-size: 9px;
  font-weight: 800;
  background: #38bdf8;
  color: #04101f;
  padding: 1px 6px;
  border-radius: 999px;
}

.selectable-pulsar {
  position: absolute;
  bottom: -16px;
  font-size: 9px;
  font-weight: 700;
  color: #34d399;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  background: rgba(52, 211, 153, 0.15);
  border: 1px solid rgba(52, 211, 153, 0.4);
  padding: 1px 6px;
  border-radius: 999px;
  white-space: nowrap;
  animation: selectablePulse 1.4s infinite;
}

/* ================= CURVY DOTTED LINE PATHS & ANIMATIONS ================= */
.spire-map-connections-svg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.spire-path-line {
  transition: stroke 0.3s ease, stroke-width 0.3s ease, filter 0.3s ease;
}

.spire-path-line.path-locked {
  stroke: rgba(100, 116, 139, 0.35);
  stroke-width: 2.2;
  stroke-dasharray: 6, 6;
}

.spire-path-line.path-visited {
  stroke: rgba(14, 165, 233, 0.7);
  stroke-width: 2.8;
  stroke-dasharray: 8, 4;
}

.spire-path-line.path-selectable {
  stroke: rgba(52, 211, 153, 0.75);
  stroke-width: 3;
  stroke-dasharray: 7, 5;
  filter: drop-shadow(0 0 5px rgba(52, 211, 153, 0.5));
}

.spire-path-line.path-animating {
  stroke: #38bdf8;
  stroke-width: 3.8;
  stroke-dasharray: 8, 6;
  animation: spireDottedFlow 0.8s linear infinite;
  filter: drop-shadow(0 0 8px rgba(56, 189, 248, 0.9));
}

@keyframes spireDottedFlow {
  from { stroke-dashoffset: 28; }
  to { stroke-dashoffset: 0; }
}

.spire-map-node.cleared .node-icon-wrapper {
  border-color: #0ea5e9;
  box-shadow: 0 0 14px rgba(14, 165, 233, 0.45);
  background: rgba(14, 165, 233, 0.18);
}

.cleared-badge {
  position: absolute;
  top: -8px;
  right: -8px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #10b981;
  border: 2px solid #07090e;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 10px rgba(16, 185, 129, 0.6);
  z-index: 10;
}

/* ================= CINEMATIC ENCOUNTER TRANSITION PORTAL ================= */
.arena-cinematic-portal {
  position: fixed;
  inset: 0;
  z-index: 999999;
  background: rgba(4, 7, 14, 0.94);
  backdrop-filter: blur(16px);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  animation: portalFadeIn 0.35s ease-out forwards;
}

@keyframes portalFadeIn {
  0% { opacity: 0; transform: scale(0.96); }
  100% { opacity: 1; transform: scale(1); }
}

.portal-content-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 16px;
  padding: 40px 52px;
  border-radius: 24px;
  background: radial-gradient(circle at 50% 50%, rgba(14, 165, 233, 0.18) 0%, rgba(10, 15, 29, 0.9) 100%);
  border: 1px solid rgba(56, 189, 248, 0.4);
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.95), 0 0 50px rgba(56, 189, 248, 0.3);
}

.portal-pulse-icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(56, 189, 248, 0.16);
  border: 2px solid #38bdf8;
  box-shadow: 0 0 28px rgba(56, 189, 248, 0.55);
  animation: portalPulseGlow 1.2s infinite alternate;
}

@keyframes portalPulseGlow {
  from { transform: scale(0.95); box-shadow: 0 0 16px rgba(56, 189, 248, 0.4); }
  to { transform: scale(1.1); box-shadow: 0 0 36px rgba(56, 189, 248, 0.85); }
}

.portal-badge {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 2px;
  color: #38bdf8;
  padding: 4px 14px;
  background: rgba(56, 189, 248, 0.1);
  border-radius: 999px;
  border: 1px solid rgba(56, 189, 248, 0.35);
}

.portal-title {
  font-size: 28px;
  font-weight: 900;
  letter-spacing: 1.5px;
  color: #f8fafc;
  text-shadow: 0 0 24px rgba(56, 189, 248, 0.6);
  margin: 0;
}

.portal-subtitle {
  font-size: 13.5px;
  color: #94a3b8;
  max-width: 440px;
  line-height: 1.5;
  margin: 0;
}

/* ================= MODALS: EVENT & CAMPFIRE ================= */
.battle-dossier-modal.event-modal,
.battle-dossier-modal.campfire-modal {
  max-width: 640px;
  width: 90%;
}

.event-icon-badge,
.campfire-icon-badge {
  padding: 10px;
  border-radius: 12px;
  background: rgba(56, 189, 248, 0.1);
