}

.campfire-option-card .option-icon-box {
  padding: 12px;
  border-radius: 50%;
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
}

.campfire-option-card h4 {
  font-size: 16px;
  color: #ffffff;
  margin: 0;
}

.campfire-option-card p {
  font-size: 11.5px;
  color: #94a3b8;
  margin: 0;
  line-height: 1.4;
}

.campfire-option-card .option-btn {
  margin-top: 8px;
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(245, 158, 11, 0.2);
