}

.hud-aspirant-crest .crest-rank-tag {
  font-size: 9px;
  font-weight: 800;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.15);
  padding: 1px 6px;
  border-radius: 4px;
}

.hud-vitality-flask {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.35);
  padding: 4px 10px;
  border-radius: 8px;
  box-shadow: 0 0 12px rgba(239, 68, 68, 0.2);
}

.flask-tube-track {
  width: 86px;
  height: 12px;
