/* Animated 3D WebGL Shader Backdrop */
.spire-animated-shader-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  z-index: 0;
  pointer-events: none;
}

.dungeon-particles-overlay {
  position: absolute;
  inset: 0;
  background-image: 
    radial-gradient(1.5px 1.5px at 15% 20%, rgba(56, 189, 248, 0.7), transparent),
    radial-gradient(2px 2px at 35% 65%, rgba(251, 191, 36, 0.6), transparent),
    radial-gradient(1.5px 1.5px at 75% 30%, rgba(244, 63, 94, 0.6), transparent),
    radial-gradient(2px 2px at 85% 80%, rgba(168, 85, 247, 0.7), transparent),
    radial-gradient(1.5px 1.5px at 50% 50%, rgba(255, 255, 255, 0.5), transparent);
  background-size: 250px 250px;
  animation: emberParticlesDrift 20s linear infinite;
  opacity: 0.75;
}

@keyframes emberParticlesDrift {
  0% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-40px) scale(1.04); }
  100% { transform: translateY(-80px) scale(1); }
}

.spire-ground-grid-perspective {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 40%;
  background: 
    linear-gradient(to top, rgba(7, 9, 14, 0.95) 10%, transparent 100%),
    linear-gradient(rgba(56, 189, 248, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(56, 189, 248, 0.08) 1px, transparent 1px);
  background-size: 100% 100%, 40px 40px, 40px 40px;
  perspective: 400px;
  transform: perspective(300px) rotateX(45deg);
  transform-origin: bottom;
  opacity: 0.45;
}

