}

.campfire-embers-particle-field .ember {
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #fbbf24;
  box-shadow: 0 0 8px #f59e0b;
  opacity: 0;
  animation: emberRise 3.5s infinite ease-in;
}

.campfire-embers-particle-field .e1 { left: 48%; bottom: 35%; animation-delay: 0.2s; }
.campfire-embers-particle-field .e2 { left: 52%; bottom: 40%; animation-delay: 1.1s; width: 3px; height: 3px; }
.campfire-embers-particle-field .e3 { left: 55%; bottom: 30%; animation-delay: 1.9s; width: 5px; height: 5px; background: #ef4444; }
.campfire-embers-particle-field .e4 { left: 45%; bottom: 45%; animation-delay: 2.6s; width: 3px; height: 3px; }
.campfire-embers-particle-field .e5 { left: 50%; bottom: 25%; animation-delay: 3.1s; }
.campfire-embers-particle-field .e6 { left: 54%; bottom: 50%; animation-delay: 0.7s; width: 2px; height: 2px; }

@keyframes emberRise {
  0% { transform: translateY(0) scale(1); opacity: 0; }
  20% { opacity: 0.9; }
  80% { opacity: 0.7; }
  100% { transform: translateY(-90px) translateX(-15px) scale(0.2); opacity: 0; }
}

