  border: 1px solid rgba(34, 197, 94, 0.3);
  color: #4ade80;
}

.audit-sync-alert.error {
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #f87171;
}

/* Inventory List */
.audit-inventory-intro {
  font-size: 12.5px;
  color: var(--text-secondary, #cbd5e1);
  line-height: 1.5;
  padding-bottom: 8px;
}

.audit-inventory-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.audit-inventory-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 16px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.07);
}

.audit-inv-icon {
  margin-top: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--accent-color, #38bdf8);
  flex-shrink: 0;
}

.audit-inv-details {
  flex: 1;
}

.audit-inv-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary, #f8fafc);
}

.audit-inv-desc {
  margin-top: 2px;
  font-size: 11.5px;
  color: var(--text-muted, #94a3b8);
  line-height: 1.4;
}

.audit-inv-storage {
  margin-top: 4px;
  font-size: 10.5px;
  color: var(--text-muted, #64748b);
}

.audit-inv-storage code {
  color: var(--accent-color, #38bdf8);
  background: rgba(56, 189, 248, 0.08);
  padding: 1px 4px;
  border-radius: 4px;
}

.audit-inv-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--text-muted, #94a3b8);
  align-self: center;
  flex-shrink: 0;
}

/* History Timeline */
.audit-history-timeline {
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
  padding-left: 18px;
}

.audit-history-timeline::before {
  content: '';
  position: absolute;
  left: 6px;
  top: 6px;
  bottom: 6px;
  width: 2px;
  background: rgba(255, 255, 255, 0.1);
}

.audit-timeline-item {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.audit-timeline-dot {
  position: absolute;
  left: -18px;
  top: 4px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #64748b;
  border: 2px solid #0f172a;
}

.audit-timeline-dot.is-active {
  background: #38bdf8;
  box-shadow: 0 0 8px #38bdf8;
}

.audit-timeline-content {
  flex: 1;
  padding: 10px 14px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.audit-tl-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.audit-tl-title {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--text-primary, #f8fafc);
}

.audit-tl-time {
  font-size: 10.5px;
  color: var(--text-muted, #94a3b8);
}

.audit-tl-desc {
  margin-top: 4px;
  font-size: 11px;
  color: var(--text-muted, #94a3b8);
}

/* Footer */
.audit-modal-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(10, 15, 28, 0.85);
}

.audit-footer-security-note {
  font-size: 9.5px;
  color: var(--text-muted, #64748b);
  letter-spacing: 0.08em;
}

.audit-footer-done-btn {
  padding: 7px 20px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #ffffff;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.audit-footer-done-btn:hover {
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.28);
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .audit-modal-container {
    max-height: 94vh;
  }
  .audit-modal-header {
    padding: 14px 16px;
  }
  .audit-tab-bar {
    padding: 8px 16px;
    overflow-x: auto;
  }
  .audit-modal-body {
    padding: 16px;
  }
  .audit-sync-action-bar {
    flex-direction: column;
    align-items: stretch;
  }
  .audit-sync-now-btn {
    justify-content: center;
  }
  .audit-metrics-grid {
    grid-template-columns: 1fr;
  }
  .audit-modal-footer {
    padding: 12px 16px;
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }
  .audit-footer-done-btn {
    width: 100%;
  }
}






